local M = {
    spellCount = 3281,
    relationshipCount = 8361,
    maximum = 134,
    sourceSHA256 = SOURCE_SHA256,
}

function M.forSpellID(spellID)
    return SCORES[tonumber(spellID)] or 0
end

function M.forEntry(entry)
    if type(entry) ~= "table" then
        return 0
    end
    local score = M.forSpellID(entry.SpellID or entry.spellID)
    for _, spellID in ipairs(entry.Spells or {}) do
        score = math.max(score, M.forSpellID(spellID))
    end
    return score
end

return M

