local SPELL_ID_INTERNAL_ALIASES = {
    [19028] = { 3342, 40601 },
}
local function canonicalSpellID(value)
    local numeric = tonumber(value)
    return SPELL_ID_ALIASES[numeric] or numeric
end

local function decodeSide(value, label)
    local result = {}
    if value == "" then
        return result
    end
    for token in string.gmatch(value .. ".", "([^.]*)%.") do
        if token == "" or not token:match("^[0-9a-z]+$") then
            return nil, "Invalid " .. label .. " spell ID token."
        end
        local spellID = canonicalSpellID(tonumber(token, 36))
        if not isInteger(spellID, 1, MAX_SPELL_ID) then
            return nil, "Invalid " .. label .. " spell ID."
        end
        result[#result + 1] = spellID
    end
    return result
end

local function normalizeOptionalIndexes(rawIndexes, sectionCount, side)
    if type(rawIndexes) ~= "table" then
        return nil, "The v3 plan has no " .. side
            .. " optional-category list."
    end
    local result = {}
    for _, rawIndex in ipairs(rawIndexes) do
        if not isInteger(rawIndex, 1, sectionCount)
            or result[rawIndex] then
            return nil, "Invalid " .. side .. " optional category."
        end
        result[rawIndex] = true
    end
    return result
end

local function normalizeSections(ids, rawSections, side, optionalIndexes)
    if type(rawSections) ~= "table" then
        return nil, "The category plan has no " .. side .. " section list."
    end

    local result = {}
    local cursor = 1
    for index, tuple in ipairs(rawSections) do
        if type(tuple) ~= "table" then
            return nil, "Invalid " .. side .. " category #" .. index .. "."
        end
        local kind = SECTION_KINDS[tuple[1]]
        local count = tuple[2]
        local need = tuple[3]
        local name = tuple[4]
        local anyPolicy = tuple[5]
        if not kind
            or not isInteger(count, 0, PLAN_LIMITS[side])
            or not isInteger(need, 1, 99)
            or type(name) ~= "string"
            or #name > 80
            or (
                anyPolicy ~= nil
                and not (
                    side == "talents"
                    and kind == "any"
                    and anyPolicy == ANY_POLICY_RANK
                )
            ) then
            return nil, "Invalid " .. side .. " category #" .. index .. "."
        end

        local section = {
            kind = kind,
            count = count,
            need = need,
            name = trim(name),
            anyPolicy = anyPolicy == ANY_POLICY_RANK
                and "rank" or "order",
            items = {},
            index = index,
            optional = optionalIndexes
                and optionalIndexes[index] and true or false,
        }
        for _ = 1, count do
            if not ids[cursor] then
                return nil, "The " .. side .. " category counts exceed its spell IDs."
            end
            section.items[#section.items + 1] = {
                spellID = ids[cursor],
                section = section,
            }
            cursor = cursor + 1
        end
        result[#result + 1] = section
    end

    if cursor - 1 ~= #ids then
        return nil, "The " .. side .. " category counts do not cover every spell ID."
    end
    return result
end

local function plainSections(ids)
    local section = {
        kind = "must",
        count = #ids,
        need = 1,
        name = "",
        index = 1,
        items = {},
    }
    for _, spellID in ipairs(ids) do
        section.items[#section.items + 1] = {
            spellID = spellID,
            section = section,
        }
    end
    return { section }
end

local function normalizeSynergies(rawRows, side, targetIDs, finalIDs)
    if type(rawRows) ~= "table" then
        return nil, "The v2 plan has no " .. side .. " synergy list."
    end
    if #rawRows > SYNERGY_LIMIT then
        return nil, "The " .. side .. " synergy list exceeds its safety limit."
    end

    local targetSet = {}
    for _, spellID in ipairs(targetIDs) do
        targetSet[canonicalSpellID(spellID)] = true
    end
    local finalSet = {}
    for _, spellID in ipairs(finalIDs) do
        finalSet[canonicalSpellID(spellID)] = true
    end

    local seen = {}
    local result = {}
    for index, tuple in ipairs(rawRows) do
        if type(tuple) ~= "table" or (#tuple ~= 1 and #tuple ~= 2) then
            return nil, "Invalid " .. side .. " synergy #" .. index .. "."
        end
        local spellID = canonicalSpellID(tuple[1])
        if not isInteger(spellID, 1, MAX_SPELL_ID)
            or seen[spellID]
            or finalSet[spellID] then
            return nil, "Invalid " .. side .. " synergy #" .. index .. "."
        end
        seen[spellID] = true

        local row = {
            spellID = spellID,
            source = "manual",
            targets = {},
            order = index,
        }
        if #tuple == 2 then
            local rawTargets = tuple[2]
            if type(rawTargets) ~= "table"
                or #rawTargets == 0
                or #rawTargets > PLAN_LIMITS[
                    side == "abilities" and "talents" or "abilities"
                ] then
                return nil,
                    "Invalid " .. side .. " Auto synergy targets #"
                        .. index .. "."
            end
            row.source = "auto"
            local targetSeen = {}
            for _, rawTargetSpellID in ipairs(rawTargets) do
                local targetSpellID = canonicalSpellID(rawTargetSpellID)
                if not isInteger(targetSpellID, 1, MAX_SPELL_ID)
                    or not targetSet[targetSpellID]
                    or targetSeen[targetSpellID] then
                    return nil,
                        "Invalid " .. side .. " Auto synergy target #"
                            .. index .. "."
                end
                targetSeen[targetSpellID] = true
                row.targets[#row.targets + 1] = targetSpellID
            end
        end
        result[#result + 1] = row
    end
    return result
end

function M.parse(value, decodePlan)
    value = trim(value)
    if value == "" then
        return nil, "Paste a Season 10 build link first."
    end

    local function tryCustomBuild(value)
        local normalizedValue = value:gsub("%%(%x%x)", function(hex)
            return string.char(tonumber(hex, 16))
        end)
        local customPayload = normalizedValue:match(
            "[#?&]build=v1%.([A-Za-z0-9_-]+)"
        ) or normalizedValue:match("^build=v1%.([A-Za-z0-9_-]+)")
        if not customPayload then return nil end
        if not addon.codec or type(addon.codec.decodePlan) ~= "function" then
            return nil, "This client cannot decode the custom builder link."
        end
        local payload, decodeError = addon.codec.decodePlan(customPayload)
        if type(payload) ~= "table" or payload.v ~= 1 then
            return nil, decodeError or "The custom builder link is invalid."
        end

        local function customIDs(raw, label)
            if type(raw) ~= "table" or #raw > CUSTOM_LIMITS[label] then
                return nil, "The custom " .. label .. " list is too large."
            end
            local ids, seen = {}, {}
            for _, rawID in ipairs(raw) do
                local id = canonicalSpellID(tonumber(rawID))
                if not isInteger(id, 1, MAX_SPELL_ID) then
                    return nil, "The custom " .. label .. " list contains an invalid ID."
                end
                -- Older editable links could contain the same canonical ID
                -- more than once (for example, legacy aliases for one spell).
                -- Keep one target so a stale duplicate cannot blank the planner.
                if not seen[id] then
                    seen[id] = true
                    ids[#ids + 1] = id
                end
            end
            return ids
        end

        local abilities, abilityError = customIDs(payload.abilities, "abilities")
        if not abilities then return nil, abilityError end
        local talents, talentError = customIDs(payload.talents, "talents")
        if not talents then return nil, talentError end
        local statIDs = {
            strength = 84864, agility = 84865, intellect = 84866,
            spirit = 84867, duality = 129243,
        }
        local primaryStat = payload.primaryStat
        if type(primaryStat) == "table" or primaryStat == "" then
            primaryStat = nil
        end
        local primaryStatID = primaryStat
            and statIDs[string.lower(tostring(primaryStat))]
        if primaryStat ~= nil and not primaryStatID then
            return nil, "The custom builder link has an unknown primary-stat selection."
        end
        return {
            version = 1,
            identity = value,
            rules = "s10w60",
            categorized = false,
            primaryStat = primaryStatID,
            primaryStatName = PRIMARY_STATS[primaryStatID],
            abilities = abilities,
            talents = talents,
            sections = { abilities = plainSections(abilities), talents = plainSections(talents) },
            cards = {},
            synergies = {
                abilities = {},
                talents = {},
            },
        }
    end

    local parsed, customError = tryCustomBuild(value)
    if parsed then return parsed end
    if customError then return nil, customError end

    local marker = string.find(value, "#b=", 1, true)
    if marker then
        value = string.sub(value, marker + 3)
        value = value:match("^([^%s]+)") or ""
    elseif string.sub(value, 1, 3) == "#b=" then
        value = string.sub(value, 4)
    end

    local formatVersion, primaryStat, abilitiesText, talentsText, planText = value:match(
        "^([123])%.s10w60%.([0-9a-z]*)~([0-9a-z%.]*)~([0-9a-z%.]*)~([A-Za-z0-9_-]+)$"
    )
    if not formatVersion then
        primaryStat, abilitiesText, talentsText = value:match(
            "^1%.s10w60%.([0-9a-z]*)~([0-9a-z%.]*)~([0-9a-z%.]*)$"
        )
        if primaryStat then
            formatVersion = "1"
        end
    end
    if not formatVersion then
        return nil, "Unsupported build. Copy a Lazy Roller build link from wildcardlogscopier.lazyloafs.workers.dev."
    end
    formatVersion = tonumber(formatVersion)

    local primaryStatID
    if primaryStat ~= "" then
        primaryStatID = tonumber(primaryStat, 36)
        if not PRIMARY_STATS[primaryStatID] then
            return nil, "Unknown Season 10 primary-stat selection."
        end
    end

    local abilities, abilityError = decodeSide(abilitiesText, "ability")
    if not abilities then
        return nil, abilityError
    end
    local talents, talentError = decodeSide(talentsText, "talent")
    if not talents then
        return nil, talentError
    end
    local limits = planText and PLAN_LIMITS or LIMITS
    if #abilities > limits.abilities or #talents > limits.talents then
        return nil, planText
            and "The categorized build is larger than the advisor safety limit."
            or "The plain build exceeds the Season 10 slot limit."
    end

    local abilitySections
    local talentSections
    local cards = {}
    local synergies = {
        abilities = {},
        talents = {},
    }
    if planText then
        if type(decodePlan) ~= "function" then
            return nil, "This client cannot decode the build's category plan."
        end
        local payload, planError = decodePlan(planText)
        if type(payload) ~= "table" then
            return nil, planError or "The build's category plan is unreadable."
        end
        local abilityOptionals
        local talentOptionals
        if formatVersion == 3 then
            abilityOptionals, abilityError = normalizeOptionalIndexes(
                payload.oa,
                type(payload.a) == "table" and #payload.a or 0,
                "abilities"
            )
            if not abilityOptionals then
                return nil, abilityError
            end
            talentOptionals, talentError = normalizeOptionalIndexes(
                payload.ot,
                type(payload.t) == "table" and #payload.t or 0,
                "talents"
            )
            if not talentOptionals then
                return nil, talentError
            end
        elseif payload.oa ~= nil or payload.ot ~= nil then
            return nil, "Optional categories require a v3 build link."
        end
        abilitySections, abilityError = normalizeSections(
            abilities,
            payload.a,
            "abilities",
            abilityOptionals
        )
        if not abilitySections then
            return nil, abilityError
        end
        talentSections, talentError = normalizeSections(
            talents,
            payload.t,
            "talents",
            talentOptionals
        )
        if not talentSections then
            return nil, talentError
        end
        cards = {
            starters = payload.sc or {},
            abilities = payload.ac or {},
            talents = payload.tc or {},
        }
        if formatVersion == 1 then
            if payload.sa ~= nil or payload.st ~= nil then
                return nil, "Synergy metadata requires a v2 build link."
            end
        else
            synergies.abilities, abilityError = normalizeSynergies(
                payload.sa,
                "abilities",
                talents,
                abilities
            )
            if not synergies.abilities then
                return nil, abilityError
            end
            synergies.talents, talentError = normalizeSynergies(
                payload.st,
                "talents",
                abilities,
                talents
            )
            if not synergies.talents then
                return nil, talentError
            end
        end
    else
        abilitySections = plainSections(abilities)
        talentSections = plainSections(talents)
    end

    return {
        version = formatVersion,
        identity = value,
        rules = "s10w60",
        categorized = planText ~= nil,
        primaryStat = primaryStatID,
        primaryStatName = PRIMARY_STATS[primaryStatID],
        abilities = abilities,
        talents = talents,
        sections = {
            abilities = abilitySections,
            talents = talentSections,
        },
        cards = cards,
        synergies = synergies,
    }
end

local function entrySide(entry)
    if entry.Type == "Talent" then
        return "talents"
    end
    if entry.Type == "Ability" or entry.Type == "TalentAbility" then
        return "abilities"
    end
end

local function entryKey(entry)
    return tostring(entry.Type) .. ":" .. tostring(entry.ID)
end

local function targetRank(entry, spellID)
    if type(entry.Spells) == "table" then
        for rank, rankSpellID in ipairs(entry.Spells) do
            if tonumber(rankSpellID) == spellID then
                return rank
            end
        end
    end
    return 1
end

local function resolveEntryBySpellID(api, spellID)
    spellID = canonicalSpellID(spellID)
    local entry = api.getEntryBySpellID(spellID)
    if entry == nil and type(api.getEntryByInternalID) == "function" then
        -- Armory exports and custom builder IDs can be internal entry IDs
        -- rather than rank spell IDs. Resolve those without changing the
        -- normal spell-ID path used by standard Season 10 links.
        for _, internalID in ipairs(SPELL_ID_INTERNAL_ALIASES[spellID] or {}) do
            entry = api.getEntryByInternalID(internalID)
            if entry ~= nil then
                break
            end
        end
        if entry == nil then
            entry = api.getEntryByInternalID(spellID)
        end
    end
    return entry
end

local function displaySpellName(spellID)
    if type(GetSpellInfo) == "function" then
        local name = GetSpellInfo(spellID)
        if type(name) == "string" and name ~= "" then
            return name
        end
    end
    return "Spell #" .. tostring(spellID)
end

local function unresolvedPlanItem(section, side, item, entry, planOrder)
    return {
        spellID = item.spellID,
        entryID = entry and entry.ID or item.spellID,
        entryType = entry and entry.Type
            or (side == "talents" and "Talent" or "Ability"),
        name = entry and entry.Name or displaySpellName(item.spellID),
        side = side,
        section = section,
        sectionKind = section.kind,
        sectionName = section.name,
        sectionIndex = section.index,
        planOrder = planOrder,
        known = false,
        locked = false,
        currentRank = 0,
        maxRank = 1,
        targetRank = 1,
        unresolved = true,
    }
end

local function learnedSpellID(entry, currentRank)
    if type(entry.Spells) == "table" then
        local rank = math.max(1, tonumber(currentRank) or 1)
        return tonumber(entry.Spells[rank])
            or tonumber(entry.Spells[#entry.Spells])
            or tonumber(entry.Spells[1])
    end
    return tonumber(entry.SpellID or entry.spellID)
end

local function reasonText(reason)
    if reason == nil or reason == "" then
        return "the client did not report a reason"
    end
    return tostring(_G and _G[reason] or reason)
end

local function pityPressureFor(api, entry)
    if not api or type(api.getPityPressure) ~= "function" then
        return 0
    end
    local score = tonumber(api.getPityPressure(entry)) or 0
    return math.max(0, math.floor(score))
end

local function newSideState(side)
    return {
        side = side,
        sections = {},
        mustMissing = 0,
        anyDeficit = 0,
        niceMissing = 0,
        unfinishedRequired = 0,
        unfinishedDiscardable = 0,
        knownCount = 0,
        learnedNonbuild = {},
        learnedSynergies = {},
        candidates = {},
        blockedCandidates = {},
    }
end

local function demandFor(state)
    if state.mustMissing > 0 then
        return 1, string.format("%d must-have missing", state.mustMissing)
    end
    if state.anyDeficit > 0 then
        return 2, string.format("%d any-of slot%s missing", state.anyDeficit, state.anyDeficit == 1 and "" or "s")
    end
    if state.unfinishedRequired > 0 then
        return 3, string.format("%d required rank%s unfinished", state.unfinishedRequired, state.unfinishedRequired == 1 and "" or "s")
    end
    if state.niceMissing > 0 then
        return 4, string.format("%d nice-to-keep missing", state.niceMissing)
    end
end

local function candidateSort(left, right)
    if left.activeSynergy ~= right.activeSynergy then
        return not left.activeSynergy
    end
    if left.activeSynergy and right.activeSynergy
        and left.synergyOrder and right.synergyOrder
        and left.synergyOrder ~= right.synergyOrder then
        return left.synergyOrder > right.synergyOrder
    end
    if left.pityRisk ~= right.pityRisk then
        return left.pityRisk
    end
    if left.priority ~= right.priority then
        return left.priority < right.priority
    end
    local leftPressure = tonumber(left.pityPressure) or 0
    local rightPressure = tonumber(right.pityPressure) or 0
    if not left.activeSynergy and not right.activeSynergy
        and leftPressure ~= rightPressure then
        return leftPressure > rightPressure
    end
    if left.planOrder and right.planOrder then
        return left.planOrder > right.planOrder
    end
    return left.knownOrder < right.knownOrder
end

local function learnedNonbuildSort(left, right)
    local leftAvailable = not left.locked and left.canRemove
    local rightAvailable = not right.locked and right.canRemove
    if leftAvailable ~= rightAvailable then
        return leftAvailable
    end
    return candidateSort(left, right)
end

function M.analyze(value, api)
    local parsed, parseError = M.parse(value, api and api.decodePlan)
    local result = {
        ok = false,
        errors = {},
        lockSuggestions = {},
        surplusAnyEntries = {},
        desiredEntries = {},
        knownDesiredEntries = {},
        sides = {
            abilities = newSideState("abilities"),
            talents = newSideState("talents"),
        },
    }
    if not parsed then
        result.errors[1] = parseError
        return result
    end
    result.parsed = parsed

    local optionalEnabled = {}
    local disabledTargetSpellIDs = {}
    for _, side in ipairs({ "abilities", "talents" }) do
        optionalEnabled[side] = {}
        for _, section in ipairs(parsed.sections[side]) do
            local enabled = not section.optional
            if section.optional
                and api
                and type(api.isOptionalCategoryEnabled) == "function" then
                enabled = api.isOptionalCategoryEnabled(
                    parsed.identity,
                    side,
                    section.index
                ) and true or false
            end
            optionalEnabled[side][section.index] = enabled
            if section.optional then
                result.optionalCategories = result.optionalCategories or {}
                result.optionalCategories[#result.optionalCategories + 1] = {
                    side = side,
                    index = section.index,
                    name = section.name,
                    kind = section.kind,
                    need = section.need,
                    count = #section.items,
                    enabled = enabled,
                }
                if not enabled then
                    for _, item in ipairs(section.items) do
                        disabledTargetSpellIDs[item.spellID] = true
                    end
                end
            end
        end
    end
    result.optionalCategories = result.optionalCategories or {}

    local buildEntries = {}
    local buildEntriesByName = {
        abilities = {},
        talents = {},
    }
    local buildItemsBySpellID = {}
    local capstoneSpellID = parsed.talents[#parsed.talents]
    local planOrder = 0
    for _, side in ipairs({ "abilities", "talents" }) do
        local state = result.sides[side]
        for _, section in ipairs(parsed.sections[side]) do
            if not optionalEnabled[side][section.index] then
                -- A disabled optional category is absent from the effective
                -- build. Its learned entries therefore remain ordinary
                -- non-build candidates under the existing policy.
            else
            local sectionState = {
                side = side,
                index = section.index,
                kind = section.kind,
                name = section.name,
                need = section.need,
                anyPolicy = section.anyPolicy or "order",
                count = #section.items,
                held = 0,
                complete = 0,
                items = {},
            }
            state.sections[#state.sections + 1] = sectionState
            for _, item in ipairs(section.items) do
                planOrder = planOrder + 1
                local entry = resolveEntryBySpellID(api, item.spellID)
                local liveSide = entry and entrySide(entry)
                if not entry or not entry.ID or not liveSide then
                    result.errors[#result.errors + 1] = string.format(
                        "Unknown live entry for spell #%d.",
                        item.spellID
                    )
                    -- Keep unresolved custom IDs visible so they can be
                    -- removed from the planner instead of disappearing.
                    sectionState.items[#sectionState.items + 1] =
                        unresolvedPlanItem(
                            sectionState,
                            side,
                            item,
                            entry,
                            planOrder
                        )
                elseif liveSide ~= side then
                    result.errors[#result.errors + 1] = string.format(
                        "%s (#%d) is a live %s entry, not %s.",
                        entry.Name or "Unknown entry",
                        item.spellID,
                        liveSide,
                        side
                    )
                    sectionState.items[#sectionState.items + 1] =
                        unresolvedPlanItem(
                            sectionState,
                            side,
                            item,
                            entry,
                            planOrder
                        )
                else
                    local key = entryKey(entry)
                    local logicalName = string.lower(tostring(entry.Name or ("Entry #" .. entry.ID)))
                    local existing = buildEntriesByName[side][logicalName]
                    if existing then
                        -- Different live IDs with the same name are rank/class variants
                        -- of one logical requirement; any matching ID satisfies it.
                        sectionState.count = math.max(0, sectionState.count - 1)
                        buildItemsBySpellID[item.spellID] = existing
                        if side == "talents" and item.spellID == capstoneSpellID then
                            existing.capstone = true
                        end
                    elseif buildEntries[key] then
                        result.errors[#result.errors + 1] = string.format(
                            "%s appears more than once through rank spell IDs.",
                            entry.Name or ("Entry #" .. entry.ID)
                        )
                    else
                        local known = api.isKnownID(entry.ID)
                        local currentRank, maxRank = 0, type(entry.Spells) == "table" and #entry.Spells or 1
                        if known then
                            if entry.Type == "Talent" then
                                currentRank, maxRank = api.getTalentRankByID(entry.ID)
                                currentRank = tonumber(currentRank) or 1
                                maxRank = tonumber(maxRank) or math.max(currentRank, 1)
                            else
                                currentRank = 1
                                maxRank = 1
                            end
                        end
                        local resolved = {
                            spellID = item.spellID,
                            entryID = entry.ID,
                            entryType = entry.Type,
                            name = entry.Name or ("Spell #" .. item.spellID),
                            side = side,
                            section = sectionState,
                            sectionKind = section.kind,
                            sectionName = section.name,
                            sectionIndex = section.index,
                            planOrder = planOrder,
                            known = known and true or false,
                            locked = known and api.isLockedID(entry.ID) or false,
                            currentRank = currentRank,
                            maxRank = maxRank,
                            targetRank = targetRank(entry, item.spellID),
                             capstone = side == "talents"
                                 and item.spellID == capstoneSpellID,
                        }
                        buildEntries[key] = resolved
                        buildEntriesByName[side][logicalName] = resolved
                        buildItemsBySpellID[item.spellID] = resolved
                        sectionState.items[#sectionState.items + 1] = resolved
                        if resolved.known then
                            sectionState.held = sectionState.held + 1
                            if resolved.currentRank >= resolved.targetRank then
                                sectionState.complete = sectionState.complete + 1
                            end
                        end
                    end
                end
            end
            end
        end
    end

    if #result.errors > 0 then
        return result
    end

    local capstone
    local otherTalentsComplete = true
    for _, section in ipairs(result.sides.talents.sections) do
        for _, item in ipairs(section.items) do
            if item.capstone then
                capstone = item
            elseif not item.known
                or item.currentRank < item.targetRank then
                otherTalentsComplete = false
            end
        end
    end
    local deferCapstone = capstone ~= nil
        and capstone.known
        and not otherTalentsComplete

    local function markDesired(item)
        item.desired = true
        result.desiredEntries[#result.desiredEntries + 1] = item
        if item.known then
            result.knownDesiredEntries[#result.knownDesiredEntries + 1] = item
        end
    end

    for _, side in ipairs({ "abilities", "talents" }) do
        local state = result.sides[side]
        for _, section in ipairs(state.sections) do
            if section.kind == "must" then
                for _, item in ipairs(section.items) do
                    if item.capstone and deferCapstone then
                        item.role = "nonbuild"
                    else
                        markDesired(item)
                    end
                    if item.known and not (item.capstone and deferCapstone) then
                        item.role = "protected"
                        if not item.locked then
                            result.lockSuggestions[#result.lockSuggestions + 1] = item
                        end
                        if item.currentRank < item.targetRank then
                            state.unfinishedRequired = state.unfinishedRequired + 1
                        end
                    elseif not item.known then
                        state.mustMissing = state.mustMissing + 1
                    end
                end
            elseif section.kind == "any" then
                local learned = {}
                for _, item in ipairs(section.items) do
                    if item.known
                        and not (item.capstone and deferCapstone) then
                        learned[#learned + 1] = item
                    end
                end
                if section.anyPolicy == "rank" then
                    table.sort(learned, function(left, right)
                        if left.currentRank ~= right.currentRank then
                            return left.currentRank > right.currentRank
                        end
                        return left.planOrder < right.planOrder
                    end)
                end
                local selected = {}
                local kept = math.min(section.need, #learned)
                for index = 1, kept do
                    selected[learned[index]] = true
                end
                for _, item in ipairs(section.items) do
                    if selected[item] then
                        item.role = "protected"
                        if not item.locked then
                            result.lockSuggestions[#result.lockSuggestions + 1] = item
                        end
                        if item.currentRank < item.targetRank then
                            state.unfinishedRequired = state.unfinishedRequired + 1
                        end
                    elseif item.known then
                        item.role = "excess_any"
                        result.surplusAnyEntries[
                            #result.surplusAnyEntries + 1
                        ] = item
                    else
                        item.role = "unheld_any"
                    end
                end
                local deficit = math.max(0, section.need - kept)
                state.anyDeficit = state.anyDeficit + deficit
                for _, item in ipairs(section.items) do
                    if item.role == "protected"
                        or item.role == "unheld_any" and deficit > 0 then
                        markDesired(item)
                    else
                        item.desired = false
                    end
                end
            else
                for _, item in ipairs(section.items) do
                    if item.capstone and deferCapstone then
                        item.role = "nonbuild"
                    else
                        markDesired(item)
                        item.role = "protected"
                    end
                    if item.known and not (item.capstone and deferCapstone) then
                        if not item.locked then
                            result.lockSuggestions[
                                #result.lockSuggestions + 1
                            ] = item
                        end
                    elseif not item.known then
                        state.niceMissing = state.niceMissing + 1
                    end
                end
            end
        end
    end

    local synergyEntries = {}
    for _, side in ipairs({ "abilities", "talents" }) do
        for _, row in ipairs(parsed.synergies[side] or {}) do
            local entry = resolveEntryBySpellID(api, row.spellID)
            local liveSide = entry and entrySide(entry)
            if not entry or not entry.ID or not liveSide then
                result.errors[#result.errors + 1] = string.format(
                    "Unknown live synergy entry for spell #%d.",
                    row.spellID
                )
            elseif liveSide ~= side then
                result.errors[#result.errors + 1] = string.format(
                    "%s (#%d) is a live %s entry, not a synergy %s entry.",
                    entry.Name or "Unknown entry",
                    row.spellID,
                    liveSide,
                    side
                )
            else
                local key = entryKey(entry)
                if buildEntries[key] then
                    result.errors[#result.errors + 1] = string.format(
                        "%s is both a final-build pick and a synergy.",
                        entry.Name or ("Entry #" .. entry.ID)
                    )
                elseif synergyEntries[key] then
                    result.errors[#result.errors + 1] = string.format(
                        "%s appears more than once in the synergy lists through rank spell IDs.",
                        entry.Name or ("Entry #" .. entry.ID)
                    )
                else
                    local targets = {}
                    local activeTargets = {}
                    for _, targetSpellID in ipairs(row.targets) do
                        local target = buildItemsBySpellID[targetSpellID]
                        local expectedSide = side == "abilities"
                            and "talents" or "abilities"
                        if disabledTargetSpellIDs[targetSpellID] then
                            -- Disabled optional targets cannot activate an
                            -- Auto synergy. Other enabled targets on the same
                            -- helper remain effective.
                        elseif not target or target.side ~= expectedSide then
                            result.errors[#result.errors + 1] = string.format(
                                "Synergy %s has an invalid opposite-side build target #%d.",
                                entry.Name or ("Entry #" .. entry.ID),
                                targetSpellID
                            )
                        else
                            targets[#targets + 1] = target
                            if target.desired and (
                                not target.known
                                or target.currentRank < target.targetRank
                            ) then
                                activeTargets[#activeTargets + 1] = target
                            end
                        end
                    end
                    synergyEntries[key] = {
                        spellID = row.spellID,
                        entryID = entry.ID,
                        entryType = entry.Type,
                        name = entry.Name or ("Spell #" .. row.spellID),
                        side = side,
                        source = row.source,
                        synergyOrder = row.order,
                        targets = targets,
                        activeTargets = activeTargets,
                        active = row.source == "manual"
                            or #activeTargets > 0,
                    }
                end
            end
        end
    end

    if #result.errors > 0 then
        return result
    end

    local knownOrder = 0
    local seenKnown = {}
    local function collectKnown(entries)
        for _, entry in ipairs(entries or {}) do
            local side = entry and entrySide(entry)
            if entry and entry.ID and side then
                local key = entryKey(entry)
                if not seenKnown[key] then
                    seenKnown[key] = true
                    knownOrder = knownOrder + 1
                    local state = result.sides[side]
                    state.knownCount = state.knownCount + 1
                    local buildItem = buildEntries[key]
                    if not buildItem then
                        local logicalName = string.lower(tostring(entry.Name or ("Entry #" .. entry.ID)))
                        buildItem = buildEntriesByName[side][logicalName]
                    end
                    local synergyItem = not buildItem and synergyEntries[key]
                    local activeSynergy = synergyItem
                        and synergyItem.active and true or false
                    local role = buildItem and buildItem.role
                        or activeSynergy and "synergy" or "nonbuild"
                    local priority = discardPriority(role, side)
                    if priority then
                        local locked = api.isLockedID(entry.ID)
                        local candidate = {
                            entryID = entry.ID,
                            entryType = entry.Type,
                            name = entry.Name or ("Entry #" .. entry.ID),
                            side = side,
                            known = true,
                            role = role,
                            priority = priority,
                            locked = locked and true or false,
                            planOrder = buildItem and buildItem.planOrder,
                            knownOrder = knownOrder,
                            activeSynergy = activeSynergy,
                            synergySource = synergyItem
                                and synergyItem.source or nil,
                            synergyOrder = synergyItem
                                and synergyItem.synergyOrder or nil,
                            synergyTargets = activeSynergy
                                and synergyItem.activeTargets or nil,
                            pityPressure = pityPressureFor(api, entry),
                        }
                        if candidate.side == "talents" then
                            local currentRank, maxRank =
                                api.getTalentRankByID(entry.ID)
                            candidate.currentRank = tonumber(currentRank) or 1
                            candidate.maxRank = tonumber(maxRank)
                                or math.max(candidate.currentRank, 1)
                            candidate.unfinished =
                                candidate.currentRank < candidate.maxRank
                            candidate.pityRisk = candidate.unfinished
                        else
                            candidate.currentRank = 1
                            candidate.maxRank = 1
                            candidate.unfinished = false
                            candidate.pityRisk = false
                        end
                        candidate.spellID = learnedSpellID(
                            entry,
                            candidate.currentRank
                        )
                        local canRemove, reason = api.canRemoveByEntryID(entry.ID)
                        candidate.canRemove = canRemove and true or false
                        candidate.reason = reasonText(reason)
                        if buildItem and role == "excess_any" then
                            buildItem.pityPressure = candidate.pityPressure
                        end
                        state = result.sides[candidate.side]
                        if activeSynergy then
                            state.learnedSynergies[
                                #state.learnedSynergies + 1
                            ] = candidate
                        elseif role == "nonbuild" then
                            state.learnedNonbuild[
                                #state.learnedNonbuild + 1
                            ] = candidate
                        end
                        if not candidate.locked and candidate.canRemove then
                            state.candidates[#state.candidates + 1] = candidate
                            if candidate.pityRisk
                                and not candidate.activeSynergy then
                                state.unfinishedDiscardable =
                                    state.unfinishedDiscardable + 1
                            end
                        else
                            state.blockedCandidates[#state.blockedCandidates + 1] = candidate
                        end
                    end
                end
            end
        end
    end
    collectKnown(api.getKnownSpellEntries())
    collectKnown(api.getKnownTalentEntries())

    local recommendations = {}
    for _, side in ipairs({ "abilities", "talents" }) do
        local state = result.sides[side]
        table.sort(state.candidates, candidateSort)
        table.sort(state.learnedNonbuild, learnedNonbuildSort)
        table.sort(state.learnedSynergies, function(left, right)
            return (left.synergyOrder or math.huge)
                < (right.synergyOrder or math.huge)
        end)
        local demandRank, demand = demandFor(state)
        state.demandRank = demandRank
        state.demand = demand
        if demandRank then
            local candidate
            for _, possible in ipairs(state.candidates) do
                if possible.priority <= DISCARD_PRIORITY.synergy then
                    candidate = possible
                    break
                end
            end
            if candidate then
                state.recommendation = {
                    side = side,
                    candidate = candidate,
                    demand = demand,
                    demandRank = demandRank,
                }
                recommendations[#recommendations + 1] = state.recommendation
            end
        end
    end
    table.sort(recommendations, function(left, right)
        if left.candidate.activeSynergy
            ~= right.candidate.activeSynergy then
            return not left.candidate.activeSynergy
        end
        if left.candidate.pityRisk ~= right.candidate.pityRisk then
            return left.candidate.pityRisk
        end
        if left.demandRank ~= right.demandRank then
            return left.demandRank < right.demandRank
        end
        if left.candidate.priority ~= right.candidate.priority then
            return left.candidate.priority < right.candidate.priority
        end
        local leftPressure = tonumber(
            left.candidate.pityPressure
        ) or 0
        local rightPressure = tonumber(
            right.candidate.pityPressure
        ) or 0
        if leftPressure ~= rightPressure then
            return leftPressure > rightPressure
        end
        return left.side < right.side
    end)
    result.recommendations = recommendations
    result.recommendation = recommendations[1]
    result.ok = true
    return result
end

function M.rollOffState(result, side)
    local function count(value)
        value = tonumber(value)
        if not value or value < 0 then
            return 0
        end
        return math.floor(value)
    end
    if side ~= "abilities" and side ~= "talents" then
        return nil
    end
    if not result or not result.ok or not result.sides then
        return nil
    end
    local state = result.sides[side]
    local mustMissing = count(state and state.mustMissing)
    local anyDeficit = count(state and state.anyDeficit)
    local niceMissing = count(state and state.niceMissing)
    local rankIncomplete = side == "talents"
        and count(state and state.unfinishedRequired) or 0
    local missing = mustMissing + anyDeficit + niceMissing
    if not state
        or count(state.knownCount) < LIMITS[side]
        or missing + rankIncomplete == 0
        or #(state.candidates or {}) > 0
        or #(state.blockedCandidates or {}) > 0 then
        return nil
    end

    local eligible = {}
    local eligibleSet = {}
    for _, section in ipairs(state.sections or {}) do
        for _, item in ipairs(section.items or {}) do
            if item.known and item.role == "protected" then
                eligible[#eligible + 1] = item
                eligibleSet[item.entryID] = true
            end
        end
    end
    if #eligible == 0 then
        return nil
    end
    return {
        side = side,
        limit = LIMITS[side],
        knownCount = count(state.knownCount),
        incomplete = rankIncomplete,
        rankIncomplete = rankIncomplete,
        missing = missing,
        mustMissing = mustMissing,
        anyDeficit = anyDeficit,
        niceMissing = niceMissing,
        eligible = eligible,
        eligibleSet = eligibleSet,
    }
end

function M.abilityRollOffState(result)
    return M.rollOffState(result, "abilities")
end

function M.talentRollOffState(result)
    return M.rollOffState(result, "talents")
end

function M.summary(result)
    if not result or not result.parsed then
        return result and result.errors[1] or "Could not analyze build."
    end
    if not result.ok then
        return string.format("Build blocked · %d validation error%s.", #result.errors, #result.errors == 1 and "" or "s")
    end

    local ability = result.sides.abilities
    local talent = result.sides.talents
    local recommendation = result.recommendation
    local nextText = "No safe reroll recommended"
    if recommendation then
        nextText = string.format(
            "Next %s: reroll %s (pity pressure %d)",
            recommendation.side == "talents" and "talent" or "ability",
            recommendation.candidate.name,
            recommendation.candidate.pityPressure or 0
        )
    end
    return string.format(
        "%s · A %d must + %d any missing · T %d must + %d any missing · %d lock suggestion%s · %s",
        result.parsed.primaryStatName or "No primary stat",
        ability.mustMissing,
        ability.anyDeficit,
        talent.mustMissing,
        talent.anyDeficit,
        #result.lockSuggestions,
        #result.lockSuggestions == 1 and "" or "s",
        nextText
    )
