addon.codec = (function()
local M = {}

local BASE64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local JSON_NULL = {}

function M.decodeBase64url(value)
    if type(value) ~= "string" or value:find("[^A-Za-z0-9_-]") then
        return nil, "The category plan is not valid base64url."
    end
    if #value % 4 == 1 then
        return nil, "The category plan has invalid base64url length."
    end
    value = value:gsub("-", "+"):gsub("_", "/")
    value = value .. string.rep("=", (4 - #value % 4) % 4)

    local bits = value:gsub(".", function(character)
        if character == "=" then
            return ""
        end
        local position = BASE64:find(character, 1, true)
        if not position then
            return ""
        end
        local number = position - 1
        local result = ""
        for power = 6, 1, -1 do
            result = result .. (
                number % 2 ^ power - number % 2 ^ (power - 1) > 0
                    and "1"
                    or "0"
            )
        end
        return result
    end)
    return bits:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(byte)
        if #byte ~= 8 then
            return ""
        end
        local number = 0
        for index = 1, 8 do
            if byte:sub(index, index) == "1" then
                number = number + 2 ^ (8 - index)
            end
        end
        return string.char(number)
    end)
end

local function decodeJSON(text)
    local position = 1
    local length = #text

    local function fail(message)
        return nil, string.format(
            "The category plan JSON is unreadable near byte %d: %s.",
            position,
            message
        )
    end

    local function skipWhitespace()
        while position <= length
            and text:sub(position, position):match("%s") do
            position = position + 1
        end
    end

    local function utf8Character(codepoint)
        if codepoint <= 0x7F then
            return string.char(codepoint)
        elseif codepoint <= 0x7FF then
            return string.char(
                0xC0 + math.floor(codepoint / 0x40),
                0x80 + codepoint % 0x40
            )
        elseif codepoint <= 0xFFFF then
            return string.char(
                0xE0 + math.floor(codepoint / 0x1000),
                0x80 + math.floor(codepoint / 0x40) % 0x40,
                0x80 + codepoint % 0x40
            )
        elseif codepoint <= 0x10FFFF then
            return string.char(
                0xF0 + math.floor(codepoint / 0x40000),
                0x80 + math.floor(codepoint / 0x1000) % 0x40,
                0x80 + math.floor(codepoint / 0x40) % 0x40,
                0x80 + codepoint % 0x40
            )
        end
    end

    local function readHexCodepoint()
        local value = text:sub(position, position + 3)
        if #value ~= 4 or not value:match("^%x%x%x%x$") then
            return nil
        end
        position = position + 4
        return tonumber(value, 16)
    end

    local function parseString()
        if text:sub(position, position) ~= '"' then
            return fail("expected a string")
        end
        position = position + 1
        local result = {}
        while position <= length do
            local character = text:sub(position, position)
            position = position + 1
            if character == '"' then
                return table.concat(result)
            elseif character == "\\" then
                local escaped = text:sub(position, position)
                position = position + 1
                local replacements = {
                    ['"'] = '"',
                    ["\\"] = "\\",
                    ["/"] = "/",
                    b = "\b",
                    f = "\f",
                    n = "\n",
                    r = "\r",
                    t = "\t",
                }
                if replacements[escaped] then
                    result[#result + 1] = replacements[escaped]
                elseif escaped == "u" then
                    local codepoint = readHexCodepoint()
                    if not codepoint then
                        return fail("invalid Unicode escape")
                    end
                    if codepoint >= 0xD800 and codepoint <= 0xDBFF then
                        if text:sub(position, position + 1) ~= "\\u" then
                            return fail("incomplete Unicode surrogate pair")
                        end
                        position = position + 2
                        local low = readHexCodepoint()
                        if not low or low < 0xDC00 or low > 0xDFFF then
                            return fail("invalid Unicode surrogate pair")
                        end
                        codepoint = 0x10000
                            + (codepoint - 0xD800) * 0x400
                            + (low - 0xDC00)
                    elseif codepoint >= 0xDC00 and codepoint <= 0xDFFF then
                        return fail("unexpected low Unicode surrogate")
                    end
                    local encoded = utf8Character(codepoint)
                    if not encoded then
                        return fail("invalid Unicode codepoint")
                    end
                    result[#result + 1] = encoded
                else
                    return fail("invalid string escape")
                end
            elseif string.byte(character) < 0x20 then
                return fail("unescaped control character")
            else
                result[#result + 1] = character
            end
        end
        return fail("unterminated string")
    end

    local parseValue

    local function parseNumber()
        local start = position
        if text:sub(position, position) == "-" then
            position = position + 1
        end
        local first = text:sub(position, position)
        if first == "0" then
            position = position + 1
        elseif first:match("[1-9]") then
            repeat
                position = position + 1
            until not text:sub(position, position):match("%d")
        else
            return fail("invalid number")
        end
        if text:sub(position, position) == "." then
            position = position + 1
            if not text:sub(position, position):match("%d") then
                return fail("invalid number fraction")
            end
            repeat
                position = position + 1
            until not text:sub(position, position):match("%d")
        end
        local exponent = text:sub(position, position)
        if exponent == "e" or exponent == "E" then
            position = position + 1
            local sign = text:sub(position, position)
            if sign == "+" or sign == "-" then
                position = position + 1
            end
            if not text:sub(position, position):match("%d") then
                return fail("invalid number exponent")
            end
            repeat
                position = position + 1
            until not text:sub(position, position):match("%d")
        end
        local value = tonumber(text:sub(start, position - 1))
        if not value then
            return fail("invalid number")
        end
        return value
    end

    local function parseArray()
        position = position + 1
        skipWhitespace()
        local result = {}
        if text:sub(position, position) == "]" then
            position = position + 1
            return result
        end
        while position <= length do
            local value, valueError = parseValue()
            if valueError then
                return nil, valueError
            end
            result[#result + 1] = value
            skipWhitespace()
            local separator = text:sub(position, position)
            position = position + 1
            if separator == "]" then
                return result
            elseif separator ~= "," then
                return fail("expected ',' or ']'")
            end
            skipWhitespace()
        end
        return fail("unterminated array")
    end

    local function parseObject()
        position = position + 1
        skipWhitespace()
        local result = {}
        if text:sub(position, position) == "}" then
            position = position + 1
            return result
        end
        while position <= length do
            local key, keyError = parseString()
            if keyError then
                return nil, keyError
            end
            skipWhitespace()
            if text:sub(position, position) ~= ":" then
                return fail("expected ':'")
            end
            position = position + 1
            local value, valueError = parseValue()
            if valueError then
                return nil, valueError
            end
            result[key] = value
            skipWhitespace()
            local separator = text:sub(position, position)
            position = position + 1
            if separator == "}" then
                return result
            elseif separator ~= "," then
                return fail("expected ',' or '}'")
            end
            skipWhitespace()
        end
        return fail("unterminated object")
    end

    function parseValue()
        skipWhitespace()
        local character = text:sub(position, position)
        if character == '"' then
            return parseString()
        elseif character == "[" then
            return parseArray()
        elseif character == "{" then
            return parseObject()
        elseif character == "-" or character:match("%d") then
            return parseNumber()
        elseif text:sub(position, position + 3) == "true" then
            position = position + 4
            return true
        elseif text:sub(position, position + 4) == "false" then
            position = position + 5
            return false
        elseif text:sub(position, position + 3) == "null" then
            position = position + 4
            return JSON_NULL
        end
        return fail("unexpected value")
    end

    local result, resultError = parseValue()
    if resultError then
        return nil, resultError
    end
    skipWhitespace()
    if position <= length then
        return fail("trailing data")
    end
    return result
end

function M.decodePlan(value)
    local json, decodeError = M.decodeBase64url(value)
    if not json then
        return nil, decodeError
    end
    local payload, jsonError = decodeJSON(json)
    if type(payload) ~= "table" then
        return nil, jsonError or "The category plan JSON is unreadable."
    end
    return payload
end

local function encodeJSON(value)
    if value == JSON_NULL then
        return "null"
    end
    local kind = type(value)
    if kind == "number" then
        if value ~= value then
            return "null"
        end
        return tostring(value)
    elseif kind == "boolean" then
        return value and "true" or "false"
    elseif kind == "string" then
        local escaped = value:gsub(
            "[%z\1-\31\"\\]",
            function(character)
                local replacements = {
                    ['"'] = '\\"',
                    ["\\"] = "\\\\",
                    ["\b"] = "\\b",
                    ["\f"] = "\\f",
                    ["\n"] = "\\n",
                    ["\r"] = "\\r",
                    ["\t"] = "\\t",
                }
                return replacements[character]
                    or string.format("\\u%04x", string.byte(character))
            end
        )
        return '"' .. escaped .. '"'
    elseif kind == "table" then
        local isArray = true
        local count = 0
        for key in pairs(value) do
            count = count + 1
            if type(key) ~= "number" or key < 1 or key % 1 ~= 0 then
                isArray = false
                break
            end
        end
        if isArray and count > 0 then
            for index = 1, count do
                if value[index] == nil then
                    isArray = false
                    break
                end
            end
        end
        if isArray then
            local parts = {}
            for index = 1, count do
                parts[#parts + 1] = encodeJSON(value[index])
            end
            return "[" .. table.concat(parts, ",") .. "]"
        end
        local parts = {}
        for key, item in pairs(value) do
            parts[#parts + 1] = encodeJSON(tostring(key))
                .. ":"
                .. encodeJSON(item)
        end
        table.sort(parts)
        return "{" .. table.concat(parts, ",") .. "}"
    end
    return "null"
end

function M.encodeBase64url(value)
    if type(value) ~= "string" then
        return nil, "The payload must be a string."
    end
    local bits = ""
    for position = 1, #value do
        local byte = string.byte(value, position)
        for power = 7, 0, -1 do
            if byte >= 2 ^ power then
                byte = byte - 2 ^ power
                bits = bits .. "1"
            else
                bits = bits .. "0"
            end
        end
    end
    bits = bits .. string.rep("0", (6 - #bits % 6) % 6)
    local encoded = bits:gsub("%d%d%d%d%d%d", function(six)
        local number = 0
        for index = 1, 6 do
            if six:sub(index, index) == "1" then
                number = number + 2 ^ (6 - index)
            end
        end
        return BASE64:sub(number + 1, number + 1)
    end)
    encoded = encoded:gsub("+", "-"):gsub("/", "_")
    return encoded
end

function M.encodeBuildPayload(payload)
    if type(payload) ~= "table" then
        return nil, "A custom build payload is required."
    end
    local ok, json = pcall(encodeJSON, payload)
    if not ok then
        return nil, "The custom build payload could not be serialized."
    end
    local encoded, encodeError = M.encodeBase64url(json)
    if not encoded then
        return nil, encodeError
    end
    return "#build=v1." .. encoded
end

return M

end)()
addon.managedLocks = (function()
local M = {}

local SCHEMA = 1

local function clean(value)
    value = tostring(value or "")
    return value:gsub("[^%w%-%._]", "_")
end

local function contextKey(identity)
    identity = type(identity) == "table" and identity or {}
    local character = identity.guid
    if not character or character == "" then
        character = clean(identity.realm) .. "/" .. clean(identity.name)
    end
    return clean(character) .. "/" .. clean(identity.specID)
end

local function root(db, create)
    if type(db) ~= "table" then
        return nil
    end
    local value = db.managedAnyLocks
    if type(value) ~= "table" or value.schema ~= SCHEMA
        or type(value.contexts) ~= "table" then
        if not create then
            return nil
        end
        value = { schema = SCHEMA, contexts = {} }
        db.managedAnyLocks = value
    end
    return value
end

local function context(db, identity, buildIdentity, create)
    local value = root(db, create)
    if not value then
        return nil
    end
    local key = contextKey(identity)
    local current = value.contexts[key]
    if type(current) ~= "table"
        or current.buildIdentity ~= tostring(buildIdentity or "")
        or type(current.entries) ~= "table" then
        if not create then
            return nil
        end
        current = {
            buildIdentity = tostring(buildIdentity or ""),
            entries = {},
        }
        value.contexts[key] = current
    end
    return current
end

local function targetKey(target)
    if type(target) ~= "table"
        or target.sectionKind ~= "any"
        or (target.side ~= "abilities" and target.side ~= "talents") then
        return nil
    end
    local sectionIndex = tonumber(target.sectionIndex)
    local spellID = tonumber(target.spellID)
    if not sectionIndex or not spellID then
        return nil
    end
    return table.concat({ target.side, sectionIndex, spellID }, ":")
end

function M.prepare(db, identity, buildIdentity)
    return context(db, identity, buildIdentity, true) ~= nil
end

function M.mark(db, identity, buildIdentity, target)
    local key = targetKey(target)
    if not key then
        return false
    end
    local current = context(db, identity, buildIdentity, true)
    current.entries[key] = {
        side = target.side,
        sectionIndex = tonumber(target.sectionIndex),
        spellID = tonumber(target.spellID),
        entryID = tonumber(target.entryID),
    }
    return true
end

function M.isManaged(db, identity, buildIdentity, target, isLocked)
    local key = targetKey(target)
    local current = key and context(db, identity, buildIdentity, false) or nil
    local record = current and current.entries[key]
    if not record then
        return false
    end
    if type(isLocked) == "function" and not isLocked(target.entryID) then
        current.entries[key] = nil
        return false
    end
    record.entryID = tonumber(target.entryID)
    return true
end

function M.clearTarget(db, identity, buildIdentity, target)
    local key = targetKey(target)
    local current = key and context(db, identity, buildIdentity, false) or nil
    if not current or not current.entries[key] then
        return false
    end
    current.entries[key] = nil
    return true
end

function M.clearEntryID(db, identity, entryID)
    local value = root(db, false)
    local current = value and value.contexts[contextKey(identity)]
    if type(current) ~= "table" or type(current.entries) ~= "table" then
        return false
    end
    local removed = false
    entryID = tonumber(entryID)
    for key, record in pairs(current.entries) do
        if tonumber(record and record.entryID) == entryID then
            current.entries[key] = nil
            removed = true
        end
    end
    return removed
end

function M.replace(db, identity, buildIdentity, targets)
    local current = context(db, identity, buildIdentity, true)
    current.entries = {}
    for _, target in ipairs(targets or {}) do
        local key = targetKey(target)
        if key then
            current.entries[key] = {
                side = target.side,
                sectionIndex = tonumber(target.sectionIndex),
                spellID = tonumber(target.spellID),
                entryID = tonumber(target.entryID),
            }
        end
    end
    return true
end

return M

end)()
addon.controllerModule = (function()
local M = {}

local function normalizeCount(value)
    value = tonumber(value)
    if not value or value < 0 then
        return 0
    end
    return math.floor(value)
end

local function normalizeSessionLimit(value)
    value = tonumber(value)
    if not value or value <= 0 then
        return nil
    end
    return math.floor(value)
end

local function normalizeHighRollFloors(value)
    value = type(value) == "table" and value or {}
    return {
        abilities = normalizeCount(value.abilities),
        talents = normalizeCount(value.talents),
    }
end

local function normalizeRollSides(value)
    value = type(value) == "table" and value or {}
    return {
        abilities = value.abilities ~= false,
        talents = value.talents ~= false,
    }
end

local function highRollCompletionReason(status)
    local parts = {}
    for _, side in ipairs({ "abilities", "talents" }) do
        local current = status and status[side]
        if current and current.reached then
            local singular = side == "abilities" and "ability" or "talent"
            parts[#parts + 1] = string.format(
                "%d non-build %s%s remain%s (floor %d)",
                current.count,
                singular,
                current.count == 1 and "" or "s",
                current.count == 1 and "s" or "",
                current.floor
            )
        end
    end
    if #parts == 0 then
        return nil
    end
    return "High-roll protection reached: "
        .. table.concat(parts, "; ") .. "."
end

local function normalizeBalances(value)
    if type(value) ~= "table" then
        return nil
    end
    return {
        abilities = normalizeCount(value.abilities),
        talents = normalizeCount(value.talents),
        shared = normalizeCount(value.shared),
        specID = value.specID,
    }
end

local function abilityBalance(balances)
    return balances.abilities + balances.shared
end

local function sideNoun(side)
    return side == "abilities" and "ability" or "talent"
end

local function candidatePriority(candidate)
    return tonumber(candidate and candidate.priority) or math.huge
end

local function pressureSourceCount(state, recommendation)
    local selected = recommendation and recommendation.candidate
    if not selected or selected.activeSynergy then
        return 0
    end

    local selectedPriority = candidatePriority(selected)
    local count = 0
    local seen = {}
    for _, candidate in ipairs(state and state.candidates or {}) do
        if not candidate.activeSynergy
            and candidatePriority(candidate) == selectedPriority
            and normalizeCount(candidate.pityPressure) > 0 then
            local key = candidate.entryID or candidate
            if not seen[key] then
                seen[key] = true
                count = count + 1
            end
        end
    end
    return count
end

local function messageFor(reason)
    if reason == nil or reason == "" then
        return "the client did not report a reason"
    end
    return tostring(_G and _G[reason] or reason)
end

function M.new(core, api, observer)
    local controller = {
        core = core,
        api = api,
        observer = observer or function() end,
        running = false,
        paused = false,
        worldSuspended = false,
        phase = "idle",
        link = "",
        sessionLimit = nil,
        highRollFloors = {
            abilities = 0,
            talents = 0,
        },
        rollSides = {
            abilities = true,
            talents = true,
        },
        allowStandardTalentScrolls = false,
        rollsSpent = 0,
        pendingLockID = nil,
        pendingLockName = nil,
        pendingLockAttempts = 0,
        pendingLockTarget = nil,
        pendingUnlockID = nil,
        pendingUnlockName = nil,
        pendingUnlockAttempts = 0,
        pendingUnlockTarget = nil,
        pendingRoll = nil,
        lastResult = nil,
        upgradeResults = {},
        scrollsAtStart = nil,
        rollsBySide = {
            abilities = 0,
            talents = 0,
        },
        lastSchedule = nil,
        lockSync = nil,
        sessionLearned = {},
        sessionLockedIDs = {},
        managedBuildIdentity = nil,
        oneShotRollOff = nil,
    }

    function controller:notify(kind, text, data)
        self.observer(kind, text, data, self)
    end

    function controller:snapshot()
        return {
            running = self.running,
            paused = self.paused,
            worldSuspended = self.worldSuspended,
            phase = self.phase,
            sessionLimit = self.sessionLimit,
            highRollFloors = self.highRollFloors,
            rollSides = self.rollSides,
            allowStandardTalentScrolls =
                self.allowStandardTalentScrolls,
            rollsSpent = self.rollsSpent,
            pendingLockID = self.pendingLockID,
            pendingLockName = self.pendingLockName,
            pendingLockAttempts = self.pendingLockAttempts,
            pendingLockTarget = self.pendingLockTarget,
            pendingUnlockID = self.pendingUnlockID,
            pendingUnlockName = self.pendingUnlockName,
            pendingUnlockAttempts = self.pendingUnlockAttempts,
            pendingUnlockTarget = self.pendingUnlockTarget,
            pendingRoll = self.pendingRoll,
            lastResult = self.lastResult,
            upgradeResults = self.upgradeResults,
            scrollsAtStart = self.scrollsAtStart,
            rollsBySide = self.rollsBySide,
            lastSchedule = self.lastSchedule,
            lockSync = self.lockSync,
            sessionLearned = self.sessionLearned,
            sessionLockedIDs = self.sessionLockedIDs,
            managedBuildIdentity = self.managedBuildIdentity,
            oneShotRollOff = self.oneShotRollOff,
