    end

    function controller:resetForSpecializationChange(reason)
        local hadSession = self.running
            or self.paused
            or self.worldSuspended
            or self.pendingLockID ~= nil
            or self.pendingUnlockID ~= nil
            or self.pendingRoll ~= nil
            or self.oneShotRollOff ~= nil
            or self.lockSync ~= nil

        -- A specialization change invalidates every live entry, balance, and
        -- pending mutation captured by this controller. Drop local ownership
        -- immediately so late events/watchdogs from the previous
