        self.sessionLimit = nil
        self.highRollFloors = {
            abilities = 0,
            talents = 0,
        }
        self.rollSides = {
            abilities = true,
            talents = true,
        }
        self.allowStandardTalentScrolls = false
        self.rollsSpent = 0
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.pendingRoll = nil
        self.lastResult = nil
        self.upgradeResults = {}
        self.scrollsAtStart = nil
        self.rollsBySide = {
            abilities = 0,
            talents = 0,
        }
        self.lastSchedule = nil
        self.lockSync = nil
        self.sessionLearned = {}
        self.sessionLockedIDs = {}
        self.managedBuildIdentity = nil
        self.oneShotRollOff = nil

        if hadSession then
            self:notify(
                "specialization_reset",
                reason
                    or "Specialization changed; the previous auto-roll session was reset."
            )
        end
        return hadSession
    end

    function controller:pause(reason)
        if not self.running then
            return false, "Auto-roll is not running."
        end
        self.running = false
        self.paused = true
        if self.phase == "ready"
            or self.phase == "locking"
            or self.phase == "unlocking" then
            self.phase = "paused"
        end
        self:notify(
            "paused",
            reason
                or "Paused. Any already-requested roll may finish, but no next roll will start."
        )
        return true
    end

    function controller:suspendForWorld()
        if self.worldSuspended then
            return false
        end
        if not self.running
            and not self.paused
            and not self.pendingRoll
            and not self.pendingLockID
            and not self.pendingUnlockID then
            return false
        end
        self.worldSuspended = true
        self:notify(
            "zone_waiting",
            "Loading screen detected; preserving the session without issuing mutations."
        )
        return true
    end

    function controller:resumeAfterWorld()
        if not self.worldSuspended then
            return true
        end
        self.worldSuspended = false

        local ensureContext = self.api.ensureContextReady
            or self.api.ensureReady
        local ready, readyError = ensureContext()
        if not ready then
            self:stop(
                "The preserved session could not continue after zoning: "
                    .. tostring(readyError or "the game context is unavailable"),
                "error"
            )
            return false, readyError
        end

        local balances, balanceError = self:readScrollBalances()
        if not balances then
            self:stop(
                "The preserved session could not read scroll balances after zoning: "
                    .. tostring(balanceError or "unknown balance error"),
                "error"
            )
            return false, balanceError
        end
        if self.scrollsAtStart
            and self.scrollsAtStart.specID
            and balances.specID ~= self.scrollsAtStart.specID then
            self:stop(
                "The active specialization changed while zoning; auto-roll stopped.",
                "stopped"
            )
            return false, "The active specialization changed."
        end

        self:notify(
            "zone_ready",
            self.running
                and "Zoning complete; live state revalidated and auto-roll is continuing."
                or "Zoning complete; live state revalidated and the session remains paused."
        )

        if self.pendingLockID then
            local target = self.pendingLockTarget
            if target and target.rollOffUnlockBarrier then
                -- A counter-lock queued behind an in-flight roll-off unlock
                -- cannot use one post-zone state read as completion. Resume
                -- the same two-observation watchdog barrier instead.
                self:onLockWatch(self.pendingLockID)
            elseif self.api.isLockedID(self.pendingLockID) then
                self:completePendingLock(self.pendingLockID)
            elseif self.running then
                self:armLockWatch(self.pendingLockID)
            end
            return true
        end

        if self.pendingUnlockID then
            if not self.api.isLockedID(self.pendingUnlockID) then
                self:completePendingUnlock(self.pendingUnlockID)
            elseif self.running then
                self:armUnlockWatch(self.pendingUnlockID)
            end
            return true
        end

        if self.pendingRoll then
            if self.phase == "waiting_unlearn" then
                if self.running then
                    self:armUnlearnWatch(self.pendingRoll)
                end
            elseif self.phase == "waiting_learn"
                or self.phase == "waiting_bonus_learn" then
                self:armLearnWatch(self.pendingRoll)
            elseif self.phase ~= "finishing_reveal" then
                self:stop(
                    "The preserved roll had an unknown phase after zoning; stopped without another mutation.",
                    "error"
                )
                return false, "Unknown preserved roll phase."
            end
            return true
        end

        self.phase = self.running and "ready" or "paused"
        self:step()
        return true
    end

    function controller:analyze()
        return self.core.analyze(self.link, self.api)
    end

    function controller:getRollOffState(result, side)
        if self.core.rollOffState then
            return self.core.rollOffState(result, side)
        elseif side == "abilities" and self.core.abilityRollOffState then
            return self.core.abilityRollOffState(result)
        elseif side == "talents" and self.core.talentRollOffState then
            return self.core.talentRollOffState(result)
        end
    end

    function controller:getRollOffTarget(result, side, entryID)
        local state = self:getRollOffState(result, side)
        if not state then
            return nil, nil
        end
        for _, item in ipairs(state.eligible or {}) do
            if item.entryID == entryID and item.side == side then
                return item, state
            end
        end
        return nil, state
    end

    function controller:failLockSync(reason)
        self.lockSync = nil
        self:notify("sync_error", reason or "Desired-lock synchronization failed.")
    end

    function controller:cancelLockSync(reason)
        if not self.lockSync then
            return
        end
        self.lockSync = nil
        self:notify(
            "sync_stopped",
            reason or "Desired-lock synchronization stopped."
        )
    end

    function controller:deferLockSync(sync, callback)
        if type(self.api.deferLockSync) == "function" then
            self.api.deferLockSync(function()
                if self.lockSync == sync then
                    callback()
                end
            end)
        elseif self.lockSync == sync then
            callback()
        end
    end

    function controller:verifyLockSync(sync)
        if self.lockSync ~= sync then
            return
        end
        local corrections = 0
        local lockedDesired = 0
        for _, target in ipairs(sync.knownEntries) do
            local shouldLock = sync.desiredSet[target.entryID] == true
                and self.api.isKnownID(target.entryID)
            local isLocked = self.api.isLockedID(target.entryID)
            if shouldLock and isLocked then
                lockedDesired = lockedDesired + 1
            elseif shouldLock and not isLocked then
                corrections = corrections + 1
                self.api.lockID(target.entryID)
            elseif not shouldLock and isLocked then
                corrections = corrections + 1
                self.api.unlockID(target.entryID)
            end
        end

        if corrections == 0 then
            local unlocked = sync.unlockRequests
            if type(self.api.replaceManagedAnyLocks) == "function" then
                self.api.replaceManagedAnyLocks(
                    sync.buildIdentity,
                    sync.desiredEntries
                )
            end
            self.lockSync = nil
            self:notify(
                "sync_complete",
                string.format(
                    "Desired locks synchronized: %d unlock request%s sent, %d desired entr%s locked.",
                    unlocked,
                    unlocked == 1 and "" or "s",
                    lockedDesired,
                    lockedDesired == 1 and "y" or "ies"
                )
            )
            return
        end

        sync.verifyPass = sync.verifyPass + 1
        if sync.verifyPass >= 3 then
            self:failLockSync(
                string.format(
                    "Lock synchronization still had %d mismatched entr%s after three verification passes.",
                    corrections,
                    corrections == 1 and "y" or "ies"
                )
            )
            return
        end
        self:notify(
            "sync_retry",
            string.format(
                "Correcting %d lock mismatch%s (verification %d/3).",
                corrections,
                corrections == 1 and "" or "es",
                sync.verifyPass + 1
            )
        )
        self:deferLockSync(sync, function()
            self:verifyLockSync(sync)
        end)
    end

    function controller:lockDesiredBatch(sync)
        if self.lockSync ~= sync then
            return
        end
        sync.phase = "locking"
        local requested = 0
        for _, target in ipairs(sync.desiredEntries) do
            if self.api.isKnownID(target.entryID)
                and not self.api.isLockedID(target.entryID) then
                self.api.lockID(target.entryID)
                requested = requested + 1
            end
        end
        sync.lockRequests = requested
        sync.phase = "verifying"
        self:notify(
            "sync_locking",
            string.format(
                "Submitted %d desired lock request%s; verifying final lock state.",
                requested,
                requested == 1 and "" or "s"
            )
        )
        self:deferLockSync(sync, function()
            self:verifyLockSync(sync)
        end)
    end

    function controller:startLockSync(link)
        if self.running or self.paused
            or self.pendingRoll or self.pendingLockID
            or self.pendingUnlockID then
            return false, "Stop the auto-roll session before changing all locks."
        end
        if self.lockSync then
            return false, "Desired-lock synchronization is already running."
        end
        local ready, readyError = self.api.ensureReady()
        if not ready then
            return false, readyError
        end
        local result = self.core.analyze(tostring(link or ""), self.api)
        if not result.ok then
            return false,
                result.errors and result.errors[1]
                    or "Build validation failed."
        end

        local knownEntries =
            self.api.getKnownLockEntries
                and self.api.getKnownLockEntries() or {}
        local seen = {}
        local normalizedKnown = {}
        for _, entry in ipairs(knownEntries) do
            local entryID = entry.entryID or entry.ID
            if entryID and not seen[entryID] then
                seen[entryID] = true
                normalizedKnown[#normalizedKnown + 1] = {
                    entryID = entryID,
                    name = entry.name or entry.Name
                        or ("Entry #" .. tostring(entryID)),
                }
            end
        end

        local desiredEntries = {}
        local desiredSet = {}
        for _, desired in ipairs(result.knownDesiredEntries or {}) do
            desiredSet[desired.entryID] = true
            desiredEntries[#desiredEntries + 1] = {
                entryID = desired.entryID,
                name = desired.name,
                side = desired.side,
                spellID = desired.spellID,
                sectionKind = desired.sectionKind,
                sectionIndex = desired.sectionIndex,
            }
            if not seen[desired.entryID] then
                seen[desired.entryID] = true
                normalizedKnown[#normalizedKnown + 1] =
                    desiredEntries[#desiredEntries]
            end
        end

        self.lockSync = {
            phase = "unlocking",
            knownEntries = normalizedKnown,
            desiredEntries = desiredEntries,
            desiredSet = desiredSet,
            unlockRequests = 0,
            lockRequests = 0,
            verifyPass = 0,
            buildIdentity = result.parsed and result.parsed.identity,
        }
        local sync = self.lockSync
        for _, target in ipairs(normalizedKnown) do
            if self.api.isLockedID(target.entryID) then
                self.api.unlockID(target.entryID)
                sync.unlockRequests = sync.unlockRequests + 1
            end
        end
        self:notify(
            "sync_started",
            string.format(
                "Submitted %d unlock request%s in one batch; %d known desired entr%s will be locked next.",
                sync.unlockRequests,
                sync.unlockRequests == 1 and "" or "s",
                #desiredEntries,
                #desiredEntries == 1 and "y" or "ies"
            )
        )
        self:deferLockSync(sync, function()
            self:lockDesiredBatch(sync)
        end)
        return true
    end

    function controller:readScrollBalances()
        if type(self.api.getScrollBalances) ~= "function" then
            return nil, "The specialization scroll balances are unavailable."
        end
        local balances, balanceError = self.api.getScrollBalances()
        balances = normalizeBalances(balances)
        if not balances then
            return nil, balanceError
                or "The specialization scroll balances could not be read."
        end
        return balances
    end

    function controller:highRollStatus(result, floors, rollSides)
        floors = normalizeHighRollFloors(floors or self.highRollFloors)
        rollSides = normalizeRollSides(rollSides or self.rollSides)
        local status = {
            anyReached = false,
        }
        for _, side in ipairs({ "abilities", "talents" }) do
            local state = result.sides[side]
            local count = #(state.learnedNonbuild or {})
            local floor = floors[side]
            local orderedAbilityDisplacement = side == "abilities"
                and state.recommendation
                and state.recommendation.candidate
                and state.recommendation.candidate.role == "excess_any"
            local reached = rollSides[side]
                and floor > 0
                and count <= floor
                and state.recommendation ~= nil
                and not orderedAbilityDisplacement
            status[side] = {
                count = count,
                floor = floor,
                reached = reached,
            }
            status.anyReached = status.anyReached or reached
        end
        status.reason = highRollCompletionReason(status)
        return status
    end

    function controller:selectRecommendation(
        result,
        session,
        highRollFloors,
        allowStandardTalentScrolls,
        rollSides
    )
        local balances, balanceError = self:readScrollBalances()
        if not balances then
            return nil, nil, balanceError
        end

        local baseline = session and self.scrollsAtStart or balances
        baseline = normalizeBalances(baseline) or balances
        local spent = session and self.rollsBySide or {
            abilities = 0,
            talents = 0,
        }
        rollSides = normalizeRollSides(rollSides or self.rollSides)
        local highRoll = self:highRollStatus(
            result,
            highRollFloors,
            rollSides
        )
        local originalAbilityRecommendation =
            rollSides.abilities
                and result.sides.abilities.recommendation or nil
        local originalTalentRecommendation =
            rollSides.talents
                and result.sides.talents.recommendation or nil
        local abilityRecommendation = not highRoll.abilities.reached
            and originalAbilityRecommendation or nil
        local talentRecommendation = not highRoll.talents.reached
            and originalTalentRecommendation or nil
        local availableAbilities = abilityBalance(balances)
        local baselineAbilities = abilityBalance(baseline)
        local abilityEligible = abilityRecommendation ~= nil
            and availableAbilities > 0
        if allowStandardTalentScrolls == nil then
            allowStandardTalentScrolls =
                self.allowStandardTalentScrolls
        end
        allowStandardTalentScrolls =
            allowStandardTalentScrolls and true or false
        local standardTalentFallback = talentRecommendation ~= nil
            and allowStandardTalentScrolls
            and balances.talents <= 0
            and balances.shared > 0
        local talentEligible = talentRecommendation ~= nil
            and (
                balances.talents > 0
                or standardTalentFallback
            )
        local deferredSynergySide
        if abilityEligible and talentEligible then
            local abilitySynergy = abilityRecommendation.candidate
                and abilityRecommendation.candidate.activeSynergy
                and true or false
            local talentSynergy = talentRecommendation.candidate
                and talentRecommendation.candidate.activeSynergy
                and true or false
            if abilitySynergy ~= talentSynergy then
                if abilitySynergy then
                    abilityEligible = false
                    deferredSynergySide = "abilities"
                else
                    talentEligible = false
                    deferredSynergySide = "talents"
                end
            end
        end
        local rollsAtStart = baselineAbilities + baseline.talents
        local schedule = {
            balances = balances,
            baseline = baseline,
            availableAbilities = availableAbilities,
            baselineAbilities = baselineAbilities,
            spent = {
                abilities = spent.abilities or 0,
                talents = spent.talents or 0,
            },
            targetAbilityShare = rollsAtStart > 0
                and baselineAbilities / rollsAtStart or 0,
            targetTalentShare = rollsAtStart > 0
                and baseline.talents / rollsAtStart or 0,
            highRoll = highRoll,
            rollSides = rollSides,
            allowStandardTalentScrolls = allowStandardTalentScrolls,
            standardTalentFallback = standardTalentFallback,
            deferredSynergySide = deferredSynergySide,
        }

        if abilityEligible and talentEligible then
            schedule.pressureSources = {
                abilities = pressureSourceCount(
                    result.sides.abilities,
                    abilityRecommendation
                ),
                talents = pressureSourceCount(
                    result.sides.talents,
                    talentRecommendation
                ),
            }
        end

        if talentEligible
            and talentRecommendation.candidate.pityRisk
            and not talentRecommendation.candidate.activeSynergy then
            schedule.side = "talents"
            schedule.reason = "unfinished discardable talent has first priority"
            return talentRecommendation, schedule
        end

        -- Generic Scrolls of Fortune are also the ability side's flexible
        -- currency. Once the player explicitly opts to spend them on talents,
        -- honor that intent before ratio scheduling so the shared pool cannot
        -- be consumed by abilities while a safe talent target still exists.
        if standardTalentFallback and talentEligible then
            schedule.side = "talents"
            schedule.reason =
                "standard-scroll talent fallback was explicitly enabled"
            return talentRecommendation, schedule
        end

        if not abilityEligible and not talentEligible then
            if not rollSides.abilities and not rollSides.talents then
                schedule.reason = "No roll types are enabled."
                return nil, schedule, schedule.reason
            end
            if abilityRecommendation or talentRecommendation then
                schedule.reason = string.format(
                    "No usable ability or talent scroll remains for a safe target."
                )
                return nil, schedule, schedule.reason
            end
            if highRoll.anyReached then
                schedule.reason = highRoll.reason
                schedule.highRollComplete = true
                return nil, schedule
            end
            schedule.reason = "no safe reroll recommendation remains"
            return nil, schedule
        end

        if abilityEligible and talentEligible then
            local abilitySources = schedule.pressureSources.abilities
            local talentSources = schedule.pressureSources.talents
            if abilitySources ~= talentSources then
                local pressureSide = abilitySources > talentSources
                    and "abilities" or "talents"
                schedule.side = pressureSide
                schedule.pressureDecision = "count"
                schedule.reason = string.format(
                    "more %s pressure sources",
                    pressureSide == "abilities" and "Ability" or "Talent"
                )
                return pressureSide == "abilities"
                    and abilityRecommendation or talentRecommendation,
                    schedule
            end
        end

        local side
        if abilityEligible and talentEligible then
            local nextPaid = schedule.spent.abilities
                + schedule.spent.talents
                + 1
            local abilityDebt = nextPaid * schedule.targetAbilityShare
                - schedule.spent.abilities
            local talentDebt = nextPaid * schedule.targetTalentShare
                - schedule.spent.talents
            side = abilityDebt >= talentDebt and "abilities" or "talents"
            schedule.abilityDebt = abilityDebt
            schedule.talentDebt = talentDebt
            if schedule.pressureSources then
                schedule.pressureDecision = "ratio"
                schedule.reason =
                    "pressure sources tied; behind the specialization scroll ratio"
            else
                schedule.reason = "behind the specialization scroll ratio"
            end
        elseif abilityEligible then
            side = "abilities"
            if deferredSynergySide then
                schedule.reason =
                    "ordinary funded discards precede active synergies"
            elseif talentRecommendation then
                schedule.reason = abilityRecommendation.candidate
                    and abilityRecommendation.candidate.activeSynergy
                    and "talent scrolls are unavailable; continuing abilities with active synergies"
                    or "talent scrolls are unavailable"
            else
                schedule.reason = "only abilities have a safe useful target"
            end
        else
            side = "talents"
            if deferredSynergySide then
                schedule.reason =
                    "ordinary funded discards precede active synergies"
            elseif abilityRecommendation then
                schedule.reason = talentRecommendation.candidate
                    and talentRecommendation.candidate.activeSynergy
                    and "ability scrolls are unavailable; continuing talents with active synergies"
                    or "ability scrolls are unavailable"
            else
                schedule.reason = "only talents have a safe useful target"
            end
        end
        schedule.side = side
        return side == "abilities"
            and abilityRecommendation or talentRecommendation,
            schedule
    end

    function controller:start(
        link,
        sessionLimit,
        highRollFloors,
        allowStandardTalentScrolls,
        rollSides
    )
        if self.lockSync then
            return false, "Wait for desired-lock synchronization to finish."
        end
        if self.running then
            return false, "Auto-roll is already running."
        end
        local ready, readyError = self.api.ensureReady()
        if not ready then
            return false, readyError
        end
        local balances, balanceError = self:readScrollBalances()
        if not balances then
            return false, balanceError
        end
        if abilityBalance(balances) + balances.talents == 0 then
            return false, string.format(
                "No ability or talent Scrolls of Fortune remain."
            )
        end
        rollSides = normalizeRollSides(rollSides)
        if not rollSides.abilities and not rollSides.talents then
            return false, "Enable Abilities, Talents, or both before starting."
        end
        self.link = tostring(link or "")
        self.sessionLimit = normalizeSessionLimit(sessionLimit)
        self.highRollFloors = normalizeHighRollFloors(highRollFloors)
        self.rollSides = rollSides
        self.allowStandardTalentScrolls =
            allowStandardTalentScrolls and true or false
        self.rollsSpent = 0
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.pendingRoll = nil
        self.lastResult = nil
        self.upgradeResults = {}
        self.scrollsAtStart = balances
        self.rollsBySide = {
            abilities = 0,
            talents = 0,
        }
        self.lastSchedule = nil
        self.sessionLearned = {}
        self.sessionLockedIDs = {}
        self.managedBuildIdentity = nil
        self.oneShotRollOff = nil
        self.running = true
        self.paused = false
        self.worldSuspended = false
        self.phase = "ready"
        self:notify(
            "started",
            string.format(
                "%s Roll types: %s. High-roll floors: A %d / T %d (0 = exact). Standard-scroll talent fallback: %s.",
                self.sessionLimit
                    and string.format(
                        "Started single-roll automation with a limit of %d paid roll%s.",
                        self.sessionLimit,
                        self.sessionLimit == 1 and "" or "s"
                    )
                    or "Started unlimited single-roll automation.",
                self.rollSides.abilities and self.rollSides.talents
                    and "Abilities and Talents"
                    or self.rollSides.abilities
                        and "Abilities only" or "Talents only",
                self.highRollFloors.abilities,
                self.highRollFloors.talents,
                self.allowStandardTalentScrolls and "enabled" or "disabled"
            )
        )
        self:step()
        return true
    end

    function controller:startRollOffOnce(
        link,
        side,
        entryID,
        allowStandardTalentScrolls
    )
        if side ~= "abilities" and side ~= "talents" then
            return false, "Choose either an ability or a talent to roll off."
        end
        if self.lockSync then
            return false, "Wait for desired-lock synchronization to finish."
        end
        if self.running or self.paused
            or self.pendingRoll or self.pendingLockID
            or self.pendingUnlockID or self.oneShotRollOff then
            return false, "Another single-roll action is already active."
        end
        local ready, readyError = self.api.ensureReady()
        if not ready then
            return false, readyError
        end
        local balances, balanceError = self:readScrollBalances()
        if not balances then
            return false, balanceError
        end
        allowStandardTalentScrolls =
            side == "talents" and allowStandardTalentScrolls and true or false
        if side == "abilities" then
            if abilityBalance(balances) <= 0 then
                return false,
                    "No Ability or standard Scroll of Fortune remains."
            end
        else
            local availableTalentCurrency = balances.talents
                + (allowStandardTalentScrolls and balances.shared or 0)
            if availableTalentCurrency <= 0 then
                return false,
                    allowStandardTalentScrolls
                        and "No Talent or standard Scroll of Fortune remains."
                        or "No Talent Scrolls remain. Enable standard-scroll talent fallback to use a standard Scroll of Fortune."
            end
        end

        local selectedLink = tostring(link or "")
        local result = self.core.analyze(selectedLink, self.api)
        if not result.ok then
            return false,
                result.errors and result.errors[1]
                    or "Build validation failed."
        end
        local rollOffState = self:getRollOffState(result, side)
        if not rollOffState then
            return false,
                "This build no longer needs a protected "
                    .. sideNoun(side)
                    .. " rolled off. Analyze the refreshed state."
        end
        entryID = tonumber(entryID)
        local target = self:getRollOffTarget(result, side, entryID)
        if not target or target.side ~= side
            or not self.api.isKnownID(entryID) then
            return false,
                "The selected "
                    .. sideNoun(side)
                    .. " is no longer an eligible owned build "
                    .. sideNoun(side) .. "."
        end
        local blockReason = self.api.getRollBlockReason()
        if blockReason then
            return false, blockReason
        end

        self.link = selectedLink
        self.sessionLimit = 1
        self.highRollFloors = { abilities = 0, talents = 0 }
        self.allowStandardTalentScrolls =
            allowStandardTalentScrolls
        self.rollsSpent = 0
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.pendingRoll = nil
        self.lastResult = nil
        self.upgradeResults = {}
        self.scrollsAtStart = balances
        self.rollsBySide = { abilities = 0, talents = 0 }
        self.lastSchedule = nil
        self.sessionLearned = {}
        self.sessionLockedIDs = {}
        self.oneShotRollOff = {
            entryID = target.entryID,
            name = target.name,
            side = side,
            currentRank = target.currentRank,
            maxRank = target.maxRank,
            targetRank = target.targetRank,
            wasLocked = self.api.isLockedID(target.entryID) and true or false,
            accepted = false,
        }
        self.running = true
        self.paused = false
        self.worldSuspended = false
        self.phase = "rolloff_ready"
        self:notify(
            "rolloff_started",
            string.format(
                "One-time roll off confirmed for %s (entry #%d).",
                target.name,
                target.entryID
            ),
            target
        )
        if self.oneShotRollOff.wasLocked then
            self:beginRollOffUnlock(target)
        else
            self:beginRollOffRequest(target)
        end
        return true
    end

    function controller:resume()
        if not self.paused then
            return false, "Auto-roll is not paused."
        end
        local ready, readyError = self.api.ensureReady()
        if not ready then
            return false, readyError
        end
        self.running = true
        self.paused = false
        if self.pendingLockID then
            self.phase = "locking"
            self:notify(
                "waiting",
                "Resumed while a protection lock is still pending; verifying it."
            )
            self:armLockWatch(self.pendingLockID)
            return true
        end
        if self.pendingUnlockID then
            self.phase = "unlocking"
            self:notify(
                "waiting",
                "Resumed while a superseded any-of lock is still pending; verifying it."
            )
            self:armUnlockWatch(self.pendingUnlockID)
            return true
        end
        if self.pendingRoll then
            if self.phase == "waiting_unlearn" then
                self:armUnlearnWatch(self.pendingRoll)
            elseif self.phase == "waiting_learn"
                or self.phase == "waiting_bonus_learn" then
                self:armLearnWatch(self.pendingRoll)
            end
            self:notify(
                "waiting",
                "Resumed while a prior roll is still finishing; waiting for its result."
            )
            return true
        end
        self.phase = "ready"
        self:notify("resumed", "Auto-roll resumed.")
        self:step()
        return true
    end

    function controller:step()
        if not self.running or self.worldSuspended then
            return
        end
        if self.pendingLockID or self.pendingUnlockID or self.pendingRoll then
            return
        end
        if self.sessionLimit
            and self.rollsSpent >= self.sessionLimit then
            self:stop(
                string.format(
                    "Session roll limit reached after %d paid roll%s.",
                    self.rollsSpent,
                    self.rollsSpent == 1 and "" or "s"
                ),
                "complete"
            )
            return
        end
        local result = self:analyze()
        if not result.ok then
            self:stop(
                result.errors and result.errors[1] or "Build validation failed.",
                "error"
            )
            return
        end
        local buildIdentity = result.parsed and result.parsed.identity
        if not self.managedBuildIdentity then
            self.managedBuildIdentity = buildIdentity
            if type(self.api.prepareManagedAnyLocks) == "function" then
                self.api.prepareManagedAnyLocks(buildIdentity)
            end
        elseif self.managedBuildIdentity ~= buildIdentity then
            self:stop(
                "The active build identity changed; start a new session before changing locks.",
                "stopped"
            )
            return
        end

        if #result.lockSuggestions > 0 then
            local target = result.lockSuggestions[1]
            self.pendingLockID = target.entryID
            self.pendingLockName = target.name
            self.pendingLockAttempts = 1
            self.pendingLockTarget = target
            self.phase = "locking"
            self:notify(
                "locking",
                string.format(
                    "Locking protected %s %s (entry #%d).",
                    target.side == "talents" and "talent" or "ability",
                    target.name,
                    target.entryID
                ),
                target
            )
            local requested = self.api.lockID(target.entryID)
            if requested == false then
                self.pendingLockID = nil
                self.pendingLockName = nil
                self.pendingLockAttempts = 0
                self.pendingLockTarget = nil
                self:stop(
                    "The client rejected the lock request for " .. target.name .. ".",
                    "error"
                )
                return
            end
            self:armLockWatch(target.entryID)
            return
        end


        local surplus = self:nextSessionOwnedSurplus(result)
        if surplus then
            self:beginPendingUnlock(surplus)
            return
        end

        local recommendation, schedule, scheduleError =
            self:selectRecommendation(result, true)
        self.lastSchedule = schedule
        if not recommendation then
            self:stop(
                scheduleError
                    or (schedule and schedule.highRollComplete
                        and schedule.reason)
                    or "No safe reroll remains. The required plan is satisfied or every candidate is blocked.",
                scheduleError and "blocked" or "complete"
            )
            return
        end

        local candidate = recommendation.candidate
        local blockReason = self.api.getRollBlockReason()
        if blockReason then
            self:stop(blockReason, "blocked")
            return
        end
        if not self.api.isKnownID(candidate.entryID) then
            self:stop("The selected target is no longer known.", "error")
            return
        end
        if self.api.isLockedID(candidate.entryID) then
            self:stop("The selected target became locked.", "error")
            return
        end
        local canRemove, removeReason = self.api.canRemoveByEntryID(candidate.entryID)
        if not canRemove then
            self:stop(messageFor(removeReason), "blocked")
            return
        end

        self.upgradeResults = {}
        self.pendingRoll = {
            entryID = candidate.entryID,
            name = candidate.name,
            side = candidate.side,
            scheduleReason = schedule and schedule.reason,
            phase = "requesting",
            requestAttempts = 1,
            blockedWatchChecks = 0,
            learnWatchChecks = 0,
            revealRequestAttempts = 0,
            revealRequested = false,
            bonusRequestStarted = false,
        }
        self.phase = "waiting_unlearn"
        self:notify(
            "rolling",
            string.format(
                "Requesting %s roll %d: %s (entry #%d) — %s.",
                candidate.side == "talents" and "talent" or "ability",
                self.rollsSpent + 1,
                candidate.name,
                candidate.entryID,
                schedule and schedule.reason or "safe target selected"
            ),
            candidate
        )
        local requested = self.api.unlearnID(candidate.entryID)
        if not requested then
            self.pendingRoll = nil
            self:stop(
                "The client rejected the reroll request before sending it.",
                "error"
            )
            return
        end
        self:armUnlearnWatch(self.pendingRoll)
    end

    function controller:armUnlearnWatch(requested)
        if type(self.api.watchUnlearn) ~= "function" then
            return
        end
        self.api.watchUnlearn(function()
            self:onUnlearnWatch(requested)
        end)
    end

    function controller:armLockWatch(entryID)
        if type(self.api.watchLock) ~= "function" then
            return
        end
        self.api.watchLock(function()
            self:onLockWatch(entryID)
        end)
    end

    function controller:completePendingLock(entryID)
        if self.pendingLockID ~= entryID then
            return
        end
        local name = self.pendingLockName
            or ("Entry #" .. tostring(entryID))
        local target = self.pendingLockTarget or {
            entryID = entryID,
            name = name,
        }
        local restoresRollOff = target.rollOffRestore and true or false
        target.learnedThisSession = self.sessionLearned[entryID]
        if not restoresRollOff then
            self.sessionLockedIDs[entryID] = true
            if target.sectionKind == "any"
                and type(self.api.markManagedAnyLock) == "function" then
                self.api.markManagedAnyLock(
                    self.managedBuildIdentity,
                    target
                )
            end
        end
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.phase = self.running and "ready" or "paused"
        self:notify(
            "locked",
            name .. " is protected.",
            target
        )
        if restoresRollOff then
            self:finishRollOffOnce()
            return
        end
        self:step()
    end

    function controller:nextSessionOwnedSurplus(result, entryID)
        for _, item in ipairs(result.surplusAnyEntries or {}) do
            local persisted = type(self.api.isManagedAnyLock) == "function"
                and self.api.isManagedAnyLock(
                    self.managedBuildIdentity,
                    item
                )
            if (not entryID or item.entryID == entryID)
                and (self.sessionLockedIDs[item.entryID] or persisted)
                and self.api.isKnownID(item.entryID)
                and self.api.isLockedID(item.entryID) then
                return item
            end
        end
    end

    function controller:clearPendingUnlock()
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
    end

    function controller:beginRollOffUnlock(target)
        local rollOff = self.oneShotRollOff
        local side = rollOff and rollOff.side or target.side
        target = {
            entryID = target.entryID,
            name = target.name,
            side = side,
            currentRank = target.currentRank,
            maxRank = target.maxRank,
            targetRank = target.targetRank,
            rollOffOnce = true,
        }
        self.pendingUnlockID = target.entryID
        self.pendingUnlockName = target.name
        self.pendingUnlockAttempts = 1
        self.pendingUnlockTarget = target
        self.phase = "rolloff_unlocking"
        self:notify(
            "rolloff_unlocking",
            string.format(
                "Releasing protection from %s for the confirmed one-time roll off.",
                target.name
            ),
            target
        )
        if self.api.unlockID(target.entryID) == false then
            self:clearPendingUnlock()
            self:stop(
                "The client rejected the confirmed "
                    .. sideNoun(side)
                    .. " unlock for "
                    .. target.name .. ".",
                "error"
            )
            return
        end
        self:armUnlockWatch(target.entryID)
    end

    function controller:beginRollOffLockRestoration(reason, kind)
        local rollOff = self.oneShotRollOff
        if not rollOff or not rollOff.wasLocked then
            self:stop(reason, kind)
            return
        end
        rollOff.restoring = true
        rollOff.finishReason = reason
            or "The one-time roll off stopped before its paid request."
        rollOff.finishKind = kind or "stopped"
        local unlockWasPending =
            self.pendingUnlockID == rollOff.entryID
        self:clearPendingUnlock()
        self.pendingRoll = nil
        self.running = true
        self.paused = false
        self.worldSuspended = false
        local target = {
            entryID = rollOff.entryID,
            name = rollOff.name,
            side = rollOff.side,
            rollOffRestore = true,
            rollOffUnlockBarrier = unlockWasPending,
            lockStableChecks = 0,
        }
        self.pendingLockID = target.entryID
        self.pendingLockName = target.name
        self.pendingLockAttempts = 1
        self.pendingLockTarget = target
        self.phase = "rolloff_relocking"
        self:notify(
            "rolloff_relocking",
            target.name
                .. " will remain protected; verifying its lock before stopping.",
            target
        )
        -- This lock request is deliberately sent even if the old lock still
        -- appears active. When an accepted UnlockID is still in flight, the
        -- later LockID acts as the ordering barrier that restores the final
        -- state after that unlock settles.
        if self.api.lockID(target.entryID) == false then
            self.pendingLockID = nil
            self.pendingLockName = nil
            self.pendingLockAttempts = 0
            self.pendingLockTarget = nil
            self:stop(
                "The client rejected protection restoration for "
                    .. target.name .. ".",
                "error"
            )
            return
        end
        self:armLockWatch(target.entryID)
    end

    function controller:beginRollOffRequest(target)
        local rollOff = self.oneShotRollOff
        if not rollOff or rollOff.entryID ~= target.entryID then
            self:stop(
                "The one-time roll-off selection changed before its paid request.",
                "error"
            )
            return
        end
        if not self.running then
            self:stop(
                "The one-time roll off was cancelled before its paid request.",
                "stopped"
            )
            return
        end
        local blockReason = self.api.getRollBlockReason()
        if blockReason then
            self:stop(blockReason, "blocked")
            return
        end
        if not self.api.isKnownID(target.entryID) then
            self:stop(
                "The selected "
                    .. sideNoun(rollOff.side)
                    .. " is no longer known.",
                "error"
            )
            return
        end
        if self.api.isLockedID(target.entryID) then
            self:stop(
                "The selected "
                    .. sideNoun(rollOff.side)
                    .. " is still protected after the unlock request.",
                "error"
            )
            return
        end
        local balances, balanceError = self:readScrollBalances()
        if not balances then
            self:stop(balanceError, "rolloff_blocked")
            return
        end
        if self.scrollsAtStart and self.scrollsAtStart.specID
            and balances.specID ~= self.scrollsAtStart.specID then
            self:stop(
                "The active specialization changed before the one-time roll-off request.",
                "rolloff_blocked"
            )
            return
        end
        local available = rollOff.side == "abilities"
            and abilityBalance(balances)
            or balances.talents
                + (self.allowStandardTalentScrolls and balances.shared or 0)
        if available <= 0 then
            self:stop(
                rollOff.side == "talents"
                    and not self.allowStandardTalentScrolls
                    and "No dedicated Talent Scroll remains for the confirmed one-time roll off."
                    or "No authorized scroll currency remains for the confirmed one-time roll off.",
                "rolloff_blocked"
            )
            return
        end
        local result = self:analyze()
        if not result.ok then
            self:stop(
                result.errors and result.errors[1]
                    or "Build validation failed before the one-time roll off.",
                "rolloff_blocked"
            )
            return
        end
        local refreshedTarget = self:getRollOffTarget(
            result,
            rollOff.side,
            target.entryID
        )
        if not refreshedTarget then
            self:stop(
                "The selected "
                    .. sideNoun(rollOff.side)
                    .. " no longer needs to be rolled off.",
                "rolloff_blocked"
            )
            return
        end
        target = refreshedTarget
        local canRemove, removeReason =
            self.api.canRemoveByEntryID(target.entryID)
        if not canRemove then
            self:stop(messageFor(removeReason), "blocked")
            return
        end

        self.upgradeResults = {}
        self.pendingRoll = {
            entryID = target.entryID,
            name = target.name,
            side = rollOff.side,
            scheduleReason = "confirmed one-time "
                .. sideNoun(rollOff.side) .. " roll off",
            rollOffOnce = true,
            phase = "requesting",
            requestAttempts = 1,
            blockedWatchChecks = 0,
            learnWatchChecks = 0,
            revealRequestAttempts = 0,
            revealRequested = false,
            bonusRequestStarted = false,
        }
        self.phase = "waiting_unlearn"
        self:notify(
            "rolloff_rolling",
            string.format(
                "Rolling off %s once (entry #%d).",
                target.name,
                target.entryID
            ),
            target
        )
        if not self.api.unlearnID(target.entryID) then
            self.pendingRoll = nil
            self:stop(
                "The client rejected the one-time reroll request before sending it.",
                "error"
            )
            return
        end
        self:armUnlearnWatch(self.pendingRoll)
    end

    function controller:finishRollOffOnce()
        local rollOff = self.oneShotRollOff
        local name = rollOff and rollOff.name or "The selected entry"
        local finishReason = rollOff and rollOff.finishReason
        local finishKind = rollOff and rollOff.finishKind
        self.running = false
        self.paused = false
        self.worldSuspended = false
        self.phase = "stopped"
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.pendingRoll = nil
        self.oneShotRollOff = nil
        self.sessionLockedIDs = {}
        self:notify(
            finishKind or "rolloff_complete",
            finishReason
                or (name
                    .. " was rolled off once. Review the refreshed plan, then explicitly start Single or Rapid.")
        )
    end

    function controller:completeRollOffResult()
        local rollOff = self.oneShotRollOff
        if not rollOff then
            self:finishRollOffOnce()
            return
        end
        if rollOff.wasLocked
            and self.api.isKnownID(rollOff.entryID)
            and not self.api.isLockedID(rollOff.entryID) then
            rollOff.restoring = true
            local target = {
                entryID = rollOff.entryID,
                name = rollOff.name,
                side = rollOff.side,
                rollOffRestore = true,
            }
            self.pendingLockID = target.entryID
            self.pendingLockName = target.name
            self.pendingLockAttempts = 1
            self.pendingLockTarget = target
            self.phase = "rolloff_relocking"
            self:notify(
                "rolloff_relocking",
                target.name
                    .. " returned from the one-time roll; restoring its protection.",
                target
            )
            if self.api.lockID(target.entryID) == false then
                self.pendingLockID = nil
                self.pendingLockName = nil
                self.pendingLockAttempts = 0
                self.pendingLockTarget = nil
                self:stop(
                    "The client rejected protection restoration for "
                        .. target.name .. ".",
                    "error"
                )
                return
            end
            self:armLockWatch(target.entryID)
            return
        end
        self:finishRollOffOnce()
    end

    function controller:beginPendingUnlock(target)
        self.pendingUnlockID = target.entryID
        self.pendingUnlockName = target.name
        self.pendingUnlockAttempts = 1
        self.pendingUnlockTarget = target
        self.phase = "unlocking"
        self:notify(
            "unlocking",
            string.format(
                "Releasing addon-managed %s from its superseded any-of slot (entry #%d).",
                target.name,
                target.entryID
            ),
            target
        )
        if self.api.unlockID(target.entryID) == false then
            self:clearPendingUnlock()
            self:stop(
                "The client rejected the safe any-of unlock for "
                    .. target.name .. ".",
                "error"
            )
            return
        end
        self:armUnlockWatch(target.entryID)
    end

    function controller:completePendingUnlock(entryID)
        if self.pendingUnlockID ~= entryID then
            return
        end
        local name = self.pendingUnlockName
            or ("Entry #" .. tostring(entryID))
        local target = self.pendingUnlockTarget or {
            entryID = entryID,
            name = name,
        }
        local rollsOffOnce = target.rollOffOnce and true or false
        self.sessionLockedIDs[entryID] = nil
        if type(self.api.clearManagedAnyLock) == "function" then
            self.api.clearManagedAnyLock(
                self.managedBuildIdentity,
                target
            )
        end
        self:clearPendingUnlock()
        self.phase = self.running and "ready" or "paused"
        self:notify(
            rollsOffOnce and "rolloff_unlocked" or "unlocked",
            rollsOffOnce
                and (name .. " is unlocked for the confirmed one-time roll off.")
                or (name
                    .. " was released because a preferred any-of option is now protected."),
            target
        )
        if rollsOffOnce then
            self:beginRollOffRequest(target)
            return
        end
        self:step()
    end

    function controller:armUnlockWatch(entryID)
        if type(self.api.watchLock) ~= "function" then
            return
        end
        self.api.watchLock(function()
            self:onUnlockWatch(entryID)
        end)
    end

    function controller:onUnlockWatch(entryID)
        if self.pendingUnlockID ~= entryID or self.worldSuspended then
            return
        end
        if not self.api.isLockedID(entryID) then
            self:completePendingUnlock(entryID)
            return
        end
        if not self.running then
            return
        end

        local rollOffTarget = self.pendingUnlockTarget
        if rollOffTarget and rollOffTarget.rollOffOnce then
            local rollOffSide = self.oneShotRollOff
                and self.oneShotRollOff.side or rollOffTarget.side
            if not self.oneShotRollOff
                or self.oneShotRollOff.entryID ~= entryID
                or not self.api.isKnownID(entryID) then
                self:clearPendingUnlock()
                self:stop(
                    "The selected "
                        .. sideNoun(rollOffSide)
                        .. " changed while verifying its one-time unlock.",
                    "error"
                )
                return
            end
            if self.pendingUnlockAttempts >= 3 then
                local name = self.pendingUnlockName
                    or ("entry #" .. tostring(entryID))
                self:clearPendingUnlock()
                self:stop(
                    "The client did not unlock "
                        .. name
                        .. " after three verified attempts.",
                    "error"
                )
                return
            end
            self.pendingUnlockAttempts = self.pendingUnlockAttempts + 1
            self:notify(
                "rolloff_unlock_retry",
                string.format(
                    "The selected %s is still protected; retrying its unlock (%d/3).",
                    sideNoun(rollOffSide),
                    self.pendingUnlockAttempts
                ),
                rollOffTarget
            )
            if self.api.unlockID(entryID) == false then
                self:clearPendingUnlock()
                self:stop(
                    "The client rejected the confirmed "
                        .. sideNoun(rollOffSide)
                        .. "-unlock retry.",
                    "error"
                )
                return
            end
            self:armUnlockWatch(entryID)
            return
        end

        local result = self:analyze()
        if not result.ok then
            self:clearPendingUnlock()
            self:stop(
                result.errors and result.errors[1]
                    or "Build validation failed while verifying an any-of unlock.",
                "error"
            )
            return
        end
        if not self:nextSessionOwnedSurplus(result, entryID) then
            local name = self.pendingUnlockName
                or ("entry #" .. tostring(entryID))
            self:clearPendingUnlock()
            self.phase = "ready"
            self:notify(
                "unlock_skipped",
                name
                    .. " is no longer a surplus any-of option; its lock was preserved."
            )
            self:step()
            return
        end
        if self.pendingUnlockAttempts >= 3 then
            local name = self.pendingUnlockName
                or ("entry #" .. tostring(entryID))
            self:clearPendingUnlock()
            self:stop(
                "The client did not release the addon-managed lock on "
                    .. name
                    .. " after three verified attempts.",
                "error"
            )
            return
        end
        self.pendingUnlockAttempts = self.pendingUnlockAttempts + 1
        self:notify(
            "unlock_retry",
            string.format(
                "Superseded any-of lock is still active; retrying %s (%d/3).",
                self.pendingUnlockName
                    or ("entry #" .. tostring(entryID)),
                self.pendingUnlockAttempts
            )
        )
        if self.api.unlockID(entryID) == false then
            self:clearPendingUnlock()
            self:stop(
                "The client rejected the safe any-of unlock retry.",
                "error"
            )
            return
        end
        self:armUnlockWatch(entryID)
    end

    function controller:onLockWatch(entryID)
        if self.pendingLockID ~= entryID then
            return
        end
        if self.worldSuspended then
            return
        end
        if self.api.isLockedID(entryID) then
            local target = self.pendingLockTarget
            if target and target.rollOffUnlockBarrier
                and (target.lockStableChecks or 0) < 1 then
                target.lockStableChecks =
                    (target.lockStableChecks or 0) + 1
                self:armLockWatch(entryID)
                return
            end
            self:completePendingLock(entryID)
            return
        end
        local target = self.pendingLockTarget
        if target and target.rollOffUnlockBarrier then
            target.lockStableChecks = 0
        end
        if not self.running then
            return
        end
        if self.pendingLockAttempts >= 3 then
            local name = self.pendingLockName
                or ("entry #" .. tostring(entryID))
            self.pendingLockID = nil
            self.pendingLockName = nil
            self.pendingLockAttempts = 0
            self.pendingLockTarget = nil
            self:stop(
                "The client did not lock "
                    .. name
                    .. " after three verified attempts.",
                "error"
            )
            return
        end
        self.pendingLockAttempts = self.pendingLockAttempts + 1
        self:notify(
            "lock_retry",
            string.format(
                "Protection lock is not active yet; retrying %s (%d/3).",
                self.pendingLockName
                    or ("entry #" .. tostring(entryID)),
                self.pendingLockAttempts
            )
        )
        if self.api.lockID(entryID) == false then
            self.pendingLockID = nil
            self.pendingLockName = nil
            self.pendingLockAttempts = 0
            self.pendingLockTarget = nil
            self:stop(
                "The client rejected the protection-lock retry.",
                "error"
            )
            return
        end
        self:armLockWatch(entryID)
    end

    function controller:armLearnWatch(requested)
        if type(self.api.watchLearn) ~= "function" then
            return
        end
        self.api.watchLearn(function()
            self:onLearnWatch(requested)
        end)
    end

    function controller:onLearnWatch(requested)
        if self.pendingRoll ~= requested
            or (
                self.phase ~= "waiting_learn"
                and self.phase ~= "waiting_bonus_learn"
            ) then
            return
        end
        if self.worldSuspended then
            return
        end
        local isBonus = self.phase == "waiting_bonus_learn"
        if isBonus and not requested.bonusRequestStarted then
            self:armLearnWatch(requested)
            return
        end
        requested.learnWatchChecks = (requested.learnWatchChecks or 0) + 1
        if requested.learnWatchChecks >= 10 then
            self.pendingRoll = nil
            self:stop(
                isBonus
                    and "The awarded Talent Essence replacement did not produce a learned result within ten seconds."
                    or "The accepted reroll did not produce a learned result within ten seconds.",
                "error"
            )
            return
        end

        if self.api.isRollRequestBlocked() then
            self:notify(
                "waiting",
                isBonus
                    and "The talent-upgrade replacement is still being processed."
                    or "The accepted reroll is still being processed; waiting for its learned result."
            )
            self:armLearnWatch(requested)
            return
        end

        if type(self.api.canRollAbilities) == "function"
            and self.api.canRollAbilities() then
            if (requested.revealRequestAttempts or 0) >= 3 then
                self.pendingRoll = nil
                self:stop(
                    isBonus
                        and "The awarded Talent Essence replacement remained unopened after three requests."
                        or "The accepted reroll remained unopened after three requests.",
                    "error"
                )
                return
            end
            requested.revealRequestAttempts =
                (requested.revealRequestAttempts or 0) + 1
            local sent = type(self.api.requestPendingRoll) == "function"
                and self.api.requestPendingRoll()
            if sent then
                requested.revealRequested = true
                self:notify(
                    "revealing",
                    isBonus
                        and "The awarded Talent Essence replacement was waiting unopened; requested it directly."
                        or "The accepted reroll was waiting unopened; requested its pending result directly."
                )
            elseif requested.revealRequestAttempts >= 3 then
                self.pendingRoll = nil
                self:stop(
                    "The client rejected three attempts to open the accepted reroll.",
                    "error"
                )
                return
            end
        end
        self:armLearnWatch(requested)
    end

    function controller:onUnlearnWatch(requested)
        if self.pendingRoll ~= requested or self.phase ~= "waiting_unlearn" then
            return
        end
        if self.worldSuspended then
            return
        end
        if not self.running then
            return
        end
        if self.api.isRollRequestBlocked() then
            requested.blockedWatchChecks =
                (requested.blockedWatchChecks or 0) + 1
            if requested.blockedWatchChecks >= 5 then
                self.pendingRoll = nil
                self:stop(
                    "The native reroll request remained in flight for five seconds.",
                    "error"
                )
                return
            end
            self:notify(
                "waiting",
                "The reroll request is still in flight; continuing to wait."
            )
            self:armUnlearnWatch(requested)
            return
        end

        if not self.api.isKnownID(requested.entryID) then
            self.pendingRoll = nil
            self:stop(
                "The reroll target changed without a result event; stopped to avoid a duplicate roll.",
                "error"
            )
            return
        end
        if self.api.isLockedID(requested.entryID) then
            self.pendingRoll = nil
            self:stop(
                "The stalled reroll target became locked; stopped without retrying.",
                "error"
            )
            return
        end
        local canRemove, removeReason =
            self.api.canRemoveByEntryID(requested.entryID)
        if not canRemove then
            self.pendingRoll = nil
            self:stop(messageFor(removeReason), "blocked")
            return
        end
        if (requested.requestAttempts or 1) >= 3 then
            self.pendingRoll = nil
            self:stop(
                "No reroll result arrived after three safe request attempts.",
                "error"
            )
            return
        end

        requested.requestAttempts = (requested.requestAttempts or 1) + 1
        requested.blockedWatchChecks = 0
        self:notify(
            "retrying",
            string.format(
                "No result event arrived; target is unchanged and the client is idle. Retrying request (%d/3).",
                requested.requestAttempts
            ),
            requested
        )
        if not self.api.unlearnID(requested.entryID) then
            self.pendingRoll = nil
            self:stop(
                "The client rejected the guarded reroll retry.",
                "error"
            )
            return
        end
        self:armUnlearnWatch(requested)
    end

    function controller:onLockResult(result, internalID)
        local pendingTarget = self.pendingLockID == internalID
            and self.pendingLockTarget or nil
        if pendingTarget and pendingTarget.rollOffUnlockBarrier then
            if not self.api.isLockedID(internalID) then
                pendingTarget.lockStableChecks = 0
            end
            -- The counter-lock was queued behind an in-flight unlock.
            -- Neither event is a safe completion boundary: their delivery
            -- order can differ from the final lock state. Let the lock
            -- watchdog observe the final state twice instead.
            return
        end
        if self.pendingLockID == internalID
            and self.api.isLockedID(internalID) then
            self:completePendingLock(internalID)
        elseif self.pendingUnlockID == internalID
            and not self.api.isLockedID(internalID) then
            self:completePendingUnlock(internalID)
        elseif self.sessionLockedIDs[internalID]
            and not self.api.isLockedID(internalID) then
            -- A player or another addon released this lock outside our
            -- pending rotation. Relinquish provenance immediately so a later
            -- manual relock can never be mistaken for addon-managed.
            self.sessionLockedIDs[internalID] = nil
        end
    end

    function controller:onUnlearnResult(result)
        if not self.pendingRoll or self.phase ~= "waiting_unlearn" then
            return
        end
        if result ~= "CA_UNLEARN_OK" then
            local target = self.pendingRoll
            self.pendingRoll = nil
            self:stop(
                "Reroll rejected for "
                    .. target.name
                    .. ": "
                    .. messageFor(result),
                "error"
            )
            return
        end
        self.rollsSpent = self.rollsSpent + 1
        if self.pendingRoll.rollOffOnce and self.oneShotRollOff then
            self.oneShotRollOff.accepted = true
        end
        local side = self.pendingRoll.side
        self.rollsBySide[side] = (self.rollsBySide[side] or 0) + 1
        self.pendingRoll.phase = "waiting_learn"
        self.phase = "waiting_learn"
        self:notify(
            "accepted",
            string.format(
                "Roll %d accepted; waiting for the learned result.",
                self.rollsSpent
            ),
            {
                engine = "single",
                side = side,
                spent = 1,
            }
        )
        self:armLearnWatch(self.pendingRoll)
    end

    function controller:onEntryLearned(internalID, newRank, preRollRank)
        if not self.pendingRoll
            or (self.phase ~= "waiting_learn"
                and self.phase ~= "waiting_unlearn"
                and self.phase ~= "waiting_bonus_learn") then
            return
        end
        local requested = self.pendingRoll
        local freeReplacement = self.phase == "waiting_bonus_learn"
        local entry = self.api.getEntryByInternalID(internalID)
        local learned = {
            engine = "single",
            entryID = internalID,
            name = entry and entry.Name
                or ("Entry #" .. tostring(internalID or "?")),
            newRank = newRank,
            preRollRank = preRollRank,
            requestedEntryID = requested.entryID,
            requestedName = requested.name,
            roll = self.rollsSpent,
            side = requested.side,
            freeReplacement = freeReplacement,
        }
        local isUpgrade = tonumber(preRollRank)
            and tonumber(preRollRank) > 0
        if isUpgrade then
            self.upgradeResults[#self.upgradeResults + 1] = learned
        else
            learned.upgrades = self.upgradeResults
            self.lastResult = learned
        end
        self.sessionLearned[internalID] = learned
        requested.phase = "finishing_reveal"
        self.phase = isUpgrade and "waiting_bonus_learn" or "finishing_reveal"
        if isUpgrade then
            requested.bonusRequestStarted = false
        end
        self:notify(
            isUpgrade and "upgrade" or "result",
            isUpgrade
                and string.format(
                    "Roll %d upgraded %s from rank %s to %s; claiming its replacement talent.",
                    self.rollsSpent,
                    learned.name,
                    tostring(preRollRank),
                    tostring(newRank or "?")
                )
                or string.format(
                    "Roll %d: %s became %s.",
                    self.rollsSpent,
                    requested.name,
                    learned.name
                ),
            learned
        )
        self.api.finishReveal(function(ok, finishError)
            if self.pendingRoll ~= requested then
                return
            end
            if not ok then
                self.pendingRoll = nil
                self:stop(
                    finishError or "The completed reveal could not be cleared.",
                    "error"
                )
                return
            end
            if isUpgrade then
                requested.bonusRequestStarted = true
                requested.revealRequestAttempts = math.max(
                    requested.revealRequestAttempts or 0,
                    1
                )
                requested.revealRequested = true
                requested.learnWatchChecks = 0
                self:notify(
                    "bonus",
                    "Talent upgrade recorded; waiting for its awarded Talent Essence replacement result."
                )
                self:armLearnWatch(requested)
                return
            end
            self.pendingRoll = nil
            if requested.rollOffOnce then
                self:notify(
                    "reveal_complete",
                    "Completed the confirmed one-time "
                        .. sideNoun(requested.side) .. " reveal."
                )
                self:completeRollOffResult()
                return
            end
            self.phase = self.running and "ready" or "paused"
            self:notify(
                "reveal_complete",
                self.running
                    and "Completed reveal cleared; recomputing locks and the next target."
                    or "Completed reveal cleared; session remains paused."
            )
            self:step()
        end, isUpgrade)
    end

    function controller:onRollAbilitiesResult(result)
        if not self.pendingRoll then
            return
        end
        if self.phase ~= "waiting_bonus_learn"
            and self.phase ~= "waiting_learn" then
            return
        end
        if result and result ~= "ROLL_ABILITIES_OK" then
            self.pendingRoll = nil
            self:stop(
                self.phase == "waiting_bonus_learn"
                    and (
                        "Talent-upgrade replacement roll failed: "
                        .. messageFor(result)
                    )
                    or (
                        "Opening the accepted reroll failed: "
                        .. messageFor(result)
                    ),
                "error"
            )
        end
    end

    return controller
end

return M

end)()
addon.rapidControllerModule = (function()
local M = {}

local IN_FLIGHT_PHASES = {
    WaitingForUnlearn = true,
    WaitingForRoll = true,
    WaitingForLearn = true,
    Revealing = true,
}

local TERMINAL_PHASES = {
    Completed = true,
    Failed = true,
    Cancelled = true,
}

local RAPID_UPGRADE_READY_MAX_CHECKS = 200
local RAPID_UPGRADE_READY_STABLE_CHECKS = 20
local RAPID_UPGRADE_LEARN_MAX_CHECKS = 10
local RAPID_RELOAD_RECOVERY_MAX_CLAIMS = 5
local RAPID_UPGRADE_BONUS_PENDING =
    "STOP_RAPID_ROLLING_TALENT_UPGRADE_BONUS_PENDING"
local RAPID_UPGRADE_BONUS_LEARNED =
    "STOP_RAPID_ROLLING_TALENT_UPGRADE_BONUS_LEARNED"
local RAPID_COUNT_DEPLETED =
    "STOP_RAPID_ROLLING_COUNT_DEPLETED"
local RAPID_IN_FLIGHT_MAX_CHECKS = 15
local MAX_ORDINARY_DISCARD_PRIORITY = 2

local function normalizeCount(value)
    value = tonumber(value)
    if not value or value < 0 then
        return 0
    end
    return math.floor(value)
end

local function normalizeSessionLimit(value)
    value = tonumber(value)
    if not value or value <= 0 then
        return nil
    end
    return math.floor(value)
end

local function normalizeHighRollFloors(value)
    value = type(value) == "table" and value or {}
    return {
        abilities = normalizeCount(value.abilities),
        talents = normalizeCount(value.talents),
    }
end

local function normalizeRollSides(value)
    value = type(value) == "table" and value or {}
    return {
        abilities = value.abilities ~= false,
        talents = value.talents ~= false,
    }
end

local function highRollCompletionReason(status)
    local parts = {}
    for _, side in ipairs({ "abilities", "talents" }) do
        local current = status and status[side]
        if current and current.reached then
            local singular = side == "abilities" and "ability" or "talent"
            parts[#parts + 1] = string.format(
                "%d non-build %s%s remain%s (floor %d)",
                current.count,
                singular,
                current.count == 1 and "" or "s",
                current.count == 1 and "s" or "",
                current.floor
            )
        end
    end
    if #parts == 0 then
        return nil
    end
    return "High-roll protection reached: "
        .. table.concat(parts, "; ") .. "."
end

local function normalizeBalances(value)
    if type(value) ~= "table" then
        return nil
    end
    return {
        abilities = normalizeCount(value.abilities),
        talents = normalizeCount(value.talents),
        shared = normalizeCount(value.shared),
        specID = value.specID,
    }
end

local function abilityBalance(balances)
    return balances.abilities + balances.shared
end

local function rapidBalanceForSide(
    side,
    balances,
    allowStandardTalentScrolls
)
    if side == "abilities" then
        return abilityBalance(balances)
    end
    return balances.talents
        + (allowStandardTalentScrolls and balances.shared or 0)
end

local function rapidFundingError(
    side,
    available,
    required,
    allowStandardTalentScrolls
)
    if not required or required <= 0 then
        if side == "abilities" then
            return "No combined ability/standard scrolls are available for Ability Rapid."
        end
        return allowStandardTalentScrolls
            and "No combined talent/standard scrolls are available for Talent Rapid."
            or "No talent scrolls are available for Talent Rapid."
    end
    if side == "abilities" then
        return string.format(
            "Ability Rapid needs %d combined ability/standard scrolls; only %d are available.",
            required,
            available
        )
    end
    return allowStandardTalentScrolls
        and string.format(
            "Talent Rapid needs %d combined talent/standard scrolls; only %d are available.",
            required,
            available
        )
        or string.format(
            "Talent Rapid needs %d talent scrolls; only %d are available.",
            required,
            available
        )
end

local function talentPaidSpend(
    before,
    after,
    allowStandardTalentScrolls
)
    local spent = math.max(0, before.talents - after.talents)
    if allowStandardTalentScrolls then
        spent = spent + math.max(0, before.shared - after.shared)
    end
    return spent
end

local function reasonText(reason)
    if reason == nil or reason == "" then
        return "the client did not report a reason"
    end
    return tostring(_G and _G[reason] or reason)
end

local function isActiveUpgradeBonusState(state, canRoll, requestBlocked)
    return type(state) == "table"
        and state.Phase == "WaitingForRoll"
        and state.StopCode == RAPID_UPGRADE_BONUS_PENDING
        and state.IsActive == true
        and normalizeCount(state.RollCount) == 0
        and canRoll == true
        and requestBlocked == true
end

local function isActiveUpgradeTimeoutState(state, canRoll, requestBlocked)
    return type(state) == "table"
        and state.Phase == "AwaitingContinue"
        and state.StopCode == RAPID_COUNT_DEPLETED
        and state.IsActive == true
        and canRoll == true
        and requestBlocked == true
end

local function isReleasedRapidState(state)
    if type(state) ~= "table" or not state.Phase
        or state.Phase == "Idle" then
        return true
    end
    return TERMINAL_PHASES[state.Phase]
        and state.IsActive == false
end

local function learnedKey(internalID, newRank, preRollRank)
    return table.concat({
        tostring(internalID or 0),
        tostring(newRank or 0),
        tostring(preRollRank or 0),
    }, ":")
end

local function entrySide(entry)
    if entry and entry.Type == "Talent" then
        return "talents"
    end
    if entry and (
        entry.Type == "Ability"
        or entry.Type == "TalentAbility"
    ) then
        return "abilities"
    end
end

local function copySelections(selections)
    local result = {}
    for _, selection in ipairs(selections or {}) do
        if selection and selection.ID and selection.Type then
            result[#result + 1] = {
                ID = selection.ID,
                Type = selection.Type,
            }
        end
    end
    return result
end

local function copyDesiredDetail(item)
    if type(item) ~= "table" or item.entryID == nil then
        return nil
    end
    return {
        entryID = item.entryID,
        name = item.name,
        side = item.side,
        sectionKind = item.sectionKind,
        sectionName = item.sectionName,
        maxRank = item.maxRank,
        targetRank = item.targetRank,
    }
end

local function copyDesiredDetails(details)
    local result = {}
    for entryID, item in pairs(
        type(details) == "table" and details or {}
    ) do
        local copied = copyDesiredDetail(item)
        if copied then
            result[tostring(entryID)] = copied
        end
    end
    return result
end

local function copyProjection(projection)
    if type(projection) ~= "table" then
        return nil
    end
    return {
        side = projection.side,
        desired = copySelections(projection.desired),
        desiredDetails = copyDesiredDetails(
            projection.desiredDetails
        ),
        undesired = copySelections(projection.undesired),
        pityOnly = projection.pityOnly and true or false,
        discardPriority = projection.discardPriority,
        pityPressure = projection.pityPressure,
        pressureSourceCount = projection.pressureSourceCount,
        pressureSources = type(projection.pressureSources) == "table" and {
            abilities = normalizeCount(
                projection.pressureSources.abilities
            ),
            talents = normalizeCount(
                projection.pressureSources.talents
            ),
        } or nil,
        pressureDecision = projection.pressureDecision,
        activeSynergy = projection.activeSynergy and true or false,
        demand = projection.demand,
        reason = projection.reason,
        targetAbilityShare = projection.targetAbilityShare,
        targetTalentShare = projection.targetTalentShare,
        rapidRequirement = projection.rapidRequirement,
        availableBalance = projection.availableBalance,
    }
end

local function copyIDSet(value)
    local result = {}
    for entryID, enabled in pairs(
        type(value) == "table" and value or {}
    ) do
        entryID = tonumber(entryID)
        if enabled and entryID then
            result[entryID] = true
        end
    end
    return result
end

function M.new(core, api, observer)
    local controller = {
        core = core,
        api = api,
        observer = observer or function() end,
        running = false,
        paused = false,
        worldSuspended = false,
        phase = "idle",
        link = "",
        sessionLimit = nil,
        highRollFloors = {
            abilities = 0,
            talents = 0,
        },
        rollSides = {
            abilities = true,
            talents = true,
        },
        autoReloadEnabled = false,
        allowStandardTalentScrolls = false,
        scrollsAtStart = nil,
        rollsBySide = {
            abilities = 0,
            talents = 0,
        },
        batches = 0,
        selectedSide = nil,
        projection = nil,
        batchStartBalances = nil,
        batchActive = false,
        batchFinalizing = false,
        upgradeBoundaryActive = false,
        upgradeBoundaryState = nil,
        upgradeBoundaryWaitChecks = 0,
        upgradeClaimStableChecks = 0,
        upgradeReplacementPending = false,
        upgradeReplacementReceived = false,
        upgradeReplacementAttempts = 0,
        upgradeReplacementLearnChecks = 0,
        upgradeLastLearnedKey = nil,
        upgradeReloadReady = false,
        reloadRecoveryActive = false,
        reloadRecoveryUsed = false,
        savedSelections = nil,
        ownsSelections = false,
        pendingLockID = nil,
        pendingLockName = nil,
        pendingLockAttempts = 0,
        pendingLockTarget = nil,
        pendingUnlockID = nil,
        pendingUnlockName = nil,
        pendingUnlockAttempts = 0,
        pendingUnlockTarget = nil,
        sessionLockedIDs = {},
        managedBuildIdentity = nil,
        learnedThisBatch = {},
        stopAfterBatch = nil,
        lastState = nil,
        lastSchedule = nil,
        rapidFundingRequirements = {},
        lifecycleGeneration = 0,
        rapidStateWatchArmed = false,
        rapidUpgradeWatchArmed = false,
        rapidUpgradeWatchGeneration = 0,
        rapidReplacementWatchArmed = false,
        rapidReplacementWatchGeneration = 0,
        inFlightStateKey = nil,
        inFlightStateChecks = 0,
    }

    function controller:notify(kind, text, data)
        self.observer(kind, text, data, self)
    end

    function controller:advanceLifecycle()
        self.lifecycleGeneration = self.lifecycleGeneration + 1
        self.rapidStateWatchArmed = false
        return self.lifecycleGeneration
    end

    function controller:snapshot()
        return {
            running = self.running,
            paused = self.paused,
            worldSuspended = self.worldSuspended,
            phase = self.phase,
            sessionLimit = self.sessionLimit,
            highRollFloors = self.highRollFloors,
            rollSides = self.rollSides,
            autoReloadEnabled = self.autoReloadEnabled,
            allowStandardTalentScrolls =
                self.allowStandardTalentScrolls,
            scrollsAtStart = self.scrollsAtStart,
            rollsBySide = self.rollsBySide,
            batches = self.batches,
            selectedSide = self.selectedSide,
            projection = self.projection,
            batchActive = self.batchActive,
            batchFinalizing = self.batchFinalizing,
            ownsSelections = self.ownsSelections,
            pendingLockID = self.pendingLockID,
            pendingUnlockID = self.pendingUnlockID,
            sessionLockedIDs = self.sessionLockedIDs,
            managedBuildIdentity = self.managedBuildIdentity,
            lastState = self.lastState,
            lastSchedule = self.lastSchedule,
            rapidFundingRequirements = self.rapidFundingRequirements,
            lifecycleGeneration = self.lifecycleGeneration,
            upgradeBoundaryActive = self.upgradeBoundaryActive,
            upgradeBoundaryWaitChecks =
                self.upgradeBoundaryWaitChecks,
            upgradeClaimStableChecks =
                self.upgradeClaimStableChecks,
            upgradeReplacementPending =
                self.upgradeReplacementPending,
            upgradeReplacementReceived =
                self.upgradeReplacementReceived,
            upgradeReplacementAttempts =
                self.upgradeReplacementAttempts,
            upgradeReplacementLearnChecks =
                self.upgradeReplacementLearnChecks,
            upgradeReloadReady = self.upgradeReloadReady,
            reloadRecoveryActive = self.reloadRecoveryActive,
            reloadRecoveryUsed = self.reloadRecoveryUsed,
            rapidUpgradeWatchArmed = self.rapidUpgradeWatchArmed,
            rapidUpgradeWatchGeneration =
                self.rapidUpgradeWatchGeneration,
            rapidReplacementWatchArmed =
                self.rapidReplacementWatchArmed,
            rapidReplacementWatchGeneration =
                self.rapidReplacementWatchGeneration,
            inFlightStateKey = self.inFlightStateKey,
            inFlightStateChecks = self.inFlightStateChecks,
        }
    end

    function controller:resetRapidTalentUpgrade()
        self.upgradeBoundaryActive = false
        self.upgradeBoundaryState = nil
        self.upgradeBoundaryWaitChecks = 0
        self.upgradeClaimStableChecks = 0
        self.upgradeReplacementPending = false
        self.upgradeReplacementReceived = false
        self.upgradeReplacementAttempts = 0
        self.upgradeReplacementLearnChecks = 0
        self.upgradeLastLearnedKey = nil
        self.upgradeReloadReady = false
        self.reloadRecoveryActive = false
        self.reloadRecoveryUsed = false
        self.rapidUpgradeWatchArmed = false
        self.rapidUpgradeWatchGeneration =
            self.rapidUpgradeWatchGeneration + 1
        self.rapidReplacementWatchArmed = false
        self.rapidReplacementWatchGeneration =
            self.rapidReplacementWatchGeneration + 1
    end

    function controller:isHandlingUpgradeReplacement()
        return self.upgradeBoundaryActive
    end

    function controller:isBusy()
        return self.running
            or self.paused
            or self.batchActive
            or self.batchFinalizing
            or self.pendingLockID ~= nil
            or self.pendingUnlockID ~= nil
            or self.ownsSelections
    end

    function controller:setAutoReloadEnabled(enabled)
        enabled = enabled and true or false
        self.autoReloadEnabled = false
        if enabled and self:isBusy() then
            self:notify(
                "rapid_reload_click_required",
                "Ascension requires a player click for UI reload recovery; automatic reload was not enabled."
            )
        end
        return true
    end

    function controller:readBalances()
        local balances, balanceError = self.api.getScrollBalances()
        balances = normalizeBalances(balances)
        if not balances then
            return nil, balanceError
                or "The specialization scroll balances could not be read."
        end
        return balances
    end

    function controller:readProjectedRapidRequirement(side)
        local required = normalizeCount(
            self.api.getMaximumRapidRolls()
        )
        if required <= 0 then
            return nil,
                "The native " .. tostring(side)
                    .. " Rapid projection did not expose a positive maximum roll count."
        end
        return required
    end

    function controller:analyze()
        return self.core.analyze(self.link, self.api)
    end

    function controller:restoreSelections()
        if not self.ownsSelections then
            return true
        end
        local saved = self.savedSelections or {
            desired = {},
            undesired = {},
        }
        local ok, reason = self.api.setRapidSelections(
            copySelections(saved.desired),
            copySelections(saved.undesired)
        )
        if not ok then
            self:notify(
                "rapid_restore_error",
                "Could not restore the player's native Rapid selections: "
                    .. reasonText(reason)
            )
            return false, reason
        end
        self.ownsSelections = false
        self:notify(
            "rapid_restored",
            "Restored the native Rapid Desired and Undesired selections."
        )
        return true
    end

    function controller:finishStopped(reason, kind)
        self:advanceLifecycle()
        self.running = false
        self.paused = false
        self.worldSuspended = false
        self.phase = "stopped"
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.sessionLockedIDs = {}
        self.managedBuildIdentity = nil
        self.stopAfterBatch = nil
        self.rapidFundingRequirements = {}
        self:restoreSelections()
        self:notify(kind or "rapid_stopped", reason or "Rapid auto-roll stopped.")
    end

    function controller:stop(reason, kind)
        if self.batchActive or self.batchFinalizing then
            self.running = false
            self.paused = false
            self.stopAfterBatch = {
                reason = reason or "Rapid auto-roll stopped.",
                kind = kind or "rapid_stopped",
            }
            self:notify(
                "rapid_stopping",
                "Stop requested; the accepted native Rapid batch will finish before selections are restored."
            )
            return
        end
        self:finishStopped(reason, kind)
    end

    function controller:resetForSpecializationChange(reason)
        local hadSession = self:isBusy()
            or self.upgradeBoundaryActive
            or self.reloadRecoveryActive

        -- Rapid Desired/Undesired selections are stored per specialization.
        -- Never finishStop/restoreSelections here: those selections were
        -- captured from the old specialization, while Ascension's own
        -- specialization handler restores the newly active specialization.
        -- This is a local ownership reset only; it deliberately sends no
        -- CancelRapidRolling, RollAbilities, or selection mutation.
        self:advanceLifecycle()
        self.running = false
        self.paused = false
        self.worldSuspended = false
        self.phase = "idle"
        self.link = ""
        self.sessionLimit = nil
        self.highRollFloors = {
            abilities = 0,
            talents = 0,
        }
        self.rollSides = {
            abilities = true,
            talents = true,
        }
        self.autoReloadEnabled = false
        self.allowStandardTalentScrolls = false
        self.scrollsAtStart = nil
        self.rollsBySide = {
            abilities = 0,
            talents = 0,
        }
        self.batches = 0
        self.selectedSide = nil
        self.projection = nil
        self.batchStartBalances = nil
        self.batchActive = false
        self.batchFinalizing = false
        self.savedSelections = nil
        self.ownsSelections = false
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.sessionLockedIDs = {}
        self.managedBuildIdentity = nil
        self.learnedThisBatch = {}
        self.stopAfterBatch = nil
        self.lastState = nil
        self.lastSchedule = nil
        self.rapidFundingRequirements = {}
        self.rapidStateWatchArmed = false
        self.inFlightStateKey = nil
        self.inFlightStateChecks = 0
        self:resetRapidTalentUpgrade()

        if hadSession then
            self:notify(
                "rapid_specialization_reset",
                reason
                    or "Specialization changed; the previous Rapid session was reset without restoring its old selections."
            )
        end
        return hadSession
    end

    function controller:pause(reason)
        if not self.running then
            return false, "Rapid auto-roll is not running."
        end
        self.running = false
        self.paused = true
        if not self.batchActive and not self.batchFinalizing then
            self.phase = "paused"
            self:restoreSelections()
        end
        self:notify(
            "rapid_paused",
            reason
                or "Rapid auto-roll paused. An accepted native batch may finish, but no next batch will start."
        )
        return true
    end

    function controller:resume()
        if not self.paused then
            return false, "Rapid auto-roll is not paused."
        end
        if self.batchActive or self.batchFinalizing then
            self.running = true
            self.paused = false
            if self.reloadRecoveryActive then
                self.upgradeBoundaryWaitChecks = 0
                self.upgradeClaimStableChecks = 0
                self.upgradeReplacementLearnChecks = 0
                self.phase = "rapid_reload_recovering"
                self:notify(
                    "rapid_resumed",
                    "Rechecking the one-shot post-reload Talent Essence recovery boundary."
                )
                if self.upgradeReplacementPending then
                    self.phase = "rapid_reload_replacement_waiting"
                    self:armRapidReplacementWatch()
                else
                    self:advanceRapidReloadRecovery(
                        self.api.getRapidState()
                    )
                end
                return true
            end
            if (
                self.phase == "rapid_upgrade_manual"
                or self.phase == "rapid_upgrade_reload_ready"
            ) and self.upgradeBoundaryActive then
                self.upgradeBoundaryWaitChecks = 0
                self.upgradeClaimStableChecks = 0
                self.upgradeReplacementLearnChecks = 0
                self.upgradeReloadReady = false
                self:notify(
                    "rapid_resumed",
                    "Rechecking the interrupted awarded Talent Essence boundary without issuing a roll or cancellation."
                )
                if self.upgradeReplacementReceived then
                    self.phase = "rapid_upgrade_completion_waiting"
                    self:armRapidUpgradeWatch()
                else
                    self.phase = "rapid_upgrade_essence_waiting"
                    self:advanceRapidTalentUpgradeBoundary(
                        self.api.getRapidState()
                    )
                end
                return true
            end
            self:notify(
                "rapid_resumed",
                "Rapid auto-roll resumed while the previous native batch is finishing."
            )
            return true
        end
        local ready, readyError = self.api.ensureRapidReady()
        if not ready then
            return false, readyError
        end
        local balances, balanceError = self:readBalances()
        if not balances then
            return false, balanceError
        end
        if self.scrollsAtStart
            and self.scrollsAtStart.specID
            and balances.specID ~= self.scrollsAtStart.specID then
            self:finishStopped(
                "The active specialization changed; Rapid auto-roll stopped.",
                "rapid_stopped"
            )
            return false, "The active specialization changed."
        end
        self.running = true
        self.paused = false
        self.phase = "ready"
        self:notify("rapid_resumed", "Rapid auto-roll resumed.")
        if self.pendingLockID then
            if self.api.isLockedID(self.pendingLockID) then
                self:completePendingLock(self.pendingLockID)
            else
                self:armLockWatch(self.pendingLockID)
            end
            return true
        end
        if self.pendingUnlockID then
            if not self.api.isLockedID(self.pendingUnlockID) then
                self:completePendingUnlock(self.pendingUnlockID)
            else
                self:armUnlockWatch(self.pendingUnlockID)
            end
            return true
        end
        self:step()
        return true
    end

    function controller:suspendForWorld()
        if self.worldSuspended or not self:isBusy() then
            return false
        end
        self.worldSuspended = true
        self:notify(
            "rapid_zone_waiting",
            "Loading screen detected; preserving the Rapid session without issuing client mutations."
        )
        return true
    end

    function controller:resumeAfterWorld()
        if not self.worldSuspended then
            return true
        end
        self.worldSuspended = false
        local ready, readyError = self.api.ensureRapidContextReady()
        if not ready then
            self:stop(
                "The Rapid session could not continue after zoning: "
                    .. tostring(readyError),
                "rapid_error"
            )
            return false, readyError
        end
        local balances, balanceError = self:readBalances()
        if not balances then
            self:stop(
                "The Rapid session could not read scroll balances after zoning: "
                    .. tostring(balanceError),
                "rapid_error"
            )
            return false, balanceError
        end
        if self.scrollsAtStart
            and self.scrollsAtStart.specID
            and balances.specID ~= self.scrollsAtStart.specID then
            self:stop(
                "The active specialization changed while zoning; Rapid auto-roll stopped.",
                "rapid_stopped"
            )
            return false, "The active specialization changed."
        end
        self:notify(
            "rapid_zone_ready",
            self.running
                and "Zoning complete; the native Rapid state is being reconciled."
                or "Zoning complete; Rapid auto-roll remains paused."
        )
        if self.pendingLockID then
            if self.api.isLockedID(self.pendingLockID) then
                self:completePendingLock(self.pendingLockID)
            elseif self.running then
                self:armLockWatch(self.pendingLockID)
            end
            return true
        end
        if self.pendingUnlockID then
            if not self.api.isLockedID(self.pendingUnlockID) then
                self:completePendingUnlock(self.pendingUnlockID)
            elseif self.running then
                self:armUnlockWatch(self.pendingUnlockID)
            end
            return true
        end
        self:onRapidStateChanged()
        if not self.batchActive
            and not self.batchFinalizing
            and self.running then
            self:step()
        end
        return true
    end

    function controller:completePendingLock(entryID)
        if self.pendingLockID ~= entryID then
            return
        end
        local name = self.pendingLockName
            or ("Entry #" .. tostring(entryID))
        local target = self.pendingLockTarget or {
            entryID = entryID,
            name = name,
        }
        self.sessionLockedIDs[entryID] = true
        if target.sectionKind == "any"
            and type(self.api.markManagedAnyLock) == "function" then
            self.api.markManagedAnyLock(
                self.managedBuildIdentity,
                target
            )
        end
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.phase = self.running and "ready" or "paused"
        self:notify(
            "rapid_locked",
            name .. " is protected before the next Rapid batch."
        )
        if self.running then
            self:step()
        end
    end

    function controller:nextSessionOwnedSurplus(result, entryID)
        for _, item in ipairs(result.surplusAnyEntries or {}) do
            local persisted = type(self.api.isManagedAnyLock) == "function"
                and self.api.isManagedAnyLock(
                    self.managedBuildIdentity,
                    item
                )
            if (not entryID or item.entryID == entryID)
                and (self.sessionLockedIDs[item.entryID] or persisted)
                and self.api.isKnownID(item.entryID)
                and self.api.isLockedID(item.entryID) then
                return item
            end
        end
    end

    function controller:clearPendingUnlock()
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
    end

    function controller:beginPendingUnlock(target)
        self.pendingUnlockID = target.entryID
        self.pendingUnlockName = target.name
        self.pendingUnlockAttempts = 1
        self.pendingUnlockTarget = target
        self.phase = "rapid_unlocking"
        self:notify(
            "rapid_unlocking",
            "Releasing addon-managed " .. target.name
                .. " from its superseded any-of slot before projecting Rapid Undesired.",
            target
        )
        if self.api.unlockID(target.entryID) == false then
            self:clearPendingUnlock()
            self:stop(
                "The client rejected the safe any-of unlock for "
                    .. target.name .. ".",
                "rapid_error"
            )
            return
        end
        self:armUnlockWatch(target.entryID)
    end

    function controller:completePendingUnlock(entryID)
        if self.pendingUnlockID ~= entryID then
            return
        end
        local name = self.pendingUnlockName
            or ("Entry #" .. tostring(entryID))
        local target = self.pendingUnlockTarget or {
            entryID = entryID,
            name = name,
        }
        self.sessionLockedIDs[entryID] = nil
        if type(self.api.clearManagedAnyLock) == "function" then
            self.api.clearManagedAnyLock(
                self.managedBuildIdentity,
                target
            )
        end
        self:clearPendingUnlock()
        self.phase = self.running and "ready" or "paused"
        self:notify(
            "rapid_unlocked",
            name
                .. " was released because a preferred any-of option is now protected.",
            target
        )
        if self.running then
            self:step()
        end
    end

    function controller:armUnlockWatch(entryID)
        local generation = self.lifecycleGeneration
        self.api.watchLock(function()
            if generation ~= self.lifecycleGeneration then
                return
            end
            self:onUnlockWatch(entryID)
        end)
    end

    function controller:onUnlockWatch(entryID)
        if self.pendingUnlockID ~= entryID or self.worldSuspended then
            return
        end
        if not self.api.isLockedID(entryID) then
            self:completePendingUnlock(entryID)
            return
        end
        if not self.running then
            return
        end

        local result = self:analyze()
        if not result.ok then
            self:clearPendingUnlock()
            self:stop(
                result.errors and result.errors[1]
                    or "Build validation failed while verifying an any-of unlock.",
                "rapid_error"
            )
            return
        end
        local buildIdentity = result.parsed and result.parsed.identity
        if not self.managedBuildIdentity then
            self.managedBuildIdentity = buildIdentity
            if type(self.api.prepareManagedAnyLocks) == "function" then
                self.api.prepareManagedAnyLocks(buildIdentity)
            end
        elseif self.managedBuildIdentity ~= buildIdentity then
            self:stop(
                "The active build identity changed; start a new Rapid session before changing locks.",
                "rapid_stopped"
            )
            return
        end
        if not self:nextSessionOwnedSurplus(result, entryID) then
            local name = self.pendingUnlockName
                or ("entry #" .. tostring(entryID))
            self:clearPendingUnlock()
            self.phase = "ready"
            self:notify(
                "rapid_unlock_skipped",
                name
                    .. " is no longer a surplus any-of option; its lock was preserved."
            )
            self:step()
            return
        end
        if self.pendingUnlockAttempts >= 3 then
            local name = self.pendingUnlockName
                or ("entry #" .. tostring(entryID))
            self:clearPendingUnlock()
            self:stop(
                "The client did not release the addon-managed lock on "
                    .. name
                    .. " after three verified attempts.",
                "rapid_error"
            )
            return
        end
        self.pendingUnlockAttempts = self.pendingUnlockAttempts + 1
        self:notify(
            "rapid_unlock_retry",
            string.format(
                "Superseded any-of lock is still active; retrying %s (%d/3).",
                self.pendingUnlockName
                    or ("entry #" .. tostring(entryID)),
                self.pendingUnlockAttempts
            )
        )
        if self.api.unlockID(entryID) == false then
            self:clearPendingUnlock()
            self:stop(
                "The client rejected the safe any-of unlock retry.",
                "rapid_error"
            )
            return
        end
        self:armUnlockWatch(entryID)
    end

    function controller:armLockWatch(entryID)
        local generation = self.lifecycleGeneration
        self.api.watchLock(function()
            if generation ~= self.lifecycleGeneration then
                return
            end
            self:onLockWatch(entryID)
        end)
    end

    function controller:onLockWatch(entryID)
        if self.pendingLockID ~= entryID or self.worldSuspended then
            return
        end
        if self.api.isLockedID(entryID) then
            self:completePendingLock(entryID)
            return
        end
        if not self.running then
            return
        end
        if self.pendingLockAttempts >= 3 then
            local name = self.pendingLockName
                or ("entry #" .. tostring(entryID))
            self.pendingLockID = nil
            self:stop(
                "The client did not lock "
                    .. name
                    .. " after three verified attempts.",
                "rapid_error"
            )
            return
        end
        self.pendingLockAttempts = self.pendingLockAttempts + 1
        if self.api.lockID(entryID) == false then
            self.pendingLockID = nil
            self:stop(
                "The client rejected a protection-lock retry.",
                "rapid_error"
            )
            return
        end
        self:notify(
            "rapid_lock_retry",
            string.format(
                "Protection lock is not active yet; retrying %s (%d/3).",
                self.pendingLockName
                    or ("entry #" .. tostring(entryID)),
                self.pendingLockAttempts
            )
        )
        self:armLockWatch(entryID)
    end

    function controller:onLockResult(_, internalID)
        if self.pendingLockID == internalID
            and self.api.isLockedID(internalID) then
            self:completePendingLock(internalID)
        elseif self.pendingUnlockID == internalID
            and not self.api.isLockedID(internalID) then
            self:completePendingUnlock(internalID)
        elseif self.sessionLockedIDs[internalID]
            and not self.api.isLockedID(internalID) then
            self.sessionLockedIDs[internalID] = nil
        end
    end

    function controller:buildProjection(result, side, pityOnly)
        local state = result.sides[side]
        if not state or not state.demandRank then
            return nil, "The " .. side .. " side has no remaining build demand."
        end

        local desired = {}
        local desiredDetails = {}
        for _, item in ipairs(result.desiredEntries or {}) do
            if item.side == side and not item.known then
                local canAdd, reason =
                    self.api.canAddRapidDesired(item.entryID, item.entryType)
                if canAdd
                    or reason == "ADD_WILDCARD_DESIRED_ENTRY_ALREADY_DESIRED" then
                    desired[#desired + 1] = {
                        ID = item.entryID,
                        Type = item.entryType,
                    }
                    desiredDetails[tostring(item.entryID)] =
                        copyDesiredDetail(item)
                end
            end
        end
        if #desired == 0 then
            return nil,
                "Rapid Rolling has no unknown desired "
                    .. (side == "talents" and "talent" or "ability")
                    .. " to stop on."
        end

        local recommendation = state.recommendation
        local recommendedCandidate = recommendation
            and recommendation.candidate
        if not pityOnly
            and recommendedCandidate
            and recommendedCandidate.activeSynergy then
            local candidate
            for _, possible in ipairs(state.candidates or {}) do
                if possible.activeSynergy
                    and possible.entryID == recommendedCandidate.entryID then
                    candidate = possible
                    break
                end
            end
            if candidate
                and self.api.isKnownID(candidate.entryID)
                and not self.api.isLockedID(candidate.entryID) then
                local removable = self.api.canRemoveByEntryID(
                    candidate.entryID
                )
                local canAdd, reason =
                    self.api.canAddRapidUndesired(
                        candidate.entryID,
                        candidate.entryType
                    )
                if removable and (
                    canAdd
                    or reason ==
                        "ADD_WILDCARD_UNDESIRED_ENTRY_ALREADY_UNDESIRED"
                ) then
                    return {
                        side = side,
                        desired = desired,
                        desiredDetails = desiredDetails,
                        undesired = {
                            {
                                ID = candidate.entryID,
                                Type = candidate.entryType,
                            },
                        },
                        pityOnly = false,
                        discardPriority = candidate.priority,
                        pityPressure = 0,
                        pressureSourceCount = 0,
                        activeSynergy = true,
                        demand = state.demand,
                    }
                end
            end
            return nil,
                "The next active "
                    .. (side == "talents" and "talent" or "ability")
                    .. " synergy is not eligible for Rapid Undesired."
        end

        local undesired = {}
        local selectedPriority
        local selectedPressure
        local selectedPressureSources = 0
        local pressureSourceIDs = {}
        for _, candidate in ipairs(state.candidates or {}) do
            local priority = tonumber(candidate.priority) or math.huge
            local pressure = math.max(
                0,
                math.floor(tonumber(candidate.pityPressure) or 0)
            )
            local allowed
            if pityOnly then
                allowed = candidate.pityRisk
            else
                allowed = priority <= MAX_ORDINARY_DISCARD_PRIORITY
            end

            if allowed
                and self.api.isKnownID(candidate.entryID)
                and not self.api.isLockedID(candidate.entryID) then
                local removable = self.api.canRemoveByEntryID(candidate.entryID)
                local canAdd, reason =
                    self.api.canAddRapidUndesired(
                        candidate.entryID,
                        candidate.entryType
                    )
                if removable and (
                    canAdd
                    or reason == "ADD_WILDCARD_UNDESIRED_ENTRY_ALREADY_UNDESIRED"
                ) then
                    if not selectedPriority or priority < selectedPriority then
                        selectedPriority = priority
                        selectedPressure = nil
                        selectedPressureSources = 0
                        pressureSourceIDs = {}
                        undesired = {}
                    end
                    if priority == selectedPriority then
                        local pressureKey = candidate.entryID or candidate
                        if pressure > 0
                            and not pressureSourceIDs[pressureKey] then
                            pressureSourceIDs[pressureKey] = true
                            selectedPressureSources =
                                selectedPressureSources + 1
                        end
                        if selectedPressure == nil
                            or pressure > selectedPressure then
                            selectedPressure = pressure
                            undesired = {}
                        end
                        if pressure == selectedPressure then
                            undesired[#undesired + 1] = {
                                ID = candidate.entryID,
                                Type = candidate.entryType,
                            }
                        end
                    end
                end
            end
        end
        if #undesired == 0 then
            return nil,
                pityOnly
                    and "No removable unfinished discardable talent is eligible for Rapid Undesired."
                    or "No safe " .. side .. " discard is eligible for Rapid Undesired."
        end

        return {
            side = side,
            desired = desired,
            desiredDetails = desiredDetails,
            undesired = undesired,
            pityOnly = pityOnly and true or false,
            discardPriority = selectedPriority,
            pityPressure = selectedPressure or 0,
            pressureSourceCount = selectedPressureSources,
            activeSynergy = false,
            demand = state.demand,
        }
    end

    function controller:highRollStatus(result, floors, rollSides)
        floors = normalizeHighRollFloors(floors or self.highRollFloors)
        rollSides = normalizeRollSides(rollSides or self.rollSides)
        local status = {
            anyReached = false,
        }
        for _, side in ipairs({ "abilities", "talents" }) do
            local state = result.sides[side]
            local count = #(state.learnedNonbuild or {})
            local floor = floors[side]
            local orderedAbilityDisplacement = side == "abilities"
                and state.recommendation
                and state.recommendation.candidate
                and state.recommendation.candidate.role == "excess_any"
            local reached = rollSides[side]
                and floor > 0
                and count <= floor
                and state.recommendation ~= nil
                and not orderedAbilityDisplacement
            status[side] = {
                count = count,
                floor = floor,
                reached = reached,
            }
            status.anyReached = status.anyReached or reached
        end
        status.reason = highRollCompletionReason(status)
        return status
    end

    function controller:chooseProjection(
        result,
        balances,
        highRollFloors,
        allowStandardTalentScrolls,
        rollSides
    )
        if allowStandardTalentScrolls == nil then
            allowStandardTalentScrolls =
                self.allowStandardTalentScrolls
        end
        allowStandardTalentScrolls =
            allowStandardTalentScrolls and true or false
        rollSides = normalizeRollSides(rollSides or self.rollSides)
        local highRoll = self:highRollStatus(
            result,
            highRollFloors,
            rollSides
        )
        local function fundingFor(side)
            local available = rapidBalanceForSide(
                side,
                balances,
                allowStandardTalentScrolls
            )
            local required = normalizeCount(
                self.rapidFundingRequirements[side]
            )
            if required <= 0 then
                required = nil
            end
            return {
                available = available,
                required = required,
                underfunded = available <= 0
                    or (required ~= nil and available < required),
                usingStandardTalentScrolls = side == "talents"
                    and allowStandardTalentScrolls
                    and balances.shared > 0
                    and (
                        balances.talents <= 0
                        or required ~= nil
                            and balances.talents < required
                    ),
            }
        end

        local talentState = result.sides.talents
        if rollSides.talents
            and talentState.unfinishedDiscardable > 0
            and not highRoll.talents.reached then
            local projection, projectionError =
                self:buildProjection(result, "talents", true)
            if not projection then
                return nil,
                    "Unfinished non-build talents have priority, but "
                        .. tostring(projectionError)
            end
            local funding = fundingFor("talents")
            if funding.underfunded then
                return nil,
                    "Unfinished non-build talents have priority, but "
                        .. rapidFundingError(
                            "talents",
                            funding.available,
                            funding.required,
                            allowStandardTalentScrolls
                        )
            end
            projection.rapidRequirement = funding.required
            projection.availableBalance = funding.available
            projection.reason =
                "unfinished discardable talents override the scroll ratio"
            return projection
        end

        local projections = {}
        local fundingBySide = {}
        local errors = {}
        local underfunded = {}
        local hasUnprotectedRecommendation = false
        for _, side in ipairs({ "abilities", "talents" }) do
            local projection
            local projectionError
            if rollSides[side] and not highRoll[side].reached then
                hasUnprotectedRecommendation =
                    hasUnprotectedRecommendation
                    or result.sides[side].recommendation ~= nil
                projection, projectionError =
                    self:buildProjection(result, side, false)
            end
            if projection then
                local funding = fundingFor(side)
                fundingBySide[side] = funding
                if not funding.underfunded then
                    projection.rapidRequirement = funding.required
                    projection.availableBalance = funding.available
                    projections[side] = projection
                else
                    underfunded[side] = funding
                    errors[#errors + 1] = rapidFundingError(
                        side,
                        funding.available,
                        funding.required,
                        allowStandardTalentScrolls
                    )
                end
            elseif projectionError then
                errors[#errors + 1] = projectionError
            end
        end

        local deferredSynergySide
        if projections.abilities and projections.talents then
            local abilitySynergy = projections.abilities.activeSynergy
                and true or false
            local talentSynergy = projections.talents.activeSynergy
                and true or false
            if abilitySynergy ~= talentSynergy then
                deferredSynergySide = abilitySynergy
                    and "abilities" or "talents"
                projections[deferredSynergySide] = nil
            end
        end

        if not projections.abilities and not projections.talents then
            if not rollSides.abilities and not rollSides.talents then
                return nil, "No roll types are enabled."
            end
            if highRoll.anyReached
                and not hasUnprotectedRecommendation then
                return nil, highRoll.reason
            end
            return nil, #errors > 0
                and table.concat(errors, " ")
                or "No enabled roll type has a safe useful Rapid projection."
        end
        if projections.abilities and not projections.talents then
            if underfunded.talents ~= nil then
                if underfunded.talents.required then
                    projections.abilities.reason = string.format(
                        "Talent Rapid has %d/%d scrolls; continuing abilities%s",
                        underfunded.talents.available,
                        underfunded.talents.required,
                        projections.abilities.activeSynergy
                            and " with active synergies" or ""
                    )
                else
                    projections.abilities.reason = string.format(
                        "Talent Rapid has no scrolls; continuing abilities%s",
                        projections.abilities.activeSynergy
                            and " with active synergies" or ""
                    )
                end
            else
                projections.abilities.reason = deferredSynergySide
                    and "ordinary funded discards precede active synergies"
                    or "only abilities have a safe useful Rapid projection"
            end
            return projections.abilities
        end
        if projections.talents and not projections.abilities then
            if underfunded.abilities ~= nil then
                if underfunded.abilities.required then
                    projections.talents.reason = string.format(
                        "Ability Rapid has %d/%d scrolls; continuing talents%s",
                        underfunded.abilities.available,
                        underfunded.abilities.required,
                        projections.talents.activeSynergy
                            and " with active synergies" or ""
                    )
                else
                    projections.talents.reason = string.format(
                        "Ability Rapid has no scrolls; continuing talents%s",
                        projections.talents.activeSynergy
                            and " with active synergies" or ""
                    )
                end
            else
                projections.talents.reason = deferredSynergySide
                    and "ordinary funded discards precede active synergies"
                    or "only talents have a safe useful Rapid projection"
            end
            return projections.talents
        end

        local pressureSources = {
            abilities = normalizeCount(
                projections.abilities.pressureSourceCount
            ),
            talents = normalizeCount(
                projections.talents.pressureSourceCount
            ),
        }
        projections.abilities.pressureSources = pressureSources
        projections.talents.pressureSources = pressureSources

        -- Standard scrolls are the ability side's flexible currency too.
        -- When the player explicitly authorizes spending them on talents,
        -- select that funded talent projection before ratio scheduling so the
        -- shared pool cannot disappear into an ability batch first.
        if projections.talents
            and fundingBySide.talents
            and fundingBySide.talents.usingStandardTalentScrolls then
            projections.talents.reason =
                "standard-scroll talent fallback was explicitly enabled"
            projections.talents.usesStandardTalentScrolls = true
            return projections.talents
        end

        local abilitySources = pressureSources.abilities
        local talentSources = pressureSources.talents
        if abilitySources ~= talentSources then
            local projection = abilitySources > talentSources
                and projections.abilities or projections.talents
            projection.pressureDecision = "count"
            projection.reason = string.format(
                "more %s pressure sources",
                projection.side == "abilities" and "Ability" or "Talent"
            )
            return projection
        end

        local baseline = self.scrollsAtStart or balances
        local baselineAbilities = abilityBalance(baseline)
        local totalBaseline = baselineAbilities + baseline.talents
        if totalBaseline <= 0 then
            return nil, "No specialization scroll currency was available at session start."
        end
        local targetAbilityShare = baselineAbilities / totalBaseline
        local targetTalentShare = baseline.talents / totalBaseline
        local spentTotal =
            self.rollsBySide.abilities + self.rollsBySide.talents
        local nextTotal = spentTotal + 1
        local abilityDeficit =
            nextTotal * targetAbilityShare - self.rollsBySide.abilities
        local talentDeficit =
            nextTotal * targetTalentShare - self.rollsBySide.talents
        local side = abilityDeficit >= talentDeficit
            and "abilities" or "talents"
        local projection = projections[side]
        projection.pressureDecision = "ratio"
        projection.reason = string.format(
            "pressure sources tied; behind the %.1f%% ability / %.1f%% talent session ratio",
            targetAbilityShare * 100,
            targetTalentShare * 100
        )
        projection.targetAbilityShare = targetAbilityShare
        projection.targetTalentShare = targetTalentShare
        return projection
    end

    function controller:previewAnalysis(
        result,
        highRollFloors,
        allowStandardTalentScrolls,
        rollSides
    )
        if not result.ok then
            return nil,
                result.errors and result.errors[1]
                    or "Build validation failed."
        end
        local balances, balanceError = self:readBalances()
        if not balances then
            return nil, balanceError
        end
        return self:chooseProjection(
            result,
            balances,
            highRollFloors,
            allowStandardTalentScrolls,
            rollSides
        )
    end

    function controller:preview(
        link,
        highRollFloors,
        allowStandardTalentScrolls,
        rollSides
    )
        local originalLink = self.link
        self.link = tostring(link or originalLink or "")
        local result = self:analyze()
        self.link = originalLink
        return self:previewAnalysis(
            result,
            highRollFloors,
            allowStandardTalentScrolls,
            rollSides
        )
    end

    function controller:startBatch(projection)
        local balances, balanceError = self:readBalances()
        if not balances then
            self:stop(balanceError, "rapid_error")
            return false, "fatal"
        end
        local available = rapidBalanceForSide(
            projection.side,
            balances,
            self.allowStandardTalentScrolls
        )
        local knownRequirement = normalizeCount(
            self.rapidFundingRequirements[projection.side]
        )
        if knownRequirement > 0 and available < knownRequirement then
            self.phase = "ready"
            self:notify(
                "rapid_funding_changed",
                rapidFundingError(
                    projection.side,
                    available,
                    knownRequirement,
                    self.allowStandardTalentScrolls
                ) .. " Rechecking the other side."
            )
            return false, "underfunded"
        end

        local ok, reason = self.api.setRapidSelections(
            copySelections(projection.desired),
            copySelections(projection.undesired)
        )
        if not ok then
            self:stop(
                "Could not install the "
                    .. projection.side
                    .. " Rapid projection: "
                    .. reasonText(reason),
                "rapid_error"
            )
            return false, "fatal"
        end
        self.ownsSelections = true

        -- GetMaximumRapidRolls is projection-sensitive. Read it only after
        -- installing this side's Desired/Undesired arrays, then compare the
        -- exact live balance before native preflight or StartRapidRolling.
        local rapidRequirement, requirementError =
            self:readProjectedRapidRequirement(projection.side)
        if not rapidRequirement then
            self:stop(requirementError, "rapid_error")
            return false, "fatal"
        end
        self.rapidFundingRequirements[projection.side] =
            rapidRequirement

        balances, balanceError = self:readBalances()
        if not balances then
            self:stop(balanceError, "rapid_error")
            return false, "fatal"
        end
        available = rapidBalanceForSide(
            projection.side,
            balances,
            self.allowStandardTalentScrolls
        )
        if available < rapidRequirement then
            self.phase = "ready"
            self:notify(
                "rapid_funding_changed",
                rapidFundingError(
                    projection.side,
                    available,
                    rapidRequirement,
                    self.allowStandardTalentScrolls
                ) .. " Rechecking the other side."
            )
            return false, "underfunded"
        end
        projection.rapidRequirement = rapidRequirement
        projection.availableBalance = available

        local targetID = self.api.getNextRapidUnlearnedID()
        local target = targetID
            and self.api.getEntryByInternalID(targetID)
        local targetSide = entrySide(target)
        if not targetID or targetSide ~= projection.side then
            self:stop(
                string.format(
                    "Rapid side verification failed: requested %s, but the server selected %s.",
                    projection.side,
                    targetSide or "no valid target"
                ),
                "rapid_error"
            )
            return false, "fatal"
        end

        local canStart, startReason = self.api.canStartRapid()
        if not canStart then
            self:stop(
                "The native Rapid preflight rejected this projection: "
                    .. reasonText(startReason),
                "rapid_error"
            )
            return false, "fatal"
        end

        self:advanceLifecycle()
        self.batchStartBalances = balances
        self.selectedSide = projection.side
        self.projection = projection
        self.learnedThisBatch = {}
        self:resetRapidTalentUpgrade()
        self.inFlightStateKey = nil
        self.inFlightStateChecks = 0
        self.phase = "starting_rapid"
        self.batchActive = true
        self.batchFinalizing = false
        local maximum = rapidRequirement
        self:notify(
            "rapid_starting",
            string.format(
                "Starting native %s Rapid batch (server maximum %d): %d Desired, %d Undesired — %s.",
                projection.side == "talents" and "talent" or "ability",
                maximum,
                #projection.desired,
                #projection.undesired,
                projection.reason
            ),
            {
                engine = "rapid",
                side = projection.side,
                maximum = maximum,
                targetID = targetID,
                projection = projection,
            }
        )
        local visualReady, visualReason =
            self.api.prepareRapidVisual()
        if not visualReady then
            self.batchActive = false
            self:stop(
                "Could not establish native Rapid dice ownership: "
                    .. reasonText(visualReason),
                "rapid_error"
            )
            return false, "fatal"
        end
        local started, rapidReason = self.api.startRapid()
        if not started then
            self.batchActive = false
            self.api.cleanupRapidVisual()
            self:stop(
                "The native Rapid start request failed: "
                    .. reasonText(rapidReason),
                "rapid_error"
            )
            return false, "fatal"
        end
        self.phase = "rapid_in_flight"
        self:armRapidStateWatch()
        return true
    end

    function controller:armRapidStateWatch()
        if self.rapidStateWatchArmed or not self.batchActive then
            return
        end
        self.rapidStateWatchArmed = true
        local generation = self.lifecycleGeneration
        self.api.watchRapidState(function()
            if generation ~= self.lifecycleGeneration then
                return
            end
            self.rapidStateWatchArmed = false
            if self.batchActive then
                self:onRapidStateChanged(true)
            end
        end)
    end

    function controller:armRapidUpgradeWatch()
        if self.rapidUpgradeWatchArmed
            or not self.batchActive
            or not self.upgradeBoundaryActive
            or self.upgradeReplacementPending then
            return
        end
        self.rapidUpgradeWatchArmed = true
        local lifecycleGeneration = self.lifecycleGeneration
        local generation = self.rapidUpgradeWatchGeneration
        self.api.watchRapidUpgradeState(function()
            if lifecycleGeneration ~= self.lifecycleGeneration
                or generation ~= self.rapidUpgradeWatchGeneration then
                return
            end
            self.rapidUpgradeWatchArmed = false
            if self.batchActive
                and self.upgradeBoundaryActive
                and not self.upgradeReplacementPending then
                if self.reloadRecoveryActive then
                    self:advanceRapidReloadRecovery(
                        self.api.getRapidState(),
                        true
                    )
                else
                    self:advanceRapidTalentUpgradeBoundary(
                        self.api.getRapidState(),
                        true
                    )
                end
            end
        end)
    end

    function controller:armRapidReplacementWatch()
        if self.rapidReplacementWatchArmed
            or not self.batchActive
            or not self.upgradeBoundaryActive
            or not self.upgradeReplacementPending then
            return
        end
        self.rapidReplacementWatchArmed = true
        local lifecycleGeneration = self.lifecycleGeneration
        local generation = self.rapidReplacementWatchGeneration
        self.api.watchLearn(function()
            if lifecycleGeneration ~= self.lifecycleGeneration
                or generation ~= self.rapidReplacementWatchGeneration then
                return
            end
            self.rapidReplacementWatchArmed = false
            self:onRapidReplacementWatch()
        end)
    end

    function controller:step()
        if not self.running
            or self.paused
            or self.worldSuspended
            or self.batchActive
            or self.batchFinalizing
            or self.pendingLockID
            or self.pendingUnlockID then
            return
        end

        local sessionSpent =
            self.rollsBySide.abilities + self.rollsBySide.talents
        if self.sessionLimit and sessionSpent >= self.sessionLimit then
            self:finishStopped(
                string.format(
                    "Session roll limit reached after %d paid rolls%s.",
                    sessionSpent,
                    sessionSpent > self.sessionLimit
                        and string.format(
                            " (configured limit %d; the final native batch could not be shortened)",
                            self.sessionLimit
                        )
                        or ""
                ),
                "rapid_complete"
            )
            return
        end

        local ready, readyError = self.api.ensureRapidReady()
        if not ready then
            self:stop(readyError, "rapid_blocked")
            return
        end
        local result = self:analyze()
        if not result.ok then
            self:stop(
                result.errors and result.errors[1]
                    or "Build validation failed.",
                "rapid_error"
            )
            return
        end
        local buildIdentity = result.parsed and result.parsed.identity
        if not self.managedBuildIdentity then
            self.managedBuildIdentity = buildIdentity
            if type(self.api.prepareManagedAnyLocks) == "function" then
                self.api.prepareManagedAnyLocks(buildIdentity)
            end
        elseif self.managedBuildIdentity ~= buildIdentity then
            self:stop(
                "The active build identity changed; start a new Rapid session before changing locks.",
                "rapid_stopped"
            )
            return
        end
        if #result.lockSuggestions > 0 then
            local target = result.lockSuggestions[1]
            self.pendingLockID = target.entryID
            self.pendingLockName = target.name
            self.pendingLockAttempts = 1
            self.pendingLockTarget = target
            self.phase = "rapid_locking"
            self:notify(
                "rapid_locking",
                "Locking protected " .. target.name
                    .. " before projecting Rapid Undesired."
            )
            if self.api.lockID(target.entryID) == false then
                self.pendingLockID = nil
                self:stop(
                    "The client rejected the protection lock.",
                    "rapid_error"
                )
                return
            end
            self:armLockWatch(target.entryID)
            return
        end

        local surplus = self:nextSessionOwnedSurplus(result)
        if surplus then
            self:beginPendingUnlock(surplus)
            return
        end

        local balances, balanceError = self:readBalances()
        if not balances then
            self:stop(balanceError, "rapid_error")
            return
        end
        for _ = 1, 2 do
            local projection, projectionError =
                self:chooseProjection(result, balances)
            if not projection then
                self:finishStopped(
                    projectionError
                        or "The build is satisfied or no safe Rapid projection remains.",
                    "rapid_complete"
                )
                return
            end

            local started, startDisposition =
                self:startBatch(projection)
            if started then
                self.lastSchedule = {
                    side = projection.side,
                    reason = projection.reason,
                    balances = balances,
                    required = projection.rapidRequirement,
                    available = projection.availableBalance,
                    spent = {
                        abilities = self.rollsBySide.abilities,
                        talents = self.rollsBySide.talents,
                    },
                }
                return
            end
            if startDisposition ~= "underfunded"
                or not self.running then
                return
            end
            balances, balanceError = self:readBalances()
            if not balances then
                self:stop(balanceError, "rapid_error")
                return
            end
        end

        local _, fundingError = self:chooseProjection(result, balances)
        self:finishStopped(
            fundingError
                or "No funded safe Rapid projection remains.",
            "rapid_complete"
        )
    end

    function controller:pauseForRapidTalentUpgrade(message)
        self.running = false
        self.paused = true
        self.phase = "rapid_upgrade_manual"
        self.rapidUpgradeWatchArmed = false
        self.rapidUpgradeWatchGeneration =
            self.rapidUpgradeWatchGeneration + 1
        self.rapidReplacementWatchArmed = false
        self.rapidReplacementWatchGeneration =
            self.rapidReplacementWatchGeneration + 1
        self:notify("rapid_upgrade_manual", message)
    end

    function controller:pauseForReloadRecovery(message)
        self.running = false
        self.paused = true
        self.phase = "rapid_upgrade_reload_ready"
        self.rapidUpgradeWatchArmed = false
        self.rapidUpgradeWatchGeneration =
            self.rapidUpgradeWatchGeneration + 1
        self.rapidReplacementWatchArmed = false
        self.rapidReplacementWatchGeneration =
            self.rapidReplacementWatchGeneration + 1
        self:notify("rapid_upgrade_reload_ready", message)
    end

    function controller:canReloadRecovery()
        local retryingBlockedReload = self.reloadRecoveryUsed
            and self.phase == "rapid_upgrade_reloading"
        return self.batchActive
            and self.upgradeBoundaryActive
            and self.upgradeReloadReady
            and not self.reloadRecoveryActive
            and (
                not self.reloadRecoveryUsed
                or retryingBlockedReload
            )
    end

    function controller:buildReloadRecoveryCheckpoint()
        if not self:canReloadRecovery() then
            return nil,
                "The stuck Rapid Talent Essence boundary is not ready for reload recovery."
        end
        return {
            schema = 1,
            link = self.link,
            sessionLimit = self.sessionLimit or 0,
            highRollFloors = normalizeHighRollFloors(
                self.highRollFloors
            ),
            rollSides = normalizeRollSides(self.rollSides),
            autoReloadEnabled = false,
            allowStandardTalentScrolls =
                self.allowStandardTalentScrolls and true or false,
            scrollsAtStart = normalizeBalances(self.scrollsAtStart),
            rollsBySide = {
                abilities = normalizeCount(self.rollsBySide.abilities),
                talents = normalizeCount(self.rollsBySide.talents),
            },
            batches = normalizeCount(self.batches),
            selectedSide = self.selectedSide,
            projection = copyProjection(self.projection),
            batchStartBalances = normalizeBalances(
                self.batchStartBalances
            ),
            savedSelections = {
                desired = copySelections(
                    self.savedSelections and self.savedSelections.desired
                ),
                undesired = copySelections(
                    self.savedSelections and self.savedSelections.undesired
                ),
            },
            ownsSelections = self.ownsSelections and true or false,
            sessionLockedIDs = copyIDSet(self.sessionLockedIDs),
            managedBuildIdentity = self.managedBuildIdentity,
            upgradeLastLearnedKey = self.upgradeLastLearnedKey,
            retireAfterRecovery = self.stopAfterBatch ~= nil,
        }
    end

    function controller:requestReloadRecovery(trigger)
        if not self:canReloadRecovery() then
            return false,
                "Reload recovery is available only at the verified stuck Rapid Talent Essence boundary."
        end

        -- The recovery button is armed only after the controller has already
        -- observed a supported stuck boundary for its full stability window.
        -- Do not race that stored decision against another set of volatile
        -- native reads on the click path. Reload is the recovery action, and
        -- the post-reload reconciler safely handles a boundary that happened
        -- to advance after the button appeared.
        local checkpoint, checkpointError =
            self:buildReloadRecoveryCheckpoint()
        if not checkpoint then
            return false, checkpointError
        end
        self.reloadRecoveryUsed = true
        self.running = false
        self.paused = false
        self.phase = "rapid_upgrade_reloading"
        self:notify(
            "rapid_upgrade_reloading",
            "Saving the verified stuck Rapid upgrade boundary and reloading the UI once.",
            { trigger = trigger or "manual" }
        )
        local requested, reason =
            self.api.requestRapidRecoveryReload(
                checkpoint,
                trigger or "manual"
            )
        if requested then
            return true
        end
        self.reloadRecoveryUsed = false
        self.running = false
        self.paused = true
        self.phase = "rapid_upgrade_reload_ready"
        self:notify(
            "rapid_upgrade_manual",
            "The UI reload could not be started: "
                .. reasonText(reason)
                .. ". The native Rapid session was left untouched."
        )
        return false, reason
    end

    function controller:beginRapidTalentUpgradeBoundary(state)
        if self.worldSuspended
            or not self.batchActive
            or self.upgradeBoundaryActive then
            return
        end
        self.upgradeBoundaryActive = true
        self.upgradeBoundaryState = state or self.api.getRapidState()
        self.upgradeBoundaryWaitChecks = 0
        self.upgradeClaimStableChecks = 0
        self.upgradeReplacementPending = false
        self.upgradeReplacementReceived = false
        self.upgradeReplacementAttempts = 0
        self.upgradeReplacementLearnChecks = 0
        self.phase = "rapid_upgrade_essence_waiting"
        self:notify(
            "rapid_upgrade_essence_waiting",
            "Talent upgraded; waiting for Ascension to expose the awarded Talent Essence while the native Rapid session remains active."
        )
        self:advanceRapidTalentUpgradeBoundary(
            self.api.getRapidState()
        )
    end

    function controller:advanceRapidTalentUpgradeBoundary(
        state,
        fromWatchdog
    )
        if self.worldSuspended
            or not self.batchActive
            or not self.upgradeBoundaryActive
            or self.upgradeReplacementPending
            or self.batchFinalizing then
            return
        end
        state = state or self.api.getRapidState()
        if not state or not state.Phase then
            self:armRapidUpgradeWatch()
            return
        end
        if state.Phase == "AwaitingContinue"
            and state.StopCode == RAPID_UPGRADE_BONUS_LEARNED then
            self:notify(
                "rapid_bonus_complete",
                "Ascension completed the awarded Talent Essence replacement inside the active Rapid session; finishing the batch."
            )
            self:finalizeBatch(state)
            return
        end
        if fromWatchdog then
            self.upgradeBoundaryWaitChecks =
                self.upgradeBoundaryWaitChecks + 1
        end

        if self.upgradeReplacementReceived then
            self.phase = "rapid_upgrade_completion_waiting"
            if self.upgradeBoundaryWaitChecks
                >= RAPID_UPGRADE_READY_MAX_CHECKS then
                self:pauseForRapidTalentUpgrade(
                    "Ascension learned the awarded Talent Essence replacement but did not expose TALENT_UPGRADE_BONUS_LEARNED within ten seconds. The active Rapid session was left untouched."
                )
                return
            end
            self:armRapidUpgradeWatch()
            return
        end

        local activeBonusReady = isActiveUpgradeBonusState(
            state,
            self.api.canRollAbilities(),
            self.api.isRollRequestBlocked()
        )
        if activeBonusReady then
            if fromWatchdog then
                self.upgradeClaimStableChecks =
                    self.upgradeClaimStableChecks + 1
            else
                self.upgradeClaimStableChecks = 0
            end
            if self.upgradeClaimStableChecks
                < RAPID_UPGRADE_READY_STABLE_CHECKS then
                self.phase = "rapid_upgrade_claim_stabilizing"
                self:armRapidUpgradeWatch()
                return
            end
            self.upgradeReloadReady = true
            self.phase = "rapid_upgrade_reload_ready"
            self:pauseForReloadRecovery(
                self.stopAfterBatch
                    and "The exact broken Rapid Talent Essence state stayed stable for one second. Press Reload & finish to recover the accepted batch; the retired session cannot resume."
                    or "The exact broken Rapid Talent Essence state stayed stable for one second. Ascension requires a player click; press Reload & resume to recover it."
            )
            return
        end
        self.upgradeClaimStableChecks = 0
        if self.upgradeBoundaryWaitChecks
            >= RAPID_UPGRADE_READY_MAX_CHECKS then
            if isActiveUpgradeTimeoutState(
                state,
                self.api.canRollAbilities(),
                self.api.isRollRequestBlocked()
            ) then
                self.upgradeReloadReady = true
                self.phase = "rapid_upgrade_reload_ready"
                self:pauseForReloadRecovery(
                    self.stopAfterBatch
                        and "The Rapid talent upgrade remained active and blocked at AwaitingContinue for ten seconds. Press Reload & finish to recover the accepted batch; the retired session cannot resume."
                        or "The Rapid talent upgrade remained active and blocked at AwaitingContinue for ten seconds. Ascension requires a player click; press Reload & resume to recover it."
                )
                return
            end
            self:pauseForRapidTalentUpgrade(
                "Ascension never exposed a stable active BONUS_PENDING Talent Essence edge within ten seconds. The native Rapid session was not cancelled and no paid Scroll of Fortune roll was sent; press Resume to recheck it."
            )
            return
        end
        self:armRapidUpgradeWatch()
    end

    function controller:restoreReloadRecovery(checkpoint)
        if self:isBusy() then
            return false, "Another Rapid session is already active."
        end
        if type(checkpoint) ~= "table"
            or checkpoint.schema ~= 1
            or checkpoint.selectedSide ~= "talents"
            or type(checkpoint.link) ~= "string"
            or type(checkpoint.savedSelections) ~= "table"
            or type(checkpoint.rollsBySide) ~= "table"
            or tonumber(checkpoint.batches) == nil
            or checkpoint.ownsSelections ~= true then
            return false, "The Rapid reload checkpoint is incomplete."
        end
        local scrollsAtStart = normalizeBalances(
            checkpoint.scrollsAtStart
        )
        local batchStartBalances = normalizeBalances(
            checkpoint.batchStartBalances
        )
        if not scrollsAtStart or not batchStartBalances then
            return false,
                "The Rapid reload checkpoint has no trustworthy scroll balances."
        end
        local contextReady, contextError =
            self.api.ensureRapidContextReady()
        if not contextReady then
            return false, contextError
        end
        local balances, balanceError = self:readBalances()
        if not balances then
            return false, balanceError
        end
        if balances.specID ~= scrollsAtStart.specID
            or balances.specID ~= batchStartBalances.specID then
            return false,
                "The active specialization does not match the Rapid reload checkpoint."
        end

        local oldLink = self.link
        self.link = checkpoint.link
        local result = self:analyze()
        if not result.ok then
            self.link = oldLink
            return false,
                result.errors and result.errors[1]
                    or "The recovered build is no longer valid."
        end

        self.sessionLimit = normalizeSessionLimit(
            checkpoint.sessionLimit
        )
        self.highRollFloors = normalizeHighRollFloors(
            checkpoint.highRollFloors
        )
        self.rollSides = normalizeRollSides(checkpoint.rollSides)
        self.autoReloadEnabled = false
        self.allowStandardTalentScrolls =
            checkpoint.allowStandardTalentScrolls and true or false
        self.scrollsAtStart = scrollsAtStart
        self.rollsBySide = {
            abilities = normalizeCount(
                checkpoint.rollsBySide
                    and checkpoint.rollsBySide.abilities
            ),
            talents = normalizeCount(
                checkpoint.rollsBySide
                    and checkpoint.rollsBySide.talents
            ),
        }
        self.batches = normalizeCount(checkpoint.batches)
        self.rapidFundingRequirements = {}
        self.selectedSide = "talents"
        self.projection = copyProjection(checkpoint.projection)
        self.batchStartBalances = batchStartBalances
        self.savedSelections = {
            desired = copySelections(checkpoint.savedSelections.desired),
            undesired = copySelections(checkpoint.savedSelections.undesired),
        }
        self.ownsSelections = checkpoint.ownsSelections and true or false
        self.sessionLockedIDs = copyIDSet(checkpoint.sessionLockedIDs)
        self.managedBuildIdentity = checkpoint.managedBuildIdentity
        self.learnedThisBatch = {}
        self.stopAfterBatch = checkpoint.retireAfterRecovery == true
            and {
                reason = "The previous Rapid session ended after reload recovery because the build link changed. Start the updated build explicitly.",
                kind = "rapid_stopped",
            }
            or nil
        self:advanceLifecycle()
        self.lastState = nil
        self.rapidStateWatchArmed = false
        self.inFlightStateKey = nil
        self.inFlightStateChecks = 0
        self:resetRapidTalentUpgrade()
        self.batchActive = true
        self.batchFinalizing = false
        self.upgradeBoundaryActive = true
        self.upgradeLastLearnedKey =
            checkpoint.upgradeLastLearnedKey
        self.reloadRecoveryActive = true
        self.reloadRecoveryUsed = true
        self.running = true
        self.paused = false
        self.worldSuspended = false
        self.phase = "rapid_reload_recovering"
        self:notify(
            "rapid_reload_resumed",
            "Recovered the interrupted Rapid batch after the addon-initiated UI reload; reconciling the awarded Talent Essence before another paid batch."
        )
        self:advanceRapidReloadRecovery(self.api.getRapidState())
        return true
    end

    function controller:advanceRapidReloadRecovery(
        state,
        fromWatchdog
    )
        if self.worldSuspended
            or not self.batchActive
            or not self.upgradeBoundaryActive
            or not self.reloadRecoveryActive
            or self.batchFinalizing
            or self.upgradeReplacementPending then
            return
        end
        local recoveryBlock = type(
            self.api.getRapidRecoveryBlockReason
        ) == "function" and self.api.getRapidRecoveryBlockReason()
        if recoveryBlock then
            self:pauseForRapidTalentUpgrade(
                "Post-reload Talent Essence recovery paused: "
                    .. tostring(recoveryBlock)
                    .. " Press Resume after clearing it."
            )
            return
        end
        state = state or self.api.getRapidState()
        self.lastState = state
        if fromWatchdog then
            self.upgradeBoundaryWaitChecks =
                self.upgradeBoundaryWaitChecks + 1
        end
        local released = isReleasedRapidState(state)
            and not self.api.isRollRequestBlocked()
        if not released then
            self.upgradeClaimStableChecks = 0
            if self.upgradeBoundaryWaitChecks
                >= RAPID_UPGRADE_READY_MAX_CHECKS then
                self:pauseForRapidTalentUpgrade(
                    "The addon-initiated reload did not release the native Rapid request within ten seconds. No second reload or paid batch was sent."
                )
                return
            end
            self.phase = "rapid_reload_recovering"
            self:armRapidUpgradeWatch()
            return
        end
        if fromWatchdog then
            self.upgradeClaimStableChecks =
                self.upgradeClaimStableChecks + 1
        else
            self.upgradeClaimStableChecks = 0
        end
        if self.upgradeClaimStableChecks
            < RAPID_UPGRADE_READY_STABLE_CHECKS then
            self.phase = "rapid_reload_stabilizing"
            self:armRapidUpgradeWatch()
            return
        end

        if not self.api.canRollAbilities() then
            self:notify(
                "rapid_reload_reconciled",
                self.upgradeReplacementReceived
                    and "The recovered Talent Essence replacement finished and the clean client request boundary is stable."
                    or "The UI reload already resolved the awarded Talent Essence; the clean client request boundary is stable."
            )
            self:completeReloadRecovery()
            return
        end
        if self.upgradeReplacementAttempts
            >= RAPID_RELOAD_RECOVERY_MAX_CLAIMS then
            self:pauseForRapidTalentUpgrade(
                "Post-reload recovery reached five chained awarded Talent Essence claims. It paused without another reload or paid batch."
            )
            return
        end

        self.upgradeReplacementAttempts =
            self.upgradeReplacementAttempts + 1
        self.upgradeReplacementPending = true
        self.upgradeReplacementReceived = false
        self.upgradeReplacementLearnChecks = 0
        self.phase = "rapid_reload_replacement_waiting"
        local sent, reason = self.api.requestPendingRoll()

        -- A learned event can be delivered synchronously from RollAbilities.
        if not self.batchActive
            or not self.reloadRecoveryActive
            or not self.upgradeReplacementPending then
            return
        end
        if not sent then
            self.upgradeReplacementPending = false
            self:pauseForRapidTalentUpgrade(
                "The clean post-reload Talent Essence request was rejected ("
                    .. reasonText(reason)
                    .. "). It was not retried and no second reload or paid batch was sent."
            )
            return
        end
        self:notify(
            "rapid_reload_claimed",
            string.format(
                "Claimed the awarded Talent Essence from the clean post-reload boundary (chain %d/%d).",
                self.upgradeReplacementAttempts,
                RAPID_RELOAD_RECOVERY_MAX_CLAIMS
            )
        )
        self:armRapidReplacementWatch()
    end

    function controller:completeReloadRecovery()
        if not self.reloadRecoveryActive
            or not self.batchActive
            or self.batchFinalizing then
            return
        end
        self.batchFinalizing = true
        self.phase = "rapid_reload_finishing"
        local generation = self.lifecycleGeneration
        self.api.deferRapidSettle(function()
            if generation ~= self.lifecycleGeneration then
                return
            end
            if self.worldSuspended then
                self.batchFinalizing = false
                return
            end
            local balances, balanceError = self:readBalances()
            if not balances then
                self.batchFinalizing = false
                self:pauseForRapidTalentUpgrade(balanceError)
                return
            end
            local before = self.batchStartBalances
            local spent = before and talentPaidSpend(
                before,
                balances,
                self.allowStandardTalentScrolls
            ) or 0
            if spent <= 0 then
                self.batchFinalizing = false
                self:pauseForRapidTalentUpgrade(
                    "The UI reload cleared the client state, but the interrupted paid talent-batch delta could not be verified. No next batch was started."
                )
                return
            end
            self.rollsBySide.talents =
                self.rollsBySide.talents + spent
            self.batches = self.batches + 1
            self:notify(
                "rapid_batch",
                string.format(
                    "Rapid batch %d recovered after UI reload: spent %d talent scroll%s; session spent A %d / T %d.",
                    self.batches,
                    spent,
                    spent == 1 and "" or "s",
                    self.rollsBySide.abilities,
                    self.rollsBySide.talents
                ),
                {
                    engine = "rapid",
                    side = "talents",
                    spent = spent,
                    reloadRecovery = true,
                }
            )
            self.batchActive = false
            self.batchFinalizing = false
            self:resetRapidTalentUpgrade()
            self.api.cleanupRapidVisual()
            if self.stopAfterBatch then
                local pending = self.stopAfterBatch
                self.stopAfterBatch = nil
                self:finishStopped(pending.reason, pending.kind)
            elseif self.paused or not self.running then
                self.phase = "paused"
                self:restoreSelections()
            else
                self.phase = "ready"
                self:step()
            end
        end)
    end

    function controller:onRapidReplacementWatch()
        if self.worldSuspended
            or not self.batchActive
            or not self.upgradeBoundaryActive
            or not self.upgradeReplacementPending then
            return
        end
        self.upgradeReplacementLearnChecks =
            self.upgradeReplacementLearnChecks + 1
        if self.upgradeReplacementLearnChecks
            >= RAPID_UPGRADE_LEARN_MAX_CHECKS then
            self:pauseForRapidTalentUpgrade(
                self.reloadRecoveryActive
                    and "The accepted clean post-reload Talent Essence request produced no learned result within ten seconds. It was not retransmitted and no second reload or paid batch was sent."
                    or "The accepted Talent Essence request produced no learned result within ten seconds. It was not retransmitted and the native Rapid session was left untouched."
            )
            return
        end
        self:armRapidReplacementWatch()
    end

    function controller:finalizeBatch(state, stalledRecovery)
        if not self.batchActive or self.batchFinalizing then
            return
        end
        self.batchFinalizing = true
        self.rapidStateWatchArmed = false
        self.phase = "rapid_finishing"
        local finishingState = state or self.api.getRapidState()
        local generation = self.lifecycleGeneration
        self.api.deferRapidSettle(function()
            if generation ~= self.lifecycleGeneration then
                return
            end
            if self.worldSuspended then
                self.batchFinalizing = false
                return
            end
            local balances, balanceError = self:readBalances()
            if not balances then
                self.batchActive = false
                self.batchFinalizing = false
                self:stop(balanceError, "rapid_error")
                return
            end
            local before = self.batchStartBalances or balances
            local spent
            if self.selectedSide == "abilities" then
                spent = math.max(
                    0,
                    abilityBalance(before) - abilityBalance(balances)
                )
            else
                spent = talentPaidSpend(
                    before,
                    balances,
                    self.allowStandardTalentScrolls
                )
            end
            if spent <= 0 then
                if stalledRecovery and #self.learnedThisBatch == 0 then
                    self:notify(
                        "rapid_recovered",
                        "The stalled native Rapid phase ended before any measurable scroll spend; rebuilding without counting a batch."
                    )
                else
                    if not self.stopAfterBatch then
                        self.running = false
                        self.paused = false
                        self.stopAfterBatch = {
                            reason =
                                "The native Rapid batch ended, but its paid scroll delta could not be verified. No next batch was started.",
                            kind = "rapid_error",
                        }
                    end
                    self:notify(
                        "rapid_accounting_error",
                        "Rapid ended without a measurable scroll delta. The advertised native batch maximum was not counted as spending."
                    )
                end
            else
                self.rollsBySide[self.selectedSide] =
                    self.rollsBySide[self.selectedSide] + spent
                self.batches = self.batches + 1
                self:notify(
                    "rapid_batch",
                    string.format(
                        "Rapid batch %d finished: spent %d %s scroll%s; session spent A %d / T %d.",
                        self.batches,
                        spent,
                        self.selectedSide == "talents" and "talent" or "ability",
                        spent == 1 and "" or "s",
                        self.rollsBySide.abilities,
                        self.rollsBySide.talents
                    ),
                    {
                        engine = "rapid",
                        side = self.selectedSide,
                        spent = spent,
                        state = finishingState,
                    }
                )
            end

            self.batchActive = false
            self:resetRapidTalentUpgrade()
            self.api.finishRapidSession(function(ready, readyReason)
                if generation ~= self.lifecycleGeneration then
                    return
                end
                self.batchFinalizing = false
                self.api.cleanupRapidVisual()
                if not ready then
                    self:finishStopped(
                        "The native Rapid session did not become ready: "
                            .. tostring(readyReason),
                        "rapid_error"
                    )
                    return
                end
                if self.stopAfterBatch then
                    local pending = self.stopAfterBatch
                    self.stopAfterBatch = nil
                    self:finishStopped(pending.reason, pending.kind)
                elseif self.paused or not self.running then
                    self.phase = "paused"
                    self:restoreSelections()
                else
                    self.phase = "ready"
                    self:step()
                end
            end, function()
                return generation == self.lifecycleGeneration
            end, function()
                return self.worldSuspended
            end)
        end)
    end

    function controller:onRapidStateChanged(fromWatchdog)
        if not self:isBusy() or self.worldSuspended then
            return
        end
        local state = self.api.getRapidState()
        self.lastState = state
        if not state or not state.Phase then
            return
        end
        if self.batchActive
            and self.upgradeBoundaryActive
            and self.reloadRecoveryActive then
            if self.phase == "rapid_upgrade_manual"
                and self.paused then
                return
            end
            self:advanceRapidReloadRecovery(state, fromWatchdog)
            return
        end
        if self.batchActive
            and state.Phase == "AwaitingContinue"
            and state.StopCode == RAPID_UPGRADE_BONUS_LEARNED then
            self:notify(
                "rapid_bonus_complete",
                "The Talent Essence replacement was learned; finishing this exhausted Rapid batch and rebuilding its projection."
            )
            self:finalizeBatch(state)
            return
        end
        if self.batchActive and self.upgradeBoundaryActive then
            if self.phase == "rapid_upgrade_manual"
                and self.paused then
                return
            end
            self:advanceRapidTalentUpgradeBoundary(
                state,
                fromWatchdog
            )
            return
        end
        if self.batchActive
            and state.StopCode == RAPID_UPGRADE_BONUS_PENDING then
            self:notify(
                "rapid_upgrade_late_recovery",
                "The Rapid upgrade learned event was missed; recovering the awarded Talent Essence from the active BONUS_PENDING boundary without cancelling it."
            )
            self:beginRapidTalentUpgradeBoundary(state)
            return
        end
        self:resetRapidTalentUpgrade()
        if IN_FLIGHT_PHASES[state.Phase] then
            local stateKey = table.concat({
                tostring(state.Phase),
                tostring(state.RollCount),
                tostring(state.StopCode),
            }, ":")
            if fromWatchdog then
                if self.inFlightStateKey == stateKey then
                    self.inFlightStateChecks =
                        self.inFlightStateChecks + 1
                else
                    self.inFlightStateKey = stateKey
                    self.inFlightStateChecks = 1
                end
            else
                self.inFlightStateKey = stateKey
                self.inFlightStateChecks = 0
            end
            if self.inFlightStateChecks
                >= RAPID_IN_FLIGHT_MAX_CHECKS then
                self:notify(
                    "rapid_recovering",
                    string.format(
                        "Native Rapid made no progress in %s for %d checks; ending this batch safely and rebuilding it.",
                        tostring(state.Phase),
                        self.inFlightStateChecks
                    )
                )
                self:finalizeBatch(state, true)
                return
            end
            self.phase = "rapid_" .. state.Phase
            self:armRapidStateWatch()
            return
        end
        self.inFlightStateKey = nil
        self.inFlightStateChecks = 0
        if self.batchActive
            and (
                state.Phase == "AwaitingContinue"
                or TERMINAL_PHASES[state.Phase]
                or state.Phase == "Idle"
            ) then
            if state.Phase == "Failed" then
                self.running = false
                self.paused = false
                self.stopAfterBatch = {
                    reason = "The native Rapid batch failed: "
                        .. reasonText(
                            state.Reason
                                or state.StopCode
                                or state.CanStartReason
                        ),
                    kind = "rapid_error",
                }
            elseif state.Phase == "Cancelled"
                and not self.batchFinalizing then
                self.running = false
                self.paused = false
                self.stopAfterBatch = {
                    reason = "The native Rapid batch was cancelled.",
                    kind = "rapid_stopped",
                }
            end
            self:finalizeBatch(state)
        end
    end

    function controller:recordRapidLearned(
        internalID,
        newRank,
        preRollRank,
        reason,
        freeReplacement
    )
        local entry = self.api.getEntryByInternalID(internalID)
        local isUpgrade = tonumber(preRollRank)
            and tonumber(preRollRank) > 0
        local desiredSnapshot = self.projection
            and self.projection.desiredDetails
            and self.projection.desiredDetails[tostring(internalID)]
        local data = {
            engine = "rapid",
            entryID = internalID,
            name = entry and entry.Name
                or ("Entry #" .. tostring(internalID)),
            side = entrySide(entry) or self.selectedSide,
            newRank = newRank,
            preRollRank = preRollRank,
            reason = reason,
            batch = self.batches + 1,
            freeReplacement = freeReplacement and true or false,
            desiredSnapshot = copyDesiredDetail(desiredSnapshot),
        }
        self.learnedThisBatch[#self.learnedThisBatch + 1] = data
        self:notify(
            isUpgrade and "upgrade" or "result",
            isUpgrade
                and string.format(
                    "%s%s upgraded %s→%s.",
                    freeReplacement
                        and "Rapid Talent Essence replacement: "
                        or "Rapid result: ",
                    data.name,
                    tostring(preRollRank),
                    tostring(newRank)
                )
                or string.format(
                    "%slearned %s.",
                    freeReplacement
                        and "Rapid Talent Essence replacement: "
                        or "Rapid result: ",
                    data.name
                ),
            data
        )
        return data, isUpgrade
    end

    function controller:onUpgradeReplacementLearned(
        internalID,
        newRank,
        preRollRank,
        reason
    )
        if not self.batchActive or not self.upgradeBoundaryActive then
            return false
        end
        local key = learnedKey(internalID, newRank, preRollRank)
        if self.upgradeLastLearnedKey == key then
            -- Rapid and generic learned events can describe the same result.
            return true
        end
        self.rapidUpgradeWatchArmed = false
        self.rapidUpgradeWatchGeneration =
            self.rapidUpgradeWatchGeneration + 1
        self.upgradeReplacementPending = false
        self.rapidReplacementWatchArmed = false
        self.rapidReplacementWatchGeneration =
            self.rapidReplacementWatchGeneration + 1
        self.upgradeLastLearnedKey = key
        local _, isUpgrade = self:recordRapidLearned(
            internalID,
            newRank,
            preRollRank,
            reason,
            true
        )
        self.upgradeBoundaryWaitChecks = 0
        self.upgradeClaimStableChecks = 0
        self.upgradeReplacementLearnChecks = 0
        if isUpgrade then
            self.upgradeReplacementReceived = false
            self.upgradeReplacementAttempts = 0
            self.phase = "rapid_upgrade_essence_waiting"
            self:notify(
                "rapid_upgrade_chain",
                "The Talent Essence replacement upgraded another talent; waiting for the next awarded essence inside the same active Rapid session."
            )
            self:armRapidUpgradeWatch()
            return true
        end
        self.upgradeReplacementReceived = true
        self.phase = "rapid_upgrade_completion_waiting"
        self:notify(
            "rapid_upgrade_complete",
            "The Talent Essence replacement was learned inside Rapid; waiting for Ascension's BONUS_LEARNED batch boundary before cleanup."
        )
        self:armRapidUpgradeWatch()
        return true
    end

    function controller:onReloadRecoveryLearned(
        internalID,
        newRank,
        preRollRank,
        reason
    )
        if not self.reloadRecoveryActive
            or not self.batchActive
            or not self.upgradeBoundaryActive then
            return false
        end
        local key = learnedKey(internalID, newRank, preRollRank)
        if self.upgradeLastLearnedKey == key then
            return true
        end
        self.rapidUpgradeWatchArmed = false
        self.rapidUpgradeWatchGeneration =
            self.rapidUpgradeWatchGeneration + 1
        self.upgradeReplacementPending = false
        self.rapidReplacementWatchArmed = false
        self.rapidReplacementWatchGeneration =
            self.rapidReplacementWatchGeneration + 1
        self.upgradeLastLearnedKey = key
        local _, isUpgrade = self:recordRapidLearned(
            internalID,
            newRank,
            preRollRank,
            reason,
            true
        )
        self.upgradeBoundaryWaitChecks = 0
        self.upgradeClaimStableChecks = 0
        self.upgradeReplacementLearnChecks = 0
        self.upgradeReplacementReceived = true
        if isUpgrade then
            self.phase = "rapid_reload_chain_waiting"
            self:notify(
                "rapid_reload_chain",
                "The post-reload Talent Essence replacement upgraded another talent; waiting for its next awarded essence without another UI reload."
            )
        else
            self.phase = "rapid_reload_cleanup_waiting"
            self:notify(
                "rapid_reload_replacement",
                "The post-reload Talent Essence replacement was learned; waiting for a clean request boundary before resuming Rapid."
            )
        end
        self:armRapidUpgradeWatch()
        return true
    end

    function controller:onRollAbilitiesResult(result)
        if not self.upgradeBoundaryActive then
            return false
        end
        if self.reloadRecoveryActive then
            if result and result ~= "ROLL_ABILITIES_OK"
                and self.upgradeReplacementPending then
                self.upgradeReplacementPending = false
                self.rapidReplacementWatchArmed = false
                self.rapidReplacementWatchGeneration =
                    self.rapidReplacementWatchGeneration + 1
                self:pauseForRapidTalentUpgrade(
                    "The clean post-reload Talent Essence request failed: "
                        .. reasonText(result)
                        .. ". It was not retransmitted and no second reload or paid batch was sent."
                )
            end
            return true
        end
        return true
    end

    function controller:onEntryLearned(
        internalID,
        newRank,
        preRollRank
    )
        if self.reloadRecoveryActive then
            return self:onReloadRecoveryLearned(
                internalID,
                newRank,
                preRollRank,
                "FREE_TALENT_UPGRADE_RELOAD_REPLACEMENT"
            )
        end
        return self:onUpgradeReplacementLearned(
            internalID,
            newRank,
            preRollRank,
            "FREE_TALENT_UPGRADE_REPLACEMENT"
        )
    end

    function controller:onRapidLearned(
        internalID,
        newRank,
        preRollRank,
        reason
    )
        if not self.batchActive then
            return false
        end
        if self.reloadRecoveryActive then
            return self:onReloadRecoveryLearned(
                internalID,
                newRank,
                preRollRank,
                reason
            )
        end
        if self.upgradeBoundaryActive then
            return self:onUpgradeReplacementLearned(
                internalID,
                newRank,
                preRollRank,
                reason
            )
        end
        self:resetRapidTalentUpgrade()
        self.inFlightStateKey = nil
        self.inFlightStateChecks = 0
        local _, isUpgrade = self:recordRapidLearned(
            internalID,
            newRank,
            preRollRank,
            reason,
            false
        )
        if isUpgrade then
            self.upgradeLastLearnedKey = learnedKey(
                internalID,
                newRank,
                preRollRank
            )
            -- Keep Rapid active. Cancelling or calling RollAbilities at this
            -- overlap is rejected or can permanently relatch the client's
            -- Wildcard request. A stable BONUS_PENDING edge is recovered only
            -- through an explicitly authorized, checkpointed UI reload.
            self:beginRapidTalentUpgradeBoundary(
                self.api.getRapidState()
            )
        else
            local generation = self.lifecycleGeneration
            self.api.deferRapidState(function()
                if generation ~= self.lifecycleGeneration then
                    return
                end
                self:onRapidStateChanged()
            end)
        end
        return true
    end

    function controller:onRapidResult(result)
        if not self.batchActive then
            return
        end
        self:notify(
            "rapid_native_result",
            "Native Rapid result: " .. reasonText(result) .. "."
        )
        local generation = self.lifecycleGeneration
        self.api.deferRapidState(function()
            if generation ~= self.lifecycleGeneration then
                return
            end
            self:onRapidStateChanged()
        end)
    end

    function controller:start(
        link,
        sessionLimit,
        autoReloadEnabled,
        highRollFloors,
        allowStandardTalentScrolls,
        rollSides
    )
        if self:isBusy() then
            return false, "Rapid auto-roll is already active or paused."
        end
        local ready, readyError = self.api.ensureRapidReady()
        if not ready then
            return false, readyError
        end
        self.link = tostring(link or "")
        local result = self:analyze()
        if not result.ok then
            return false,
                result.errors and result.errors[1]
                    or "Build validation failed."
        end
        local balances, balanceError = self:readBalances()
        if not balances then
            return false, balanceError
        end
        local normalizedHighRollFloors =
            normalizeHighRollFloors(highRollFloors)
        local normalizedStandardTalentFallback =
            allowStandardTalentScrolls and true or false
        local normalizedRollSides = normalizeRollSides(rollSides)
        if not normalizedRollSides.abilities
            and not normalizedRollSides.talents then
            return false, "Enable Abilities, Talents, or both before starting Rapid mode."
        end
        self.rapidFundingRequirements = {}
        local projection, projectionError = self:chooseProjection(
            result,
            balances,
            normalizedHighRollFloors,
            normalizedStandardTalentFallback,
            normalizedRollSides
        )
        if not projection then
            return false, projectionError
        end

        self.managedBuildIdentity = result.parsed and result.parsed.identity
        if type(self.api.prepareManagedAnyLocks) == "function" then
            self.api.prepareManagedAnyLocks(self.managedBuildIdentity)
        end

        self:advanceLifecycle()
        self.sessionLimit = normalizeSessionLimit(sessionLimit)
        self.highRollFloors = normalizedHighRollFloors
        self.rollSides = normalizedRollSides
        self.autoReloadEnabled = false
        self.allowStandardTalentScrolls =
            normalizedStandardTalentFallback
        self.savedSelections = self.api.getSavedRapidSelections()
            or { desired = {}, undesired = {} }
        self.scrollsAtStart = balances
        self.rollsBySide = {
            abilities = 0,
            talents = 0,
        }
        self.batches = 0
        self.selectedSide = nil
        self.projection = nil
        self.batchStartBalances = nil
        self.batchActive = false
        self.batchFinalizing = false
        self:resetRapidTalentUpgrade()
        self.ownsSelections = false
        self.pendingLockID = nil
        self.pendingLockName = nil
        self.pendingLockAttempts = 0
        self.pendingLockTarget = nil
        self.pendingUnlockID = nil
        self.pendingUnlockName = nil
        self.pendingUnlockAttempts = 0
        self.pendingUnlockTarget = nil
        self.sessionLockedIDs = {}
        self.learnedThisBatch = {}
        self.stopAfterBatch = nil
        self.lastState = nil
        self.rapidStateWatchArmed = false
        self.inFlightStateKey = nil
        self.inFlightStateChecks = 0
        self.running = true
        self.paused = false
        self.worldSuspended = false
        self.phase = "ready"
        self:notify(
            "rapid_started",
            string.format(
                "Started Rapid auto-roll%s. Roll types: %s. High-roll floors: A %d / T %d (0 = exact). Standard-scroll talent fallback: %s. Initial projection: %s — %s.",
                self.sessionLimit
                    and string.format(
                        " with a limit of %d paid rolls",
                        self.sessionLimit
                    )
                    or " without a session limit",
                self.rollSides.abilities and self.rollSides.talents
                    and "Abilities and Talents"
                    or self.rollSides.abilities
                        and "Abilities only" or "Talents only",
                self.highRollFloors.abilities,
                self.highRollFloors.talents,
                self.allowStandardTalentScrolls and "enabled" or "disabled",
                projection.side,
                projection.reason
            ),
            {
                engine = "rapid",
                projection = projection,
            }
        )
        self:step()
        return true
    end

    return controller
end

return M

end)()
addon.uiModule = (function()
local M = {}
local canonicalSpellID = addon.core.canonicalSpellID

local CATEGORY_LABELS = {
