    rapid_reload_finishing = "Accounting for the recovered Rapid batch",
    rapid_upgrade_manual = "Upgrade recovery paused",
}

local PLAN_ENTRY_HEIGHT = 22
local PLAN_ENTRY_STEP = 23
local PLAN_SECTION_HEIGHT = 18
local PLAN_SECTION_STEP = 19
local PLAN_ICON_SIZE = 16
local SLOT_LIMITS = {
    abilities = 30,
    talents = 25,
}
local SLOT_PROGRESS_COLORS = {
    complete = { 0.13, 0.72, 0.25, 1.00 },
    incomplete = { 0.92, 0.67, 0.12, 1.00 },
    replaceable = { 0.13, 0.43, 0.82, 1.00 },
    empty = { 0.09, 0.09, 0.09, 1.00 },
}

local function normalizeSessionLimit(value)
    value = tonumber(value)
    if not value or value <= 0 then
        return nil
    end
    return math.floor(value)
end

local function normalizeCount(value)
    value = tonumber(value)
    if not value or value < 0 then
        return 0
    end
    return math.floor(value)
end

local function sideNoun(side)
    return side == "abilities" and "ability" or "talent"
end

local function sideTitle(side)
    return side == "abilities" and "ABILITY" or "TALENT"
end

local function rollOffStateForSide(state, side)
    if not state then
        return nil
    end
    if state.side == side then
        return state
    end
    if state.side == "both" and state.states then
        return state.states[side]
    end
    return nil
end

local function combineRollOffStates(abilityState, talentState)
    if abilityState and talentState then
        return {
            side = "both",
            states = {
                abilities = abilityState,
                talents = talentState,
            },
        }
    end
    return abilityState or talentState
end

local function singleRollOffDemandText(state)
    state = state or {}
    local parts = {}
    local missing = normalizeCount(state.missing)
    local ranks = normalizeCount(
        state.rankIncomplete ~= nil
            and state.rankIncomplete or state.incomplete
    )
    if missing > 0 then
        parts[#parts + 1] = string.format(
            "%d build entr%s missing",
            missing,
            missing == 1 and "y" or "ies"
        )
    end
    if ranks > 0 then
        parts[#parts + 1] = string.format(
            "%d rank%s incomplete",
            ranks,
            ranks == 1 and "" or "s"
        )
    end
    return #parts > 0 and table.concat(parts, " · ")
        or (sideNoun(state.side) .. " plan incomplete")
end

local function rollOffDemandText(state)
    if state and state.side == "both" then
        local parts = {}
        for _, side in ipairs({ "abilities", "talents" }) do
            local current = rollOffStateForSide(state, side)
            if current then
                parts[#parts + 1] = sideTitle(side):sub(1, 1)
                    .. " " .. singleRollOffDemandText(current)
            end
        end
        return table.concat(parts, " · ")
    end
    return singleRollOffDemandText(state)
end

local function rollOffSlotsText(state)
    if state and state.side == "both" then
        return "Ability and talent slots full"
    end
    local side = state and state.side or "talents"
    local limit = normalizeCount(state and state.limit)
    if limit <= 0 then
        limit = side == "abilities" and 30 or 25
    end
    return string.format(
        "%d %s slots full",
        limit,
        sideNoun(side)
    )
end

local function rollOffChoiceNoun(state)
    return state and state.side == "both"
        and "entry" or sideNoun(state and state.side)
end

local function initializeHighRollSettings(db)
    db = type(db) == "table" and db or {}
    if not db.highRollProtectionInitialized then
        local configured = db.highRollAbilityFloor ~= nil
            or db.highRollTalentFloor ~= nil
        db.highRollAbilityFloor = configured
            and normalizeCount(db.highRollAbilityFloor)
            or 0
        db.highRollTalentFloor = configured
            and normalizeCount(db.highRollTalentFloor)
            or 0
        db.highRollProtectionInitialized = true
    else
        db.highRollAbilityFloor = normalizeCount(
            db.highRollAbilityFloor
        )
        db.highRollTalentFloor = normalizeCount(
            db.highRollTalentFloor
        )
    end
    return {
        abilities = db.highRollAbilityFloor,
        talents = db.highRollTalentFloor,
    }
end

M.initializeHighRollSettings = initializeHighRollSettings

local function highRollDescription(floors)
    floors = type(floors) == "table" and floors or {}
    return string.format(
        "High-roll floors: A %d / T %d (0 = exact).",
        normalizeCount(floors.abilities),
        normalizeCount(floors.talents)
    )
end

local function normalizeRollSides(value)
    value = type(value) == "table" and value or {}
    return {
        abilities = value.abilities ~= false,
        talents = value.talents ~= false,
    }
end

local function sameRollSides(left, right)
    left = normalizeRollSides(left)
    right = normalizeRollSides(right)
    return left.abilities == right.abilities
        and left.talents == right.talents
end

local function rollSideDescription(value)
    value = normalizeRollSides(value)
    if value.abilities and value.talents then
        return "Abilities and Talents"
    elseif value.abilities then
        return "Abilities only"
    elseif value.talents then
        return "Talents only"
    end
    return "None"
end

local function rollSideNotice(value)
    value = normalizeRollSides(value)
    if value.abilities and not value.talents then
        return "ABILITIES ONLY"
    elseif value.talents and not value.abilities then
        return "TALENTS ONLY"
    elseif not value.abilities and not value.talents then
        return "NO ROLL TYPES ENABLED"
    end
end

local function trim(value)
    return tostring(value or ""):match("^%s*(.-)%s*$") or ""
end

local function decodePercentEncoded(value)
    return tostring(value or ""):gsub("%%(%x%x)", function(hex)
        return string.char(tonumber(hex, 16))
    end)
end

local function customPayloadFromLink(value)
    local normalized = decodePercentEncoded(value)
    return normalized:match("[#?&]build=v1%.([A-Za-z0-9_-]+)")
        or normalized:match("^build=v1%.([A-Za-z0-9_-]+)")
end

local UI_MAX_SPELL_ID = 2147483647

local function uiIsInteger(value, minimum, maximum)
    return type(value) == "number"
        and value == math.floor(value)
        and value >= minimum
        and value <= maximum
end

local function uiSideLimit(side)
    return side == "talents" and 100 or 120
end

local function buildKey(value)
    value = decodePercentEncoded(trim(value))
    local marker = string.find(value, "#b=", 1, true)
    if marker then
        value = string.sub(value, marker + 3)
        value = value:match("^([^%s]+)") or ""
    elseif string.sub(value, 1, 3) == "#b=" then
        value = string.sub(value, 4)
    end
    return value
end

M.buildKey = buildKey

local function optionalCategoryName(category)
    local name = trim(category and category.name)
    if name ~= "" then
        return name
    end
    if category and category.kind == "any" then
        return "Unnamed any-of group"
    elseif category and category.kind == "nice" then
        return "Nice to keep"
    end
    return "Uncategorized"
end

local function optionalCategorySummary(categories)
    local active = 0
    for _, category in ipairs(categories or {}) do
        if category.enabled then
            active = active + 1
        end
    end
    return active, #(categories or {})
end

local function createCategoryToggle(parent)
    local toggle = CreateFrame("CheckButton", nil, parent)
    toggle:SetSize(28, 14)

    local track = toggle:CreateTexture(nil, "BACKGROUND")
    track:SetTexture("Interface\\Buttons\\WHITE8X8")
    track:SetPoint("TOPLEFT", 0, 0)
    track:SetPoint("BOTTOMRIGHT", 0, 0)
    toggle.Track = track

    local knob = toggle:CreateTexture(nil, "ARTWORK")
    knob:SetTexture("Interface\\Buttons\\WHITE8X8")
    knob:SetSize(10, 10)
    toggle.Knob = knob

    toggle:SetScript("OnEnter", function(current)
        if not GameTooltip then
            return
        end
        GameTooltip:SetOwner(current, "ANCHOR_RIGHT")
        GameTooltip:SetText(current.categoryLabel or "Auto-Roll category")
        if GameTooltip.AddLine then
            GameTooltip:AddLine(
                current:GetChecked()
                    and "Auto-Roll: on"
                    or "Auto-Roll: off",
                current:GetChecked() and 0.42 or 0.70,
                current:GetChecked() and 0.82 or 0.70,
                current:GetChecked() and 1.00 or 0.70
            )
            GameTooltip:AddLine(
                current:GetChecked()
                    and "This category participates normally."
                    or "This category is absent from the rolling plan.",
                0.78,
                0.78,
                0.74,
                true
            )
        end
        GameTooltip:Show()
    end)
    toggle:SetScript("OnLeave", function()
        if GameTooltip then
            GameTooltip:Hide()
        end
    end)
    return toggle
end

local function paintCategoryToggle(toggle, enabled, editable)
    if not toggle then
        return
    end
    toggle:SetChecked(enabled and true or false)
    if toggle.Track then
        if enabled then
            toggle.Track:SetVertexColor(0.15, 0.43, 0.62, 1.00)
        else
            toggle.Track:SetVertexColor(0.20, 0.22, 0.24, 1.00)
        end
    end
    if toggle.Knob then
        toggle.Knob:ClearAllPoints()
        toggle.Knob:SetPoint(enabled and "RIGHT" or "LEFT", enabled and -2 or 2, 0)
        toggle.Knob:SetVertexColor(
            enabled and 0.84 or 0.58,
            enabled and 0.94 or 0.61,
            enabled and 1.00 or 0.64,
            1.00
        )
    end
    if editable then
        toggle:Enable()
    else
        toggle:Disable()
    end
end

M.optionalCategoryName = optionalCategoryName
M.optionalCategorySummary = optionalCategorySummary

local function abilityBalance(balances)
    return normalizeCount(balances and balances.abilities)
        + normalizeCount(balances and balances.shared)
end

local function addButton(parent, name, text, width)
    local button = _G[name] or CreateFrame(
        "Button",
        name,
        parent,
        "UIPanelButtonTemplate"
    )
    button:SetSize(width or 110, 22)
    button:SetText(text)
    return button
end

local function setButtonEnabled(button, enabled)
    if not button then
        return
    end
    button:SetEnabled(enabled and true or false)
end

local function raise(panel)
    panel:SetFrameStrata("FULLSCREEN_DIALOG")
    local level = 100
    if CharacterAdvancement and CharacterAdvancement.GetFrameLevel then
        level = math.max(level, CharacterAdvancement:GetFrameLevel() + 100)
    end
    panel:SetFrameLevel(level)
end

-- The Auto-Roll panel deliberately sits above Character Advancement on the
-- FULLSCREEN_DIALOG strata. Stock StaticPopup frames normally use DIALOG, so
-- an otherwise valid confirmation can be rendered behind this panel. Lift
-- every addon-owned confirmation to the top strata returned by the client.
local function showConfirmationPopup(panel, ...)
    local popup = StaticPopup_Show(...)
    if not popup then
        return nil
    end
    if popup.SetFrameStrata then
        popup:SetFrameStrata("TOOLTIP")
    end
    if popup.SetFrameLevel then
        local level = 200
        if panel and panel.GetFrameLevel then
            level = math.max(level, panel:GetFrameLevel() + 100)
        end
        popup:SetFrameLevel(level)
    end
    if popup.Raise then
        popup:Raise()
    end
    return popup
end

local function clamp(value, minimum, maximum)
    return math.max(minimum, math.min(maximum, value))
end

local function createBox(parent)
    local frame = CreateFrame("Frame", nil, parent)
    frame:SetBackdrop({
        bgFile = "Interface\\ChatFrame\\ChatFrameBackground",
        edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
        tile = true,
        tileSize = 16,
        edgeSize = 12,
        insets = { left = 3, right = 3, top = 3, bottom = 3 },
    })
    frame:SetBackdropColor(0.025, 0.025, 0.025, 0.94)
    frame:SetBackdropBorderColor(0.45, 0.40, 0.25, 0.72)
    return frame
end

