local function searchText(value)
    value = string.lower(tostring(value or ""))
    value = value:gsub("[^%w]+", " ")
    return trim(value)
end

local function compactSearchText(value)
    return searchText(value):gsub("%s+", "")
end

local function entryBelongsToSide(entry, side)
    if side == "talents" then
        return entry.type == "Talent"
    end
    return entry.type == "Ability" or entry.type == "TalentAbility"
end

local function fuzzyEntryScore(query, name)
    local normalizedQuery = searchText(query)
    local normalizedName = searchText(name)
    if normalizedQuery == "" or normalizedName == "" then
        return nil
    end
    if normalizedName == normalizedQuery then
        return 100000
    end

    local compactQuery = compactSearchText(normalizedQuery)
    local compactName = compactSearchText(normalizedName)
    if compactQuery == compactName then
        return 95000
    end

    local directStart = compactName:find(compactQuery, 1, true)
    if directStart then
        return 80000 - directStart - (#compactName - #compactQuery) * 0.01
    end

    local matched = 0
    for token in normalizedQuery:gmatch("%S+") do
        if normalizedName:find(token, 1, true) then
            matched = matched + 1
        else
            local tokenStart = normalizedName:find(token:sub(1, 1), 1, true)
            if not tokenStart then
                return nil
            end
        end
    end
    if matched > 0 then
        return 60000 + matched * 100 - (#normalizedName * 0.01)
    end

    local cursor = 1
    local gaps = 0
    for index = 1, #compactQuery do
        local character = compactQuery:sub(index, index)
        local found = compactName:find(character, cursor, true)
        if not found then
            return nil
        end
        gaps = gaps + found - cursor
        cursor = found + 1
    end
    return 40000 - gaps - (#compactName - #compactQuery) * 0.01
end

local function fuzzyEntryMatches(side, query, limit)
    local results = {}
    local seen = {}
    local normalizedQuery = searchText(query)
    if normalizedQuery == "" then
        return results
    end
    for _, entry in ipairs(ADDON_ENTRY_CATALOG) do
        local id = tonumber(entry.id)
        local logicalName = searchText(entry.name)
        if id and logicalName ~= "" and not seen[logicalName]
            and entryBelongsToSide(entry, side) then
            local score = fuzzyEntryScore(normalizedQuery, entry.name)
            if score then
                seen[logicalName] = true
                results[#results + 1] = {
                    id = id,
                    name = entry.name,
                    score = score,
                }
            end
        end
    end
    table.sort(results, function(left, right)
        if left.score ~= right.score then
            return left.score > right.score
        end
        local leftName = string.lower(left.name or "")
        local rightName = string.lower(right.name or "")
        if leftName ~= rightName then
            return leftName < rightName
        end
        return left.id < right.id
    end)
    local maximum = math.min(limit or 6, #results)
    for index = #results, maximum + 1, -1 do
        results[index] = nil
    end
    return results
end

-- Exact names may map to multiple live spell IDs (for example, rank or
-- class variants). They are one logical requirement, so expose one ID;
-- resolveEntryBySpellID accepts the equivalent variants during analysis.
local function exactEntryMatches(side, query)
    local results = {}
    local seen = {}
    local normalizedQuery = searchText(query)
    if normalizedQuery == "" then
        return results
    end
    for _, entry in ipairs(ADDON_ENTRY_CATALOG) do
        local id = tonumber(entry.id)
        if id
            and not seen[id]
            and entryBelongsToSide(entry, side)
            and searchText(entry.name) == normalizedQuery then
            seen[id] = true
            results[#results + 1] = {
                id = id,
                name = entry.name,
                score = 100000,
            }
        end
    end
    table.sort(results, function(left, right)
        return left.id < right.id
    end)
    for index = #results, 2, -1 do
        results[index] = nil
    end
    return results
end

local function styleInputBox(box)
    if not box then
        return
    end
    if type(box.SetTextColor) == "function" then
        box:SetTextColor(1.00, 0.96, 0.82, 1.00)
    end
    if type(box.SetDisabledTextColor) == "function" then
        box:SetDisabledTextColor(1.00, 0.96, 0.82, 1.00)
    end
end

local function getEntryStatus(item)
    if not item or not item.known then
        return "missing", STATUS_STYLES.missing
    end
    local currentRank = normalizeCount(item.currentRank)
    local maxRank = math.max(
        1,
        normalizeCount(item.maxRank),
        normalizeCount(item.targetRank)
    )
    if item.side == "talents" and currentRank < maxRank then
        return "upgrade", STATUS_STYLES.upgrade
    end
    return "owned", STATUS_STYLES.owned
end

M.getEntryStatus = getEntryStatus

local function progressEntryKey(item)
    if not item then
        return nil
    end
    return tostring(item.entryID or item.spellID or item)
end

function M.buildSlotProgress(result, side)
    local limit = SLOT_LIMITS[side] or 0
    local progress = {
        available = result and result.ok and true or false,
        limit = limit,
        found = 0,
        complete = 0,
        incomplete = 0,
        replaceable = 0,
        empty = limit,
        known = 0,
    }
    local state = result
        and result.ok
        and result.sides
        and result.sides[side]
    if not state then
        return progress
    end

    local seenKnown = {}
    local discoveredKnown = 0
    local function countKnown(item)
        local key = progressEntryKey(item)
        if item and item.known and key and not seenKnown[key] then
            seenKnown[key] = true
            discoveredKnown = discoveredKnown + 1
        end
    end

    for _, section in ipairs(state.sections or {}) do
        for _, item in ipairs(section.items or {}) do
            countKnown(item)
            local retained = item.known and (
                section.kind ~= "any"
                or item.role == "protected"
            )
            if retained then
                progress.found = progress.found + 1
                local status = getEntryStatus(item)
                if side == "talents" and status == "upgrade" then
                    progress.incomplete = progress.incomplete + 1
                else
                    progress.complete = progress.complete + 1
                end
            end
        end
    end
    for _, item in ipairs(state.learnedNonbuild or {}) do
        countKnown(item)
    end
    for _, item in ipairs(state.learnedSynergies or {}) do
        countKnown(item)
    end

    progress.known = math.min(
        limit,
        math.max(
            normalizeCount(state.knownCount),
            discoveredKnown,
            progress.found
        )
    )
    progress.found = math.min(progress.found, progress.known)
    progress.incomplete = math.min(
        progress.incomplete,
        progress.found
    )
    progress.complete = progress.found - progress.incomplete
    progress.replaceable = math.max(
        0,
        progress.known - progress.found
    )
    progress.empty = math.max(0, limit - progress.known)
    return progress
end

local function slotProgressDetail(progress)
    if not progress.available then
        return "Analyze a build"
    end
    local parts = {}
    if progress.incomplete > 0 then
        parts[#parts + 1] = string.format(
            "%d rank%s incomplete",
            progress.incomplete,
            progress.incomplete == 1 and "" or "s"
        )
    end
    if progress.replaceable > 0 then
        parts[#parts + 1] = string.format(
            "%d replaceable",
            progress.replaceable
        )
    end
    if progress.empty > 0 then
        parts[#parts + 1] = string.format(
            "%d empty",
            progress.empty
        )
    end
    return #parts > 0 and table.concat(parts, " · ")
        or "All slots found"
end

local function scrollCurrencyIcon(side)
    local tokenUtil = _G and _G.TokenUtil
    if type(tokenUtil) ~= "table" then
        return nil
    end
    local getTokenType = side == "abilities"
        and tokenUtil.GetScrollOfFortuneForSpec
        or tokenUtil.GetScrollOfFortuneTalentsForSpec
    if type(getTokenType) ~= "function"
        or type(tokenUtil.CreateFromTokenType) ~= "function" then
        return nil
    end
    local okType, tokenType = pcall(getTokenType)
    if not okType or not tokenType then
        return nil
    end
    local okToken, token = pcall(
        tokenUtil.CreateFromTokenType,
        tokenType
    )
    if not okToken or not token or type(token.GetIcon) ~= "function" then
        return nil
    end
    local okIcon, icon = pcall(token.GetIcon, token)
    if not okIcon or not icon then
        return nil
    end
    return icon, tokenType
end

local function createSlotProgressCard(parent, side, width, height)
    local limit = SLOT_LIMITS[side]
    local frame = createBox(parent)
    frame:SetSize(width, height)

    local title = frame:CreateFontString(
        nil,
        "OVERLAY",
        "GameFontNormalSmall"
    )
    title:SetPoint("TOPLEFT", 11, -7)
    title:SetText(string.format(
        "%s  ·  — / %d FOUND",
        side == "abilities" and "ABILITIES" or "TALENTS",
        limit
    ))

    local currency = frame:CreateFontString(
        nil,
        "OVERLAY",
        "GameFontHighlightSmall"
    )
    local currencyIcon = frame:CreateTexture(nil, "OVERLAY")
    currencyIcon:SetSize(14, 14)
    currencyIcon:SetPoint("TOPRIGHT", -10, -5)
    currencyIcon:Hide()
    currency:SetPoint("RIGHT", currencyIcon, "LEFT", -3, 0)
    currency:SetJustifyH("RIGHT")
    currency:SetText("—")

    local meter = CreateFrame("Frame", nil, frame)
    meter:SetSize(width - 22, 9)
    meter:SetPoint("TOPLEFT", 11, -24)
    meter:SetBackdrop({
        bgFile = "Interface\\ChatFrame\\ChatFrameBackground",
    })
    meter:SetBackdropColor(0.015, 0.015, 0.015, 0.96)

    local segmentGap = 1
    local segmentWidth = (
        width - 22 - (limit - 1) * segmentGap
    ) / limit
    local segments = {}
    for index = 1, limit do
        local segment = meter:CreateTexture(nil, "ARTWORK")
        segment:SetTexture("Interface\\ChatFrame\\ChatFrameBackground")
        segment:SetVertexColor(unpack(SLOT_PROGRESS_COLORS.empty))
        segment:SetSize(segmentWidth, 9)
        segment:SetPoint(
            "LEFT",
            meter,
            "LEFT",
            (index - 1) * (segmentWidth + segmentGap),
            0
        )
        segments[index] = segment
    end

    local detail = frame:CreateFontString(
        nil,
        "OVERLAY",
        "GameFontHighlightSmall"
    )
    detail:SetPoint("BOTTOMLEFT", 11, 7)
    local innerWidth = width - 22
    detail:SetWidth(math.floor(
        innerWidth * (side == "talents" and 0.64 or 0.40)
    ))
    detail:SetJustifyH("LEFT")
    detail:SetTextColor(0.72, 0.72, 0.68)
    detail:SetText("Analyze a build")

    local session = frame:CreateFontString(
        nil,
        "OVERLAY",
        "GameFontHighlightSmall"
    )
    session:SetPoint("BOTTOMRIGHT", -11, 7)
    session:SetWidth(math.floor(
        innerWidth * (side == "talents" and 0.34 or 0.58)
    ))
    session:SetJustifyH("RIGHT")
    session:SetTextColor(0.72, 0.72, 0.68)
    session:SetText("Session spent 0")

    return {
        frame = frame,
        side = side,
        limit = limit,
        title = title,
        currency = currency,
        currencyIcon = currencyIcon,
        meter = meter,
        segments = segments,
        detail = detail,
        session = session,
    }
end

local function renderSlotProgress(card, progress)
    card.progress = progress
    card.title:SetText(string.format(
        "%s  ·  %s / %d FOUND",
        card.side == "abilities" and "ABILITIES" or "TALENTS",
        progress.available and tostring(progress.found) or "—",
        progress.limit
    ))
    card.detail:SetText(slotProgressDetail(progress))

    local currencyIcon, tokenType = scrollCurrencyIcon(card.side)
    card.currencyTokenType = tokenType
    if currencyIcon then
        card.currencyIcon:SetTexture(currencyIcon)
        card.currencyIcon:Show()
    else
        card.currencyIcon:Hide()
    end

    local completeEnd = progress.complete
    local incompleteEnd = completeEnd + progress.incomplete
    local replaceableEnd = incompleteEnd + progress.replaceable
    for index, segment in ipairs(card.segments) do
        local color
        if index <= completeEnd then
            color = SLOT_PROGRESS_COLORS.complete
        elseif index <= incompleteEnd then
            color = SLOT_PROGRESS_COLORS.incomplete
        elseif index <= replaceableEnd then
            color = SLOT_PROGRESS_COLORS.replaceable
        else
            color = SLOT_PROGRESS_COLORS.empty
        end
        segment:SetVertexColor(unpack(color))
        segment.progressState = index <= completeEnd and "complete"
            or index <= incompleteEnd and "incomplete"
            or index <= replaceableEnd and "replaceable"
            or "empty"
    end
end

local function sectionTitle(section)
    local name = trim(section and section.name)
    local category = CATEGORY_LABELS[section and section.kind]
        or tostring(section and section.kind or "planned")
    if section
        and section.side == "talents"
        and section.kind == "any" then
        category = category
            .. (section.anyPolicy == "rank"
                and " · highest rank"
                or " · build order")
    end
    if name == "" then
        return category
    end
    return name .. " · " .. category
end

local function sectionProgress(section)
    local held = normalizeCount(section and section.held)
    local count = normalizeCount(section and section.count)
    if section and section.kind == "any" then
        local need = math.max(1, normalizeCount(section.need))
        return string.format(
            "%d/%d needed · %d option%s",
            math.min(held, need),
            need,
            count,
            count == 1 and "" or "s"
        )
    end
    return string.format("%d/%d owned", held, count)
end

local function shouldShowAnyItem(section, item, index)
    if not section or section.kind ~= "any" then
        return true
    end
    local need = math.max(1, normalizeCount(section.need))
    if normalizeCount(section.held) < need then
        return true
    end

    local hasProtected = false
    local selectedCutoff = 0
    for optionIndex, option in ipairs(section.items or {}) do
        if option.role == "protected" then
            hasProtected = true
            selectedCutoff = math.max(selectedCutoff, optionIndex)
        end
    end
    if not hasProtected then
        return true
    end
    if section.anyPolicy == "rank" then
        return item.known
    end
    return item.known or index <= selectedCutoff
end

function M.buildPlanRows(result, side)
    local rows = {}
    local summary = {
        total = 0,
        owned = 0,
        upgrading = 0,
        missing = 0,
    }
    local state = result
        and result.sides
        and result.sides[side]
    local optionalByIndex = {}
    for _, category in ipairs(result and result.optionalCategories or {}) do
        if category.side == side then
            optionalByIndex[category.index] = category
        end
    end
    local displaySections = {}
    local seenOptional = {}
    for order, section in ipairs(state and state.sections or {}) do
        local sectionIndex = normalizeCount(section.index)
        if sectionIndex < 1 then
            sectionIndex = order
        end
        local category = optionalByIndex[sectionIndex]
        if category then
            seenOptional[sectionIndex] = true
        end
        displaySections[#displaySections + 1] = {
            index = sectionIndex,
            order = order,
            section = section,
            optionalCategory = category,
        }
    end
    for sectionIndex, category in pairs(optionalByIndex) do
        if not seenOptional[sectionIndex] then
            displaySections[#displaySections + 1] = {
                index = sectionIndex,
                order = 1000 + sectionIndex,
                section = {
                    side = side,
                    index = sectionIndex,
                    kind = category.kind,
                    name = category.name,
                    need = category.need,
                    count = category.count,
                    held = 0,
                    items = {},
                },
                optionalCategory = category,
                disabled = not category.enabled,
            }
        end
    end
    table.sort(displaySections, function(left, right)
        if left.index ~= right.index then
            return left.index < right.index
        end
        return left.order < right.order
    end)
    for _, display in ipairs(displaySections) do
        local section = display.section
        rows[#rows + 1] = {
            kind = "section",
            title = sectionTitle(section),
            progress = display.disabled and "" or sectionProgress(section),
            section = section,
            optionalCategory = display.optionalCategory,
            disabled = display.disabled,
        }
        for index, item in ipairs(section.items or {}) do
            local statusKey, style = getEntryStatus(item)
            local displayStatus = statusKey
            local displayStyle = style
            if item.known and item.role == "excess_any" then
                displayStatus = "surplus"
                displayStyle = STATUS_STYLES.surplus
            end
            summary.total = summary.total + 1
            if statusKey == "missing" then
                summary.missing = summary.missing + 1
            else
                summary.owned = summary.owned + 1
                if statusKey == "upgrade" then
                    summary.upgrading = summary.upgrading + 1
                end
            end
            if shouldShowAnyItem(section, item, index) then
                rows[#rows + 1] = {
                    kind = "entry",
                    item = item,
                    status = displayStatus,
                    style = displayStyle,
                }
            end
        end
    end
    local learnedNonbuild = state and state.learnedNonbuild or {}
    local learnedSynergies = state and state.learnedSynergies or {}
    local learnedCount = #learnedNonbuild + #learnedSynergies
    if learnedCount > 0 then
        local locked = 0
        for _, item in ipairs(learnedNonbuild) do
            if item.locked then
                locked = locked + 1
            end
        end
        for _, item in ipairs(learnedSynergies) do
            if item.locked then
                locked = locked + 1
            end
        end
        rows[#rows + 1] = {
            kind = "section",
            title = "Learned · not in build",
            progress = string.format(
                "%d learned%s",
                learnedCount,
                locked > 0 and (" · " .. locked .. " locked") or ""
            ),
            nonbuild = true,
        }
        for _, item in ipairs(learnedNonbuild) do
            rows[#rows + 1] = {
                kind = "entry",
                item = item,
                status = "nonbuild",
                style = STATUS_STYLES.nonbuild,
            }
        end
        for _, item in ipairs(learnedSynergies) do
            rows[#rows + 1] = {
                kind = "entry",
                item = item,
                status = "nonbuild",
                style = STATUS_STYLES.nonbuild,
                synergy = true,
            }
        end
    end
    return rows, summary
end

local function synergyBracket(item)
    if not item or not item.activeSynergy then
        return nil
    end
    if item.synergySource == "manual" then
        return "[Manual]"
    end
    local names = {}
    for _, target in ipairs(item.synergyTargets or {}) do
        names[#names + 1] = target.name
            or ("Spell #" .. tostring(target.spellID or target.entryID or "?"))
    end
    if #names == 0 then
        return "[Auto]"
    end
    return "[" .. table.concat(names, ", ") .. "]"
end

local function pityPressure(item)
    return math.max(
        0,
        normalizeCount(item and item.pityPressure)
    )
end

local function pressureSourceGuidance(decision)
    local counts = decision and decision.pressureSources
    if type(counts) ~= "table" then
        return nil
    end
    return string.format(
        "pressure sources A %d / T %d",
        normalizeCount(counts.abilities),
        normalizeCount(counts.talents)
    )
end

local function schedulingGuidance(decision, fallback)
    local parts = {}
    local sources = pressureSourceGuidance(decision)
    if sources then
        parts[#parts + 1] = sources
    end
    local reason = decision and decision.reason or fallback
    if reason and reason ~= "" then
        parts[#parts + 1] = reason
    end
    return table.concat(parts, " · ")
end

local function candidateGuidance(candidate)
    return string.format(
        "%s · pity pressure %d",
        candidate and candidate.name or "Unknown entry",
        pityPressure(candidate)
    )
end

local function catalogNameForSpellID(spellID)
    local wanted = canonicalSpellID(spellID)
    if not wanted then
        return nil
    end
    for _, entry in ipairs(ADDON_ENTRY_CATALOG) do
        if tonumber(entry.id) == wanted then
            return entry.name
        end
    end
end

local function entryRowName(item)
    local name = item and item.name or "Unknown entry"
    if name == "Unknown entry" or name:match("^Spell #%d+$") then
        name = catalogNameForSpellID(item and item.spellID) or name
    end
    local bracket = synergyBracket(item)
    return bracket and (name .. " " .. bracket) or name
end

M.synergyBracket = synergyBracket
M.entryRowName = entryRowName
M.candidateGuidance = candidateGuidance
M.pressureSourceGuidance = pressureSourceGuidance

local function entryMeta(item, status)
    local parts = {
        "#" .. tostring(item.spellID or item.entryID or "?"),
    }
    if item.side == "talents" and item.known then
        local currentRank = normalizeCount(item.currentRank)
        local maxRank = math.max(
            1,
            normalizeCount(item.maxRank),
            normalizeCount(item.targetRank)
        )
        parts[#parts + 1] = string.format(
            "Rank %d/%d",
            currentRank,
            maxRank
        )
        local targetRank = normalizeCount(item.targetRank)
        if targetRank > 0 and targetRank < maxRank then
            parts[#parts + 1] = "target " .. targetRank
        end
    end
    if item.locked and status ~= "nonbuild" and status ~= "surplus" then
        parts[#parts + 1] = "protected"
    end
    if item.role == "excess_any" then
        parts[#parts + 1] = "surplus any-of"
    end
    if not item.activeSynergy
        and (item.role == "nonbuild" or item.role == "excess_any") then
        parts[#parts + 1] = string.format(
            "pity pressure %d",
            pityPressure(item)
        )
    end
    return table.concat(parts, " · ")
end

local function analysisText(
    result,
    recommendation,
    schedule,
    rapidProjection,
    rapidError,
    rollOffState
)
    if not result.ok then
        return "Blocked: " .. tostring(
            result.errors and result.errors[1] or "unknown validation error"
        )
    end
    local lines = {
        string.format(
            "Missing: A %d must + %d any · T %d must + %d any",
            result.sides.abilities.mustMissing,
            result.sides.abilities.anyDeficit,
            result.sides.talents.mustMissing,
            result.sides.talents.anyDeficit
        ),
        string.format(
            "Pity risk: %d unfinished discardable talent%s · %d lock%s waiting",
            result.sides.talents.unfinishedDiscardable,
            result.sides.talents.unfinishedDiscardable == 1 and "" or "s",
            #result.lockSuggestions,
            #result.lockSuggestions == 1 and "" or "s"
        ),
    }
    if #result.parsed.talents == 0 then
        lines[#lines + 1] =
            "This build has no talent targets; talent rolling is disabled."
    end
    if recommendation then
        local candidate = recommendation.candidate
        lines[#lines + 1] = string.format(
            "Single next: %s · %s",
            candidateGuidance(candidate),
            schedulingGuidance(schedule, recommendation.demand)
        )
    elseif rollOffState then
        lines[#lines + 1] = rollOffSlotsText(rollOffState) .. ": "
            .. rollOffDemandText(rollOffState)
            .. "; choose one owned "
            .. rollOffChoiceNoun(rollOffState)
            .. " to roll off once."
    elseif schedule and schedule.reason then
        lines[#lines + 1] = "Single: " .. schedule.reason
    else
        lines[#lines + 1] = "Single: no safe reroll is currently recommended."
    end
    if rapidProjection then
        lines[#lines + 1] = string.format(
            "Rapid next: %s · %d desired / %d undesired · pity pressure %d · %s",
            rapidProjection.side,
            #rapidProjection.desired,
            #rapidProjection.undesired,
            pityPressure(rapidProjection),
            schedulingGuidance(rapidProjection)
        )
    elseif rapidError then
        lines[#lines + 1] = "Rapid: " .. rapidError
    end
    return table.concat(lines, "\n")
end

local function createTextFeed(parent, width, height)
    local feed = {
        width = width,
        height = height,
    }
    local scroll = CreateFrame(
        "ScrollFrame",
        nil,
        parent,
        "UIPanelScrollFrameTemplate"
    )
    scroll:SetSize(width, height)
    local child = CreateFrame("Frame", nil, scroll)
    child:SetWidth(math.max(40, width - 25))
    child:SetHeight(height)
    local text = child:CreateFontString(
        nil,
        "OVERLAY",
        "GameFontHighlightSmall"
    )
    text:SetPoint("TOPLEFT", 3, -3)
    text:SetPoint("TOPRIGHT", -3, -3)
    text:SetJustifyH("LEFT")
    text:SetJustifyV("TOP")
    text:SetText("")
    scroll:SetScrollChild(child)
    feed.scroll = scroll
    feed.child = child
    feed.text = text
    return feed
end

local function updateTextFeed(feed, lines)
    if not feed then
        return
    end
    feed.text:SetText(table.concat(lines or {}, "\n"))
    local contentHeight = feed.height
    if feed.text.GetStringHeight then
        contentHeight = math.max(
            contentHeight,
            feed.text:GetStringHeight() + 10
        )
    end
    feed.child:SetHeight(contentHeight)
    if feed.scroll.UpdateScrollChildRect then
        feed.scroll:UpdateScrollChildRect()
    end
    if contentHeight > feed.height then
        feed.scroll:SetVerticalScroll(contentHeight - feed.height)
    else
        feed.scroll:SetVerticalScroll(0)
    end
end

local function phaseText(phase)
    if PHASE_LABELS[phase] then
        return PHASE_LABELS[phase]
    end
    phase = tostring(phase or "idle")
    phase = phase:gsub("^rapid_", "")
    phase = phase:gsub("_", " ")
    return phase:gsub("^%l", string.upper)
end

function M.new(runtime)
    local ui = {
        runtime = runtime,
        log = {},
        protectionLog = {},
        viewMode = "closed",
        worldTransition = false,
        restoreViewAfterWorld = false,
        pendingHide = false,
        hideGeneration = 0,
        loadingEdit = false,
        lastAnalysis = nil,
        lastRecommendation = nil,
        lastSchedule = nil,
        lastRapidProjection = nil,
        lastRapidError = nil,
        lastAnalyzedKey = nil,
        analysisDirty = false,
        linkInvalidated = false,
        pendingStop = false,
        specializationSettling = false,
        specializationReset = false,
        specializationGeneration = 0,
        specializationSpecID = nil,
        rollOffSelecting = false,
        rollOffState = nil,
    }

    function ui:pauseForClosedPanel(singleReason, rapidReason, syncReason)
        if runtime.controller.running then
            runtime.controller:pause(singleReason)
        end
        if runtime.rapidController.running then
            runtime.rapidController:pause(rapidReason)
        end
        runtime.controller:cancelLockSync(syncReason)
        self:refreshButtons()
    end

    function ui:isCombatRollingAllowed()
        return self.viewMode == "minimized"
    end

    function ui:enforceCombatBoundary()
        if not UnitAffectingCombat
            or not UnitAffectingCombat("player") then
            return false
        end
        if self:isCombatRollingAllowed() then
            runtime.controller:cancelLockSync(
                "Combat started; desired-lock synchronization stopped."
            )
            self:refreshButtons()
            return false
        end
        self:pauseForClosedPanel(
            "Combat started; auto-roll paused. Minimize and press Resume to continue during combat, or resume after combat.",
            "Combat started; Rapid auto-roll paused. The accepted native batch may finish. Minimize and press Resume to continue during combat, or resume after combat.",
            "Combat started; desired-lock synchronization stopped."
        )
        return true
    end

    function ui:refreshTracker()
        local tracker = self.tracker
        if not tracker then
            return
        end

        local mode = self:activeMode()
        local controller = mode == "rapid"
            and runtime.rapidController
            or runtime.controller
        local reloadRecoveryReady =
            runtime.rapidController:canReloadRecovery()
        local state = "IDLE"
        local color = { 0.72, 0.72, 0.72 }
        if reloadRecoveryReady then
            state = "RECOVERY REQUIRED"
            color = { 1.00, 0.55, 0.16 }
        elseif mode and self:sessionRetiring() then
            state = "RETIRING"
            color = { 0.40, 0.78, 1.00 }
        elseif mode and controller.paused then
            state = "PAUSED"
            color = { 1.00, 0.78, 0.20 }
        elseif mode and controller.running then
            state = "RUNNING"
            color = { 0.38, 1.00, 0.46 }
        elseif mode then
            state = "FINISHING"
            color = { 1.00, 0.72, 0.25 }
        end

        tracker.Title:SetText(
            "AUTO-ROLL · " .. string.upper(mode or "idle") .. " · " .. state
        )
        tracker.Title:SetTextColor(unpack(color))

        local detail = "No active rolling session."
        if reloadRecoveryReady then
            detail = "Press Reload to recover the accepted Rapid batch, or open for details."
        elseif mode == "rapid" then
            detail = string.format(
                "%s · %d batch%s · A%d / T%d spent",
                phaseText(controller.phase),
                normalizeCount(controller.batches),
                normalizeCount(controller.batches) == 1 and "" or "es",
                normalizeCount(controller.rollsBySide
                    and controller.rollsBySide.abilities),
                normalizeCount(controller.rollsBySide
                    and controller.rollsBySide.talents)
            )
        elseif mode == "single" then
            detail = string.format(
                "%s · %d roll%s · A%d / T%d spent",
                phaseText(controller.phase),
                normalizeCount(controller.rollsSpent),
                normalizeCount(controller.rollsSpent) == 1 and "" or "s",
                normalizeCount(controller.rollsBySide
                    and controller.rollsBySide.abilities),
                normalizeCount(controller.rollsBySide
                    and controller.rollsBySide.talents)
            )
        end
        local rollNotice = mode and rollSideNotice(controller.rollSides)
        if rollNotice then
            detail = "|cffffc24a" .. rollNotice .. "|r · " .. detail
            tracker:SetBackdropBorderColor(1.00, 0.70, 0.18, 0.98)
        else
            tracker:SetBackdropBorderColor(0.35, 0.62, 0.82, 0.96)
        end
        tracker.Detail:SetText(detail)

        local busy = self:isSessionBusy()
        local canPause = busy
            and not self:sessionRetiring()
            and not self:draftDiffers()
            and not reloadRecoveryReady
        if busy then
            tracker.CloseButton:Hide()
            tracker.StopButton:Show()
            if reloadRecoveryReady then
                tracker.PauseButton:Hide()
                tracker.ReloadRecoveryButton:Show()
                setButtonEnabled(tracker.ReloadRecoveryButton, true)
            else
                tracker.ReloadRecoveryButton:Hide()
                tracker.PauseButton:Show()
                setButtonEnabled(tracker.PauseButton, canPause)
            end
        else
            tracker.PauseButton:Hide()
            tracker.ReloadRecoveryButton:Hide()
            tracker.StopButton:Hide()
            tracker.CloseButton:Show()
        end
        tracker.OpenButton:ClearAllPoints()
        tracker.PauseButton:ClearAllPoints()
        tracker.ReloadRecoveryButton:ClearAllPoints()
        tracker.StopButton:ClearAllPoints()
        tracker.CloseButton:ClearAllPoints()
        if busy then
            tracker.StopButton:SetPoint(
                "RIGHT",
                tracker,
                "RIGHT",
                -12,
                0
            )
            local middleButton = reloadRecoveryReady
                and tracker.ReloadRecoveryButton
                or tracker.PauseButton
            middleButton:SetPoint(
                "RIGHT",
                tracker.StopButton,
                "LEFT",
                -6,
                0
            )
            tracker.OpenButton:SetPoint(
                "RIGHT",
                middleButton,
                "LEFT",
                -6,
                0
            )
        else
            tracker.CloseButton:SetPoint(
                "RIGHT",
                tracker,
                "RIGHT",
                -12,
                0
            )
            tracker.OpenButton:SetPoint(
                "RIGHT",
                tracker.CloseButton,
                "LEFT",
                -6,
                0
            )
        end
        tracker.PauseButton:SetText(
            controller and controller.paused and "Resume" or "Pause"
        )
        setButtonEnabled(tracker.StopButton, busy)
        tracker.OpenButton:SetText("Open")
    end

    function ui:closeTracker()
        if self.viewMode ~= "minimized" then
            return false
        end
        self.viewMode = "closed"
        if self.tracker then
            self.tracker:Hide()
        end
        self:pauseForClosedPanel(
            "Auto-Roll tracker closed; no further paid roll will start. Reopen Auto-Roll and press Resume to continue.",
            "Auto-Roll tracker closed; the accepted native Rapid batch may finish, but no next batch will start. Reopen Auto-Roll and press Resume.",
            "Auto-Roll tracker closed; desired-lock synchronization stopped."
        )
        return true
    end

    function ui:restoreFullPanel()
        if not self.panel then
            return false
        end
        self.viewMode = "full"
        if self.tracker then
            self.tracker:Hide()
        end
        raise(self.panel)
        if self.panel:IsShown() then
            self:analyze()
        else
            self.panel:Show()
        end
        self:enforceCombatBoundary()
        return true
    end

    function ui:restoreMinimizedTracker()
        self:createPanel()
        self.hideGeneration = self.hideGeneration + 1
        self.pendingHide = false
        self.viewMode = "minimized"
        self.analysisDirty = true
        self:createTracker()
        self:refreshTracker()
        raise(self.tracker)
        self.tracker:Show()
        if self.panel:IsShown() then
            self.panel:Hide()
        end
        return true
    end

    function ui:minimize()
        if not self.panel or not self.panel:IsShown() then
            return false
        end
        if runtime.controller.lockSync or self.rollOffSelecting then
            return false
        end

        self.hideGeneration = self.hideGeneration + 1
        self.pendingHide = false
        self.viewMode = "minimized"
        self:createTracker()
        self:refreshTracker()
        raise(self.tracker)
        self.tracker:Show()
        self.panel:Hide()

        -- Never let the one-click return to play discard a native draft.
        -- The controllers own their own event frame and keep using the live C
        -- APIs while the stock Character Advancement UI is closed.
        local hasPendingChanges = not C_CharacterAdvancement
            or type(C_CharacterAdvancement.IsPending) ~= "function"
            or C_CharacterAdvancement.IsPending()
        if not hasPendingChanges
            and CharacterAdvancement
            and CharacterAdvancement.IsShown
            and CharacterAdvancement:IsShown()
            and Collections
            and type(HideUIPanel) == "function" then
            HideUIPanel(Collections)
        end
        return true
    end

    function ui:singleBusy()
        local controller = runtime.controller
        return controller.running
            or controller.paused
            or controller.pendingRoll ~= nil
            or controller.pendingLockID ~= nil
            or controller.pendingUnlockID ~= nil
            or controller.oneShotRollOff ~= nil
    end

    function ui:rapidBusy()
        return runtime.rapidController
            and runtime.rapidController:isBusy()
            or false
    end

    function ui:isSessionBusy()
        return self:singleBusy() or self:rapidBusy()
    end

    function ui:activeMode()
        if self:rapidBusy() then
            return "rapid"
        end
        if self:singleBusy() then
            return "single"
        end
    end

    function ui:activeLink()
        local mode = self:activeMode()
        if mode == "rapid" then
            return runtime.rapidController.link
        elseif mode == "single" then
            return runtime.controller.link
        end
    end

    function ui:draftLink()
        if self.panel and self.panel.EditBox then
            return self.panel.EditBox:GetText()
        end
        LazyRollerDB = LazyRollerDB or {}
        return LazyRollerDB.draftLink
            or LazyRollerDB.link
            or ""
    end

    function ui:configuredHighRollFloors()
        if self.panel
            and self.panel.HighRollAbilityBox
            and self.panel.HighRollTalentBox then
            return {
                abilities = normalizeCount(
                    self.panel.HighRollAbilityBox:GetText()
                ),
                talents = normalizeCount(
                    self.panel.HighRollTalentBox:GetText()
                ),
            }
        end
        LazyRollerDB = LazyRollerDB or {}
        return initializeHighRollSettings(LazyRollerDB)
    end

    function ui:configuredStandardTalentFallback()
        return self.panel
            and self.panel.StandardTalentCheck
            and self.panel.StandardTalentCheck:GetChecked()
            and true or false
    end

    function ui:configuredRollSides()
        if self.panel
            and self.panel.RollAbilitiesCheck
            and self.panel.RollTalentsCheck then
            return {
                abilities = self.panel.RollAbilitiesCheck:GetChecked()
                    and true or false,
                talents = self.panel.RollTalentsCheck:GetChecked()
                    and true or false,
            }
        end
        return {
            abilities = true,
            talents = true,
        }
    end

    function ui:optionalCategories()
        return self.lastAnalysis
            and self.lastAnalysis.ok
            and self.lastAnalysis.optionalCategories
            or {}
    end

    function ui:canEditOptionalCategories()
        return not self:isSessionBusy()
            and runtime.controller.lockSync == nil
            and not self.rollOffSelecting
            and not self.specializationSettling
    end

    function ui:applyOptionalCategoryState(category, enabled, control)
        local previous = category and category.enabled and true or false
        if not category or not self:canEditOptionalCategories() then
            paintCategoryToggle(control, previous, false)
            self:appendLog(
                "optional_blocked",
                "Stop the active session before changing Auto-Roll categories."
            )
            return false
        end
        local identity = self.lastAnalysis
            and self.lastAnalysis.parsed
            and self.lastAnalysis.parsed.identity
        local ok, reason = runtime.api.setOptionalCategoryEnabled(
            identity,
            category.side,
            category.index,
            enabled and true or false
        )
        if not ok then
            paintCategoryToggle(control, previous, true)
            self:appendLog(
                "optional_blocked",
                reason or "The Auto-Roll category could not be changed."
            )
            return false
        end
        self:appendLog(
            "optional_category",
            string.format(
                "%s %s.",
                optionalCategoryName(category),
                enabled and "enabled" or "disabled"
            )
        )
        self:analyze()
        return true
    end

    function ui:renderOptionalCategories()
        if not self.panel or not self.panel.OptionalCategoryFrame then
            return
        end
        local categories = self:optionalCategories()
        local panel = self.panel
        local rows = panel.OptionalCategoryRows
        local canEdit = self:canEditOptionalCategories()
        for index, category in ipairs(categories) do
            local row = rows[index]
            if not row then
                local check = createCategoryToggle(
                    panel.OptionalCategoryScrollChild
                )
                local label = panel.OptionalCategoryScrollChild:CreateFontString(
                    nil,
                    "OVERLAY",
                    "GameFontHighlightSmall"
                )
                label:SetJustifyH("LEFT")
                row = { check = check, label = label }
                rows[index] = row
            end
            row.check:ClearAllPoints()
            row.check:SetPoint("TOPRIGHT", -4, -7 - ((index - 1) * 28))
            row.check.categoryLabel = optionalCategoryName(category)
            row.check.optionalCategory = category
            paintCategoryToggle(row.check, category.enabled, canEdit)
            row.check:Show()
            row.label:ClearAllPoints()
            row.label:SetPoint("LEFT", 2, -((index - 1) * 28))
            row.label:SetPoint("RIGHT", row.check, "LEFT", -8, 0)
            row.label:SetText(string.format(
                "%s · %s · %s",
                sideTitle(category.side),
                optionalCategoryName(category),
                CATEGORY_LABELS[category.kind] or tostring(category.kind)
            ))
            row.check:SetScript("OnClick", function(current)
                local enabled = current:GetChecked() and true or false
                self:applyOptionalCategoryState(
                    current.optionalCategory,
                    enabled,
                    current
                )
            end)
        end
        for index = #categories + 1, #rows do
            rows[index].check:Hide()
            rows[index].label:Hide()
        end
        for index = 1, #categories do
            rows[index].label:Show()
        end
        panel.OptionalCategoryScrollChild:SetHeight(
            math.max(1, #categories * 28)
        )
        panel.OptionalCategoryHint:SetText(
            canEdit
                and "Use these switches or the matching category-header switches. Every change reruns analysis."
                or "Stop the active session before changing these categories."
        )
    end

    function ui:draftDiffers()
        local activeLink = self:activeLink()
        return activeLink ~= nil
            and buildKey(activeLink) ~= buildKey(self:draftLink())
    end

    function ui:sessionRetiring()
        local rapid = runtime.rapidController
        return self.linkInvalidated
            or self.pendingStop
            or (rapid and rapid.stopAfterBatch ~= nil)
    end

    function ui:beginSpecializationReset(hadSession, eventSpecID)
        self.specializationGeneration =
            self.specializationGeneration + 1
        self.specializationSettling = true
        self.specializationReset = hadSession and true or false
        self.specializationSpecID = tonumber(eventSpecID)
            or self.specializationSpecID
        self.pendingStop = false
        self.lastAnalysis = nil
        self.lastRecommendation = nil
        self.lastSchedule = nil
        self.lastRapidProjection = nil
        self.lastRapidError = nil
        self.lastAnalyzedKey = nil
        self.rollOffSelecting = false
        self.rollOffState = nil

        -- A confirmation opened for the old specialization must not remain
        -- actionable after its live entry/balance context has changed.
        if type(StaticPopup_Hide) == "function" then
            StaticPopup_Hide("LAZY_ROLLER_START")
            StaticPopup_Hide("LAZY_ROLLER_START_RAPID")
            StaticPopup_Hide("LAZY_ROLLER_SYNC_LOCKS")
            StaticPopup_Hide("LAZY_ROLLER_ROLL_OFF")
        end

        -- An active controller emits the one user-facing reset record after
        -- its ownership has actually been cleared. Idle specialization
        -- changes still need one concise refresh record here.
        if not hadSession then
            self:appendLog(
                "specialization_changed",
                "Specialization changed; waiting for Ascension to finish refreshing live build state."
            )
        end
        if self.panel then
            self:refreshButtons()
        end
        return self.specializationGeneration
    end

    function ui:completeSpecializationReset(specID)
        self.specializationSpecID = tonumber(specID)
            or self.specializationSpecID
        self.specializationSettling = false
        if self.panel and not self.worldTransition then
            return self:analyze()
        elseif self.panel then
            self:refreshButtons()
        end
    end

    function ui:saveInputs()
        if not self.panel then
            return
        end
        LazyRollerDB = LazyRollerDB or {}
        local draft = self.panel.EditBox:GetText()
        LazyRollerDB.draftLink = draft
        if not self:isSessionBusy() then
            LazyRollerDB.link = draft
        end
        LazyRollerDB.sessionLimit =
            normalizeSessionLimit(self.panel.SessionLimitBox:GetText())
        local highRollFloors = self:configuredHighRollFloors()
        LazyRollerDB.highRollProtectionInitialized = true
        LazyRollerDB.highRollAbilityFloor =
            highRollFloors.abilities
        LazyRollerDB.highRollTalentFloor =
            highRollFloors.talents
        -- Ascension blocks ReloadUI outside a hardware event. Retire the old
        -- automatic setting while retaining the key for saved-profile
        -- compatibility; recovery is now always an explicit button click.
        LazyRollerDB.autoReloadRapidUpgrade = false
    end

    function ui:commitLink(link)
        LazyRollerDB = LazyRollerDB or {}
        LazyRollerDB.link = tostring(link or "")
        LazyRollerDB.draftLink = tostring(link or "")
    end

    function ui:refreshDraftState()
        if not self.panel then
            return
        end
        local active = self:activeMode()
        local dirty = self:draftDiffers()
        local retiring = self:sessionRetiring() or dirty
        if self.specializationSettling then
            self.panel.DraftStatus:SetText(
                "Specialization changed. Waiting for the new live entries and scroll balances to settle."
            )
            self.panel.DraftStatus:SetTextColor(1.00, 0.78, 0.20)
            self.panel.AnalyzeButton:SetText("Analyze")
        elseif self.specializationReset then
            self.panel.DraftStatus:SetText(
                "Specialization changed. The previous session was reset; review the refreshed plan and explicitly Start again."
            )
            self.panel.DraftStatus:SetTextColor(1.00, 0.78, 0.20)
            self.panel.AnalyzeButton:SetText("Analyze")
        elseif retiring and active then
            self.panel.DraftStatus:SetText(
                "Build link changed. The old session is retiring and cannot resume."
            )
            self.panel.DraftStatus:SetTextColor(1.00, 0.78, 0.20)
            self.panel.AnalyzeButton:SetText("Analyze")
        elseif self.linkInvalidated then
            self.panel.DraftStatus:SetText(
                self.lastAnalysis
                    and self.lastAnalyzedKey == buildKey(self:draftLink())
                    and "Previous session ended when the build changed. Press Start explicitly for the updated build."
                    or "Previous session ended when the build changed. Analyze, then explicitly start the updated build."
            )
            self.panel.DraftStatus:SetTextColor(1.00, 0.78, 0.20)
            self.panel.AnalyzeButton:SetText("Analyze")
        elseif active then
            self.panel.DraftStatus:SetText(
                "Editor matches the active " .. active .. " session."
            )
            self.panel.DraftStatus:SetTextColor(0.42, 0.90, 0.48)
            self.panel.AnalyzeButton:SetText("Analyze")
        else
            self.panel.DraftStatus:SetText(
                "Edit a Season 10 builder link, then analyze it."
            )
            self.panel.DraftStatus:SetTextColor(0.72, 0.72, 0.72)
            self.panel.AnalyzeButton:SetText("Analyze")
        end
    end

    function ui:currentTargetID()
        local pending = runtime.controller.pendingRoll
        if pending and pending.entryID then
            return pending.entryID
        end
        local rapid = runtime.rapidController
        local state = rapid and rapid.lastState
        return state and state.TargetEntryID
    end

    function ui:createPlanRow(pane)
        local row = CreateFrame("Button", nil, pane.child)
        row:RegisterForClicks("LeftButtonUp", "RightButtonUp")
        row:SetBackdrop({
            bgFile = "Interface\\ChatFrame\\ChatFrameBackground",
            edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
            tile = true,
            tileSize = 16,
            edgeSize = 8,
            insets = { left = 2, right = 2, top = 2, bottom = 2 },
        })

        local icon = row:CreateTexture(nil, "ARTWORK")
        icon:SetSize(PLAN_ICON_SIZE, PLAN_ICON_SIZE)
        icon:SetPoint("LEFT", 3, 0)
        row.Icon = icon

        local name = row:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontNormalSmall"
        )
        name:SetPoint("LEFT", icon, "RIGHT", 4, 0)
        name:SetPoint("RIGHT", -68, 0)
        name:SetHeight(12)
        name:SetJustifyH("LEFT")
        name:SetJustifyV("MIDDLE")
        if name.SetWordWrap then
            name:SetWordWrap(false)
        end
        row.Name = name

        local meta = row:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontHighlightSmall"
        )
        meta:SetPoint("BOTTOMLEFT", icon, "BOTTOMRIGHT", 7, 2)
        meta:SetPoint("BOTTOMRIGHT", -7, 2)
        meta:SetJustifyH("LEFT")
        row.Meta = meta

        local status = row:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontNormalSmall"
        )
        status:SetPoint("RIGHT", -5, 0)
        status:SetJustifyH("RIGHT")
        row.Status = status

        local lockedStatus = row:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontNormal"
        )
        lockedStatus:SetPoint("RIGHT", -5, 0)
        lockedStatus:SetJustifyH("RIGHT")
        lockedStatus:SetText("!LOCKED!")
        lockedStatus:SetTextColor(1.00, 0.08, 0.08)
        lockedStatus:Hide()
        row.LockedStatus = lockedStatus

        local sectionName = row:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontNormalSmall"
        )
        sectionName:SetPoint("LEFT", 5, 0)
        sectionName:SetPoint("RIGHT", -124, 0)
        sectionName:SetJustifyH("LEFT")
        row.SectionName = sectionName

        local sectionProgress = row:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontHighlightSmall"
        )
        sectionProgress:SetPoint("RIGHT", -5, 0)
        sectionProgress:SetJustifyH("RIGHT")
        row.SectionProgress = sectionProgress

        local sectionToggle = createCategoryToggle(row)
        sectionToggle:SetPoint("RIGHT", -5, 0)
        sectionToggle:Hide()
        row.SectionToggle = sectionToggle

        row:SetScript("OnEnter", function(current)
            if current.rollOffEligible then
                current:SetBackdropBorderColor(1.00, 0.58, 0.12, 1.00)
            end
            local item = current.item
            if not item or not GameTooltip then
                return
            end
            GameTooltip:SetOwner(current, "ANCHOR_RIGHT")
            local linked = false
            if GameTooltip.SetHyperlink and item.spellID then
                linked = pcall(
                    GameTooltip.SetHyperlink,
                    GameTooltip,
                    "spell:" .. tostring(item.spellID)
                )
            end
            if not linked then
                GameTooltip:SetText(item.name or "Planned entry")
            end
            if GameTooltip.AddLine then
                local style = current.planStyle
                    or select(2, getEntryStatus(item))
                GameTooltip:AddLine(
                    style.label,
                    style.text[1],
                    style.text[2],
                    style.text[3]
                )
                if (current.planStatus == "nonbuild"
                    or current.planStatus == "surplus") and item.locked then
                    GameTooltip:AddLine(
                        "!LOCKED! This entry cannot be used as a reroll target.",
                        1,
                        0.08,
                        0.08,
                        true
                    )
                end
                local bracket = synergyBracket(item)
                if bracket then
                    GameTooltip:AddLine(
                        item.synergySource == "manual"
                            and "Manual synergy; kept until no ordinary discard remains."
                            or "Active synergy for " .. bracket,
                        0.76,
                        0.84,
                        0.82,
                        true
                    )
                end
                if not item.activeSynergy
                    and (item.role == "nonbuild"
                        or item.role == "excess_any") then
                    GameTooltip:AddLine(
                        string.format(
                            "Pity pressure: %d probable opposite-side synergies.",
                            pityPressure(item)
                        ),
                        0.76,
                        0.84,
                        0.82,
                        true
                    )
                end
                if current.guidanceKind then
                    GameTooltip:AddLine(
                        current.guidanceKind == "RAPID"
                            and "Included in the next highest-pressure Rapid Undesired group."
                            or "Recommended as the next safe Single roll-off.",
                        1.00,
                        0.78,
                        0.20,
                        true
                    )
                end
                if item.side == "talents" and item.known then
                    GameTooltip:AddLine(
                        string.format(
                            "Current rank %d of %d",
                            normalizeCount(item.currentRank),
                            math.max(
                                1,
                                normalizeCount(item.maxRank),
                                normalizeCount(item.targetRank)
                            )
                        ),
                        1,
                        0.82,
                        0.28
                    )
                end
                if current.rollOffEligible then
                    GameTooltip:AddLine(
                        "Click to choose this "
                            .. sideNoun(item.side)
                            .. " for one roll off.",
                        1.00,
                        0.72,
                        0.20,
                        true
                    )
                end
                if item.section and not item.locked
                    and (self:hasAnalyzedBuild()
                        or self:isCustomBuildCandidate()) then
                    GameTooltip:AddLine(
                        "Right-click to remove this "
                            .. sideNoun(item.side)
                            .. " from the editable build.",
                        0.90,
                        0.42,
                        0.42,
                        true
                    )
                end
            end
            GameTooltip:Show()
        end)
        row:SetScript("OnLeave", function(current)
            if current.planBorder then
                current:SetBackdropBorderColor(unpack(current.planBorder))
            end
            if GameTooltip then
                GameTooltip:Hide()
            end
        end)
        row:SetScript("OnClick", function(current, button)
            if self.panel and self.panel.EditBox then
                self.panel.EditBox:ClearFocus()
            end
            if button == nil or button == "LeftButton" then
                if current.rollOffEligible and current.item then
                    self:requestRollOff(current.item)
                end
            elseif button == "RightButton" then
                            if current.shiftKey then
                                local item = current.item
                                if item and item.section and not item.locked
                                    and (self:hasAnalyzedBuild()
                                        or self:isCustomBuildCandidate()) then
                                    self:removeCustomEntry(item.side, item.spellID)
                                end
                            else
                                local item = current.item
                                if item and item.section and not item.locked
                                    and (self:hasAnalyzedBuild()
                                        or self:isCustomBuildCandidate()) then
                                    self:removeCustomEntry(item.side, item.spellID)
                                end
                            end
                        end
        end)
        return row
    end

    function ui:renderPlanSide(side, result)
        if not self.panel or not self.panel.PlanPanes then
            return
        end
        local pane = self.panel.PlanPanes[side]
        local previousScroll = pane.scroll.GetVerticalScroll
            and pane.scroll:GetVerticalScroll() or 0
        local followBottom = pane.bottomPinned == true
        local rows, summary = M.buildPlanRows(result, side)
        local targetID = self:currentTargetID()
        local mode = self:activeMode()
        local rapidGuidance = mode == "rapid"
            or mode == nil and self.lastRapidProjection ~= nil
        local rapidIDs = {}
        if rapidGuidance and self.lastRapidProjection
            and self.lastRapidProjection.side == side then
            for _, selection in ipairs(
                self.lastRapidProjection.undesired or {}
            ) do
                rapidIDs[selection.ID] = true
            end
        end
        local singleGuidanceID = not rapidGuidance
            and self.lastRecommendation
            and self.lastRecommendation.candidate
            and self.lastRecommendation.candidate.entryID
        local offset = 0
        for index, model in ipairs(rows) do
            local row = pane.pool[index]
            if not row then
                row = self:createPlanRow(pane)
                pane.pool[index] = row
            end
            row:ClearAllPoints()
            row:SetPoint("TOPLEFT", 0, -offset)
            row:SetPoint("TOPRIGHT", 0, -offset)
            row.item = nil
            row.planStatus = nil
            row.planStyle = nil
            row.rollOffEligible = false
            row.planBorder = nil
            row.guidanceKind = nil
            row.optionalCategory = nil
            row.SectionToggle:Hide()
            if model.kind == "section" then
                row:SetHeight(PLAN_SECTION_HEIGHT)
                if model.disabled then
                    row:SetBackdropColor(0.055, 0.06, 0.065, 0.96)
                    row:SetBackdropBorderColor(0.25, 0.27, 0.29, 0.88)
                elseif model.nonbuild then
                    row:SetBackdropColor(0.035, 0.075, 0.14, 0.96)
                    row:SetBackdropBorderColor(0.15, 0.42, 0.72, 0.88)
                else
                    row:SetBackdropColor(0.10, 0.09, 0.055, 0.96)
                    row:SetBackdropBorderColor(0.42, 0.36, 0.18, 0.80)
                end
                row.Icon:Hide()
                row.Name:Hide()
                row.Meta:Hide()
                row.Status:Hide()
                row.LockedStatus:Hide()
                row.SectionName:Show()
                row.SectionProgress:Show()
                row.SectionName:ClearAllPoints()
                row.SectionName:SetPoint("LEFT", 5, 0)
                row.SectionProgress:ClearAllPoints()
                row.SectionName:SetText(string.upper(model.title))
                if model.disabled then
                    row.SectionName:SetTextColor(0.55, 0.56, 0.57)
                elseif model.nonbuild then
                    row.SectionName:SetTextColor(0.42, 0.76, 1.00)
                else
                    row.SectionName:SetTextColor(0.95, 0.78, 0.24)
                end
                if model.optionalCategory then
                    row.optionalCategory = model.optionalCategory
                    row.SectionName:SetPoint("RIGHT", -156, 0)
                    row.SectionProgress:SetPoint("RIGHT", -40, 0)
                    row.SectionToggle.categoryLabel = optionalCategoryName(
                        model.optionalCategory
                    )
                    row.SectionToggle.optionalCategory = model.optionalCategory
                    paintCategoryToggle(
                        row.SectionToggle,
                        model.optionalCategory.enabled,
                        self:canEditOptionalCategories()
                    )
                    row.SectionToggle:SetScript("OnClick", function(current)
                        self:applyOptionalCategoryState(
                            current.optionalCategory,
                            current:GetChecked() and true or false,
                            current
                        )
                    end)
                    row.SectionToggle:Show()
                else
                    row.SectionName:SetPoint("RIGHT", -124, 0)
                    row.SectionProgress:SetPoint("RIGHT", -5, 0)
                end
                row.SectionProgress:SetText(model.progress)
                row.SectionProgress:SetTextColor(0.76, 0.76, 0.72)
                offset = offset + PLAN_SECTION_STEP
            else
                local item = model.item
                local style = model.style
                if rapidIDs[item.entryID] then
                    row.guidanceKind = "RAPID"
                elseif singleGuidanceID
                    and item.entryID == singleGuidanceID then
                    row.guidanceKind = "NEXT"
                end
                row:SetHeight(PLAN_ENTRY_HEIGHT)
                row:SetBackdropColor(unpack(style.background))
                if targetID and item.entryID == targetID then
                    row.planBorder = { 0.25, 0.70, 1.00, 1.00 }
                elseif row.guidanceKind then
                    row.planBorder = { 1.00, 0.64, 0.12, 1.00 }
                else
                    row.planBorder = {
                        style.border[1],
                        style.border[2],
                        style.border[3],
                        style.border[4],
                    }
                end
                row:SetBackdropBorderColor(unpack(row.planBorder))
                row.item = item
                row.planStatus = model.status
                row.planStyle = style
                local sideRollOffState = rollOffStateForSide(
                    self.rollOffState,
                    side
                )
                row.rollOffEligible = self.rollOffSelecting
                    and sideRollOffState
                    and sideRollOffState.eligibleSet
                    and sideRollOffState.eligibleSet[item.entryID]
                    and true or false
                row.Icon:Show()
                row.Name:Show()
                row.Meta:Hide()
                row.SectionName:Hide()
                row.SectionProgress:Hide()
                row.Name:ClearAllPoints()
                row.Name:SetPoint("LEFT", row.Icon, "RIGHT", 4, 0)
                local rightInset = -68
                if model.status == "owned"
                    or model.status == "nonbuild" and not item.locked then
                    rightInset = -5
                elseif model.status == "surplus" and not item.locked then
                    rightInset = -68
                elseif model.status == "nonbuild"
                    or model.status == "surplus" then
                    rightInset = -88
                end
                if row.guidanceKind then
                    rightInset = math.min(rightInset, -48)
                end
                row.Name:SetPoint(
                    "RIGHT",
                    rightInset,
                    0
                )
                local icon
                if type(GetSpellInfo) == "function" and item.spellID then
                    local _, _, spellIcon = GetSpellInfo(item.spellID)
                    icon = spellIcon
                end
                row.Icon:SetTexture(
                    icon or "Interface\\Icons\\INV_Misc_QuestionMark"
                )
                row.Name:SetText(string.format(
                    "%s  |cffadadad%s|r",
                    entryRowName(item),
                    entryMeta(item, model.status)
                ))
                row.Name:SetTextColor(1.00, 0.96, 0.82)
                row.Meta:SetText("")
                if row.guidanceKind then
                    row.Status:SetText(row.guidanceKind)
                    row.Status:SetTextColor(1.00, 0.78, 0.20)
                    row.Status:Show()
                elseif model.status == "owned"
                    or model.status == "nonbuild" then
                    row.Status:SetText("")
                    row.Status:Hide()
                elseif model.status == "surplus" and item.locked then
                    row.Status:SetText("")
                    row.Status:Hide()
                else
                    row.Status:Show()
                    row.Status:SetText(
                        model.status == "upgrade"
                            and string.format(
                                "%d/%d",
                                normalizeCount(item.currentRank),
                                math.max(
                                    1,
                                    normalizeCount(item.maxRank),
                                    normalizeCount(item.targetRank)
                                )
                            )
                            or style.label
                    )
                    row.Status:SetTextColor(unpack(style.text))
                end
                if (model.status == "nonbuild"
                    or model.status == "surplus") and item.locked then
                    row.LockedStatus:Show()
                else
                    row.LockedStatus:Hide()
                end
                offset = offset + PLAN_ENTRY_STEP
            end
            row:Show()
        end
        for index = #rows + 1, #pane.pool do
            pane.pool[index]:Hide()
        end
        local contentHeight = math.max(pane.viewHeight, offset + 2)
        -- UIPanelScrollFrameTemplate applies its real range after the child
        -- changes size. Let that native callback follow the bottom, and keep
        -- its programmatic movement from looking like player input.
        pane.adjustingScroll = true
        pane.scroll.scrollToBottom = followBottom and true or nil
        pane.child:SetHeight(contentHeight)
        if pane.scroll.UpdateScrollChildRect then
            pane.scroll:UpdateScrollChildRect()
        end
        if pane.scroll.GetVerticalScroll then
            local maximum = pane.scroll.GetVerticalScrollRange
                and math.max(0, pane.scroll:GetVerticalScrollRange())
                or math.max(0, contentHeight - pane.viewHeight)
            local nextScroll = followBottom and maximum
                or math.min(previousScroll, maximum)
            pane.scroll:SetVerticalScroll(nextScroll)
        end
        pane.adjustingScroll = false
        local title = side == "abilities" and "ABILITIES" or "TALENTS"
        if self.rollOffSelecting
            and rollOffStateForSide(self.rollOffState, side) then
            pane.title:SetText(
                string.upper(side)
                    .. "  ·  CLICK ONE OWNED " .. sideTitle(side)
            )
            pane.frame:SetBackdropBorderColor(1.00, 0.58, 0.12, 0.95)
        else
            pane.title:SetText(title)
            pane.frame:SetBackdropBorderColor(0.45, 0.40, 0.25, 0.72)
        end
        if #rows == 0 then
            pane.empty:SetText(
                result and result.ok
                    and "No planned " .. side .. "."
                    or "Analyze a valid build to populate this list."
            )
            pane.empty:Show()
        else
            pane.empty:Hide()
        end
    end

    function ui:renderPlan(result)
        self:renderPlanSide("abilities", result)
        self:renderPlanSide("talents", result)
        self:refreshBuildEditor()
    end

    function ui:customBuildPayload()
        local payload = customPayloadFromLink(self:draftLink())
        if not payload or not addon.codec
            or type(addon.codec.decodePlan) ~= "function" then
            return nil
        end
        local decoded, why = addon.codec.decodePlan(payload)
        if type(decoded) ~= "table" or decoded.v ~= 1 then
            return nil, why
        end
        return decoded
    end

    function ui:payloadFromParsed(parsed)
        if type(parsed) ~= "table" then
            return nil
        end
        local payload = {
            v = 1,
            name = "Imported analyzed build",
            primaryStat = parsed.primaryStatName or "",
            abilities = {},
            talents = {},
        }
        for _, side in ipairs({ "abilities", "talents" }) do
            local seen = {}
            for _, rawID in ipairs(parsed[side] or {}) do
                local value = canonicalSpellID(tonumber(rawID))
                if uiIsInteger(value, 1, UI_MAX_SPELL_ID)
                    and not seen[value] then
                    seen[value] = true
                    payload[side][#payload[side] + 1] = value
                end
            end
        end
        return payload
    end

    function ui:isCustomBuildCandidate()
        return customPayloadFromLink(self:draftLink()) ~= nil
    end

    function ui:isPlainIDListCandidate()
        local value = trim(self:draftLink())
        if value == "" or value:find("[#?&=./:]", 1) then
            return false
        end
        local found = false
        for token in value:gmatch("[^,%s]+") do
            found = true
            if not token:match("^%d+$") then
                return false
            end
        end
        return found
    end

    function ui:hasAnalyzedBuild()
        return self.lastAnalysis
            and self.lastAnalysis.ok
            and self.lastAnalysis.parsed
            and self.lastAnalyzedKey == buildKey(self:draftLink())
            and not self:isSessionBusy()
    end

    function ui:isCustomBuildActive()
        return self:hasAnalyzedBuild()
            and self.lastAnalysis.parsed.rules == "s10w60"
            and self.lastAnalysis.parsed.version == 1
            and self.lastAnalysis.parsed.categorized == false
    end

    function ui:customBuildFromPayload(payload)
        local abilities, talents = {}, {}
        local seenAbilities, seenTalents = {}, {}
        for _, id in ipairs(payload and payload.abilities or {}) do
            local value = canonicalSpellID(tonumber(id))
            if uiIsInteger(value, 1, UI_MAX_SPELL_ID)
                and not seenAbilities[value] then
                seenAbilities[value] = true
                abilities[#abilities + 1] = value
            end
        end
        for _, id in ipairs(payload and payload.talents or {}) do
            local value = canonicalSpellID(tonumber(id))
            if uiIsInteger(value, 1, UI_MAX_SPELL_ID)
                and not seenTalents[value] then
                seenTalents[value] = true
                talents[#talents + 1] = value
            end
        end
        return {
            v = 1,
            name = tostring(payload and payload.name or ""),
            primaryStat = payload and payload.primaryStat or nil,
            abilities = abilities,
            talents = talents,
        }
    end

    function ui:applyCustomPayload(payload)
        if self:isSessionBusy() then
            self:appendLog(
                "build_edit_blocked",
                "Stop the active rolling session before editing this build."
            )
            return false
        end
        if not addon.codec or
            type(addon.codec.encodeBuildPayload) ~= "function" then
            self:appendLog(
                "build_edit_blocked",
                "This client cannot regenerate a custom build link."
            )
            return false
        end
        local encoded, encodeError = addon.codec.encodeBuildPayload(payload)
        if not encoded then
            self:appendLog(
                "build_edit_blocked",
                encodeError or "The custom build link could not be regenerated."
            )
            return false
        end
        if self.panel and self.panel.EditBox then
            self.loadingEdit = true
            self.panel.EditBox:SetText(encoded)
            self.loadingEdit = false
        end
        self:saveInputs()
        self:analyze()
        return true
    end

    function ui:addCustomEntry(side, spec)
        if side ~= "abilities" and side ~= "talents" then
            return false
        end
        if self:isSessionBusy() then
            self:appendLog(
                "build_edit_blocked",
                "Stop the active rolling session before editing this build."
            )
            return false
        end
        if self.specializationSettling then
            self:appendLog(
                "build_edit_blocked",
                "Wait for the new specialization state to finish refreshing."
            )
            return false
        end
        local requested = trim(tostring(spec or ""))
        local values = {}
        local matchedNames = {}
        local numericValue = canonicalSpellID(tonumber(requested))
        if uiIsInteger(numericValue, 1, UI_MAX_SPELL_ID) then
            values[1] = numericValue
        else
            -- An exact name is allowed to resolve to every distinct live ID.
            -- Partial names remain a single best-match lookup to avoid adding
            -- unrelated entries that merely share a search fragment.
            local matches = exactEntryMatches(side, requested)
            if #matches == 0 then
                matches = fuzzyEntryMatches(side, requested, 6)
                if #matches > 0 then
                    for index = #matches, 2, -1 do
                        matches[index] = nil
                    end
                end
            end
            if #matches == 0 then
                self:appendLog(
                    "build_edit_blocked",
                    "No " .. sideTitle(side) .. " matched \""
                        .. requested .. "\". Type part of its name or ID."
                )
                return false
            end
            for _, match in ipairs(matches) do
                local value = canonicalSpellID(match.id)
                if uiIsInteger(value, 1, UI_MAX_SPELL_ID) then
                    values[#values + 1] = value
                    matchedNames[value] = match.name
                end
            end
        end
        if #values == 0 then
            return false
        end
        if not self:canEditCustomBuild() then
            self:appendLog(
                "build_edit_blocked",
                "The planner is not ready for editing yet. Stop any active roll or wait for the specialization refresh."
            )
            return false
        end
        local attempt = self:beginCustomEdit()
        if not attempt then
            return false
        end
        local payload = attempt.payload
        local list = payload[side]
        local added = {}
        for index, value in ipairs(values) do
            local present = false
            for _, id in ipairs(list) do
                if id == value then
                    present = true
                    break
                end
            end
            if not present then
                if #list + #added >= uiSideLimit(side) then
                    break
                end
                added[#added + 1] = value
            end
        end
        if #added == 0 then
            if #values == 1 then
                self:appendLog(
                    "build_edit_blocked",
                    sideTitle(side) .. " #"
                        .. tostring(values[1])
                        .. " is already in this build."
                )
            else
                self:appendLog(
                    "build_edit_blocked",
                    "All matching " .. sideTitle(side)
                        .. " IDs are already in this build."
                )
            end
            return false
        end
        for _, value in ipairs(added) do
            list[#list + 1] = value
        end
        if not self:applyCustomPayload(payload) then
            return false
        end
        local labels = {}
        for _, value in ipairs(added) do
            local name = matchedNames[value]
            labels[#labels + 1] = name
                and (name .. " (#" .. tostring(value) .. ")")
                or ("#" .. tostring(value))
        end
        self:appendLog(
            "build_edit",
            "Added " .. sideTitle(side) .. " "
                .. table.concat(labels, ", ")
                .. " to the editable build."
        )
        return true
    end

    function ui:removeCustomEntry(side, spellID)
        if not self:canEditCustomBuild() then
            return false
        end
        local value = canonicalSpellID(tonumber(spellID))
        if not uiIsInteger(value, 1, UI_MAX_SPELL_ID) then
            return false
        end
        local attempt = self:beginCustomEdit()
        if not attempt then
            return false
        end
        local payload = attempt.payload
        local list = payload[side]
        local removed = false
        for index = #list, 1, -1 do
            if list[index] == value then
                table.remove(list, index)
                removed = true
            end
        end
        if not removed then
            self:appendLog(
                "build_edit_blocked",
                sideTitle(side) .. " #" .. tostring(value)
                    .. " is not part of this analyzed build."
            )
            return false
        end
        if not self:applyCustomPayload(payload) then
            return false
        end
        if self.panel and self.panel.PlanPanes
            and self.panel.PlanPanes[side]
            and self.panel.PlanPanes[side].frame
            and self.panel.PlanPanes[side].frame[side .. "AddBox"] then
            self.panel.PlanPanes[side].frame[side .. "AddBox"]:ClearFocus()
        end
        self:appendLog(
            "build_edit",
            "Removed " .. sideTitle(side) .. " #" .. tostring(value)
                .. " from the editable build."
        )
        return true
    end

    function ui:canEditCustomBuild()
        if self:isSessionBusy() then
            self:appendLog(
                "build_edit_blocked",
                "Stop the active rolling session before editing this build."
            )
            return false
        end
        if self.specializationSettling then
            self:appendLog(
                "build_edit_blocked",
                "Wait for the new specialization state to finish refreshing."
            )
            return false
        end
        if self:isCustomBuildActive() then
            return true
        end
        local key = buildKey(self:draftLink())
        if self.lastAnalysis
            and self.lastAnalysis.ok
            and self.lastAnalysis.parsed
            and self.lastAnalyzedKey == key then
            return true
        end
        local draft = trim(self:draftLink())
        if draft ~= "" then
            local normalized = decodePercentEncoded(draft)
            local isBuildCandidate = self:isCustomBuildCandidate()
                or self:isPlainIDListCandidate()
                or normalized:find("#b=", 1, true) ~= nil
            if isBuildCandidate then
                self:analyze()
                if self:hasAnalyzedBuild() then
                    return true
                end
            end
            -- An Add action is also allowed to bootstrap a new custom build.
            -- beginCustomEdit will replace an unreadable stale draft with an
            -- empty payload and then apply the requested entry immediately.
            return true
        end
        return true
    end

    function ui:beginCustomEdit()
        if not self:canEditCustomBuild() then
            return nil
        end
        local payload = self:customBuildPayload()
        if not payload and self.lastAnalysis
            and self.lastAnalysis.ok
            and self.lastAnalysis.parsed
            and self.lastAnalyzedKey == buildKey(self:draftLink()) then
            payload = self:payloadFromParsed(self.lastAnalysis.parsed)
        end
        if not payload then
            -- Adding an entry before the first analysis starts a new editable
            -- custom build. This also recovers from stale or invalid text left
            -- in the main draft field without requiring a separate reset step.
            payload = {
                v = 1,
                name = "Lazy Roller build",
                primaryStat = "",
                abilities = {},
                talents = {},
            }
        end
        return {
            payload = self:customBuildFromPayload(payload),
        }
    end

    function ui:refreshBuildEditor()
        if not self.panel or not self.panel.PlanPanes then
            return
        end
        local custom = self:isCustomBuildActive()
        local candidate = custom
            or self:isCustomBuildCandidate()
            or self:isPlainIDListCandidate()
            or trim(self:draftLink()) ~= ""
        for _, side in ipairs({ "abilities", "talents" }) do
            local pane = self.panel.PlanPanes[side]
            local box = pane and pane.frame and pane.frame[side .. "AddBox"]
            local button = pane and pane.frame and pane.frame[side .. "AddButton"]
            local hint = pane and pane.frame and pane.frame[side .. "BuildHint"]
            local editable = not self:isSessionBusy()
            if box then
                box:SetEnabled(editable)
            end
            if button then
                button:SetEnabled(editable)
            end
            if hint then
                local hintText
                if custom then
                    hintText = "Right-click a row to remove it from this build. Type an ID or name and press Add to include it."
                elseif candidate then
                    hintText = "Click Add or Analyze to load this full build into the planner."
                else
                    hintText = "Type an ID or name and click Add to start a build, or paste a full link and click Analyze."
                end
                hint:SetText(hintText)
                hint:SetTextColor(custom and 0.72 or candidate and 0.62 or 0.48,
                    custom and 0.90 or candidate and 0.78 or 0.48,
                    custom and 0.84 or candidate and 0.92 or 0.48)
            end
        end
    end

    function ui:refreshSessionSummary()
        if not self.panel then
            return
        end
        local mode = self:activeMode()
        local controller = mode == "rapid"
            and runtime.rapidController
            or runtime.controller
        local phase = controller and controller.phase or "idle"
        local stateWord = "IDLE"
        local color = { 0.72, 0.72, 0.72 }
        if mode then
            if controller.paused then
                stateWord = "PAUSED"
                color = { 1.00, 0.78, 0.20 }
            elseif controller.running then
                stateWord = "RUNNING"
                color = { 0.38, 1.00, 0.46 }
            else
                stateWord = "FINISHING"
                color = { 1.00, 0.72, 0.25 }
            end
        end
        if runtime.rapidController:canReloadRecovery() then
            stateWord = "RECOVERY REQUIRED"
            color = { 1.00, 0.55, 0.16 }
        elseif mode and self:sessionRetiring() then
            stateWord = "RETIRING"
            color = { 0.40, 0.78, 1.00 }
        elseif self.rollOffSelecting then
            stateWord = "CHOOSING "
                .. string.upper(rollOffChoiceNoun(self.rollOffState))
            color = { 1.00, 0.72, 0.20 }
        end
        self.panel.SessionTitle:SetText(
            string.upper(mode or "no active session") .. " · " .. stateWord
        )
        self.panel.SessionTitle:SetTextColor(unpack(color))
        local phaseSummary = phaseText(phase)
        if mode then
            phaseSummary = phaseSummary
                .. " · limit "
                .. tostring(controller.sessionLimit or "unlimited")
                .. " · roll "
                .. rollSideDescription(controller.rollSides)
                .. string.format(
                    " · floor A%d/T%d",
                    normalizeCount(
                        controller.highRollFloors
                            and controller.highRollFloors.abilities
                    ),
                    normalizeCount(
                        controller.highRollFloors
                            and controller.highRollFloors.talents
                    )
                )
            phaseSummary = phaseSummary
                .. (controller.allowStandardTalentScrolls
                    and " · standard talents on"
                    or " · standard talents off")
        end
        self.panel.SessionPhase:SetText(phaseSummary)
        local balances
        local balancesError
        local ok, value, reason = pcall(runtime.api.getScrollBalances)
        if ok then
            balances = value
            balancesError = reason
        else
            balancesError = value
        end
        local spent = { abilities = 0, talents = 0 }
        local batches = 0
        if mode == "rapid" then
            spent = runtime.rapidController.rollsBySide or spent
            batches = normalizeCount(runtime.rapidController.batches)
        elseif mode == "single" then
            spent = runtime.controller.rollsBySide or spent
        end
        local abilityProgress = M.buildSlotProgress(
            self.lastAnalysis,
            "abilities"
        )
        local talentProgress = M.buildSlotProgress(
            self.lastAnalysis,
            "talents"
        )
        renderSlotProgress(
            self.panel.SlotProgress.abilities,
            abilityProgress
        )
        renderSlotProgress(
            self.panel.SlotProgress.talents,
            talentProgress
        )
        if balances then
            self.panel.SlotProgress.abilities.currency:SetText(string.format(
                "%d",
                abilityBalance(balances)
            ))
            self.panel.SlotProgress.abilities.session:SetText(string.format(
                "%d dedicated + %d standard · %d spent",
                normalizeCount(balances.abilities),
                normalizeCount(balances.shared),
                normalizeCount(spent.abilities)
            ))
            self.panel.SlotProgress.talents.currency:SetText(string.format(
                "%d",
                normalizeCount(balances.talents)
            ))
            self.panel.SlotProgress.talents.session:SetText(string.format(
                "%d spent%s",
                normalizeCount(spent.talents),
                mode == "rapid"
                    and string.format(
                        " · %d batch%s",
                        batches,
                        batches == 1 and "" or "es"
                    )
                    or ""
            ))
        else
            local message = tostring(balancesError or "unavailable")
            self.panel.SlotProgress.abilities.currency:SetText("—")
            self.panel.SlotProgress.abilities.session:SetText(message)
            self.panel.SlotProgress.talents.currency:SetText("—")
            self.panel.SlotProgress.talents.session:SetText(message)
        end

        local nextText = "Analyze a build to preview the next roll."
        if mode == "single" and self.lastRecommendation then
            nextText = string.format(
                "NEXT SINGLE: %s\nPity pressure %d · %s",
                self.lastRecommendation.candidate.name,
                pityPressure(self.lastRecommendation.candidate),
                schedulingGuidance(
                    self.lastSchedule,
                    self.lastRecommendation.demand
                )
            )
        elseif self.lastRapidProjection then
            nextText = string.format(
                "NEXT RAPID: %s · %d desired / %d undesired\n%s",
                string.upper(self.lastRapidProjection.side),
                #self.lastRapidProjection.desired,
                #self.lastRapidProjection.undesired,
                string.format(
                    "Pity pressure %d · %s",
                    pityPressure(self.lastRapidProjection),
                    schedulingGuidance(self.lastRapidProjection)
                )
            )
        elseif self.lastRecommendation then
            nextText = string.format(
                "NEXT SINGLE: %s\nPity pressure %d · %s",
                self.lastRecommendation.candidate.name,
                pityPressure(self.lastRecommendation.candidate),
                schedulingGuidance(
                    self.lastSchedule,
                    self.lastRecommendation.demand
                )
            )
        elseif self.rollOffState then
            nextText = string.upper(rollOffSlotsText(self.rollOffState)) .. "\n"
                .. rollOffDemandText(self.rollOffState)
                .. "; choose one owned "
                .. rollOffChoiceNoun(self.rollOffState) .. "."
        elseif self.lastRapidError then
            nextText = "RAPID PREVIEW BLOCKED\n" .. tostring(self.lastRapidError)
        end
        self.panel.NextSummary:SetText(nextText)
    end

    function ui:layoutRecovery()
        if not self.panel then
            return
        end
        local showRecovery = runtime.rapidController:canReloadRecovery()
        local showRollOff = not showRecovery
            and self.rollOffState ~= nil
            and not self:isSessionBusy()
            and runtime.controller.lockSync == nil
            and not self.specializationSettling
        if showRecovery then
            self.panel.RecoveryFrame:Show()
        else
            self.panel.RecoveryFrame:Hide()
        end
        if showRollOff then
            self.panel.RollOffFrame:Show()
            self.panel.RollOffText:SetText(
                rollOffSlotsText(self.rollOffState) .. " · "
                    .. rollOffDemandText(self.rollOffState)
                    .. ".\nChoose one owned "
                    .. rollOffChoiceNoun(self.rollOffState)
                    .. " to roll off once."
            )
            self.panel.RollOffButton:SetText(
                self.rollOffSelecting and "Cancel selection"
                    or ("Choose " .. rollOffChoiceNoun(self.rollOffState))
            )
        else
            self.panel.RollOffFrame:Hide()
        end
        -- Controls end at y=324. A contextual action card occupies
        -- y=332..402 when visible, so both feed stacks begin below the last
        -- visible control instead of sharing its space.
        local feedStart = (showRecovery or showRollOff) and 414 or 336
        local topOffset = -feedStart
        local feedHeight = math.max(
            18,
            math.floor(
                (self.panel.RightPaneHeight - feedStart - 56) / 2
            )
        )
        self.panel.ResultsTitle:ClearAllPoints()
        self.panel.ResultsTitle:SetPoint(
            "TOPLEFT",
            self.panel.RightPane,
            "TOPLEFT",
            12,
            topOffset
        )
        self.panel.ResultsFeed.scroll:ClearAllPoints()
        self.panel.ResultsFeed.scroll:SetPoint(
            "TOPLEFT",
            self.panel.ResultsTitle,
            "BOTTOMLEFT",
            0,
            -5
        )
        self.panel.ResultsFeed.scroll:SetSize(
            self.panel.RightPaneWidth - 40,
            feedHeight
        )
        self.panel.ResultsFeed.height = feedHeight
        self.panel.ActivityTitle:ClearAllPoints()
        self.panel.ActivityTitle:SetPoint(
            "TOPLEFT",
            self.panel.ResultsFeed.scroll,
            "BOTTOMLEFT",
            0,
            -12
        )
        self.panel.ActivityFeed.scroll:ClearAllPoints()
        self.panel.ActivityFeed.scroll:SetPoint(
            "TOPLEFT",
            self.panel.ActivityTitle,
            "BOTTOMLEFT",
            0,
            -5
        )
        self.panel.ActivityFeed.scroll:SetSize(
            self.panel.RightPaneWidth - 40,
            feedHeight
        )
        self.panel.ActivityFeed.height = feedHeight
        updateTextFeed(self.panel.ResultsFeed, self.protectionLog)
        updateTextFeed(self.panel.ActivityFeed, self.log)
    end

    function ui:refreshButtons()
        if not self.panel then
            return
        end
        if self.viewMode == "minimized" then
            self:refreshTracker()
            return
        end
        local controller = runtime.controller
        local rapid = runtime.rapidController
        local syncing = controller.lockSync ~= nil
        local singleBusy = self:singleBusy()
        local rapidBusy = self:rapidBusy()
        local busy = singleBusy or rapidBusy
        local contextSettling = self.specializationSettling
        local selectingRollOff = self.rollOffSelecting
        local changingRollSides = not syncing
            and not selectingRollOff
            and not contextSettling
            and runtime.controller.oneShotRollOff == nil
        if not syncing and not selectingRollOff then
            self.panel.SessionLimitBox:Enable()
            self.panel.HighRollAbilityBox:Enable()
            self.panel.HighRollTalentBox:Enable()
        else
            self.panel.SessionLimitBox:Disable()
            self.panel.HighRollAbilityBox:Disable()
            self.panel.HighRollTalentBox:Disable()
        end
        if not busy and not syncing and not selectingRollOff
            and not contextSettling then
            self.panel.StandardTalentCheck:Enable()
        else
            self.panel.StandardTalentCheck:Disable()
        end
        if changingRollSides then
            self.panel.RollAbilitiesCheck:Enable()
            self.panel.RollTalentsCheck:Enable()
        else
            self.panel.RollAbilitiesCheck:Disable()
            self.panel.RollTalentsCheck:Disable()
        end
        local configuredRollSides = self:configuredRollSides()
        local hasRollSide = configuredRollSides.abilities
            or configuredRollSides.talents
        local analysisReady = self.lastAnalysis and self.lastAnalysis.ok
        local optionalCategories = self:optionalCategories()
        local optionalActive, optionalTotal =
            optionalCategorySummary(optionalCategories)
        if optionalTotal > 0 then
            self.panel.OptionalCategoriesButton:Show()
            self.panel.OptionalCategoriesButton:SetText(string.format(
                "Auto-Roll categories: %d/%d on",
                optionalActive,
                optionalTotal
            ))
        else
            self.panel.OptionalCategoriesButton:Hide()
            self.panel.OptionalCategoryFrame:Hide()
        end
        setButtonEnabled(
            self.panel.OptionalCategoriesButton,
            analysisReady and optionalTotal > 0
        )
        if self.panel.OptionalCategoryFrame:IsShown() then
            self:renderOptionalCategories()
        end
        setButtonEnabled(
            self.panel.StartButton,
            not busy
                and not syncing
                and not selectingRollOff
                and not contextSettling
                and analysisReady
                and hasRollSide
                and self.lastRecommendation ~= nil
        )
        setButtonEnabled(
            self.panel.StartRapidButton,
            not busy
                and not syncing
                and not selectingRollOff
                and not contextSettling
                and analysisReady
                and hasRollSide
                and self.lastRapidProjection ~= nil
        )
        setButtonEnabled(
            self.panel.PauseButton,
            busy
                and not self:sessionRetiring()
                and not self:draftDiffers()
        )
        local paused = controller.paused or rapid.paused
        if self:sessionRetiring() or self:draftDiffers() then
            self.panel.PauseButton:SetText("Resume unavailable")
        else
            self.panel.PauseButton:SetText(paused and "Resume" or "Pause")
        end
        setButtonEnabled(self.panel.StopButton, busy)
        if rapidBusy and (rapid.batchActive or rapid.batchFinalizing) then
            self.panel.StopButton:SetText("Stop after batch")
        elseif singleBusy and controller.pendingRoll then
            self.panel.StopButton:SetText("Stop after roll")
        else
            self.panel.StopButton:SetText("Stop")
        end
        setButtonEnabled(
            self.panel.SyncLocksButton,
            not busy and not syncing and not selectingRollOff
                and not contextSettling
        )
        setButtonEnabled(
            self.panel.AnalyzeButton,
            not syncing and not selectingRollOff and not contextSettling
        )
        setButtonEnabled(
            self.panel.MinimizeButton,
            not syncing and not selectingRollOff
        )
        setButtonEnabled(
            self.panel.RollOffButton,
            not busy and not syncing and not contextSettling
                and self.rollOffState ~= nil
        )
        setButtonEnabled(
            self.panel.ReloadRecoveryButton,
            rapid:canReloadRecovery()
        )
        self.panel.ReloadRecoveryButton:SetText(
            self:sessionRetiring()
                and "Reload & finish"
                or "Reload & resume"
        )
        self:refreshDraftState()
        self:refreshSessionSummary()
        self:layoutRecovery()
        self:refreshTracker()
    end

    function ui:appendLog(kind, text)
        self.log[#self.log + 1] = string.format(
            "[%s] %s",
            tostring(kind),
            tostring(text)
        )
        while #self.log > 18 do
            table.remove(self.log, 1)
        end
        if self.panel and self.viewMode == "full"
            and self.panel:IsShown() then
            self.panel.Status:SetText(text)
            updateTextFeed(self.panel.ActivityFeed, self.log)
            self:refreshButtons()
        else
            self:refreshTracker()
        end
        print("Lazy Roller: " .. tostring(text))
    end

    function ui:appendProtection(text)
        self.protectionLog[#self.protectionLog + 1] = tostring(text)
        while #self.protectionLog > 20 do
            table.remove(self.protectionLog, 1)
        end
        if self.panel and self.viewMode == "full"
            and self.panel:IsShown() then
            updateTextFeed(self.panel.ResultsFeed, self.protectionLog)
        end
    end

    function ui:findDesired(entryID, engine)
        if not entryID then
            return
        end
        local result = self.lastAnalysis
        if not result or not result.ok then
            return
        end
        for _, desired in ipairs(result.desiredEntries or {}) do
            if desired.entryID == entryID then
                return desired
            end
        end
    end

    function ui:desiredLabel(desired)
        if not desired then
            return "desired"
        end
        return string.format(
            "%s · %s%s",
            desired.side == "talents" and "Talent" or "Ability",
            CATEGORY_LABELS[desired.sectionKind]
                or desired.sectionKind
                or "desired",
            desired.sectionName and desired.sectionName ~= ""
                and (" · " .. desired.sectionName) or ""
        )
    end

    function ui:startNewSession(data)
        if self.specializationSettling
            or data.specializationGeneration ~= nil
                and data.specializationGeneration
                    ~= self.specializationGeneration
            or data.buildKey ~= buildKey(self:draftLink())
            or not sameRollSides(
                data.rollSides,
                self:configuredRollSides()
            ) then
            local reason =
                "That confirmation belongs to an older build, specialization, or Roll selection. Review the refreshed plan and press Start again."
            self:appendLog("specialization_blocked", reason)
            return false, reason
        end
        self.rollOffSelecting = false
        self:commitLink(data.link)
        local ok
        local reason
        if data.mode == "rapid" then
            ok, reason = runtime.rapidController:start(
                data.link,
                data.sessionLimit,
                false,
                data.highRollFloors,
                data.allowStandardTalentScrolls,
                data.rollSides
            )
        else
            ok, reason = runtime.controller:start(
                data.link,
                data.sessionLimit,
                data.highRollFloors,
                data.allowStandardTalentScrolls,
                data.rollSides
            )
        end
        if not ok then
            self:appendLog(
                data.mode == "rapid" and "rapid_blocked" or "blocked",
                reason
            )
            return false, reason
        end
        self.linkInvalidated = false
        self.pendingStop = false
        self.specializationReset = false
        self:refreshButtons()
        return true
    end

    function ui:tryPendingStop()
        if not self.pendingStop or runtime.controller.pendingRoll then
            return
        end
        self.pendingStop = false
        if self:singleBusy() then
            runtime.controller:stop(
                self.linkInvalidated
                    and "The previous single-roll session ended after its accepted roll finished because the build link changed."
                    or "Stopped safely after the accepted roll finished.",
                "stopped"
            )
        end
    end

    function ui:retireActiveSessionForLinkChange()
        if self.linkInvalidated then
            return false
        end
        local mode = self:activeMode()
        if not mode then
            return false
        end

        self.linkInvalidated = true
        if mode == "rapid" then
            self:appendLog(
                "link_changed",
                "Build link changed; the previous Rapid session is dead. Its accepted native batch or upgrade recovery will finish safely, then no new batch will start."
            )
            runtime.rapidController:stop(
                "The previous Rapid session ended because the build link changed. Start the updated build explicitly.",
                "rapid_stopped"
            )
        elseif runtime.controller.pendingRoll then
            self.pendingStop = true
            if runtime.controller.running then
                runtime.controller:pause(
                    "Build link changed; the accepted roll will finish, then the previous session will end permanently."
                )
            end
            self:appendLog(
                "link_changed",
                "Build link changed; the previous single-roll session cannot resume. Its accepted roll will finish, then no new roll will start."
            )
        else
            runtime.controller:stop(
                "The previous single-roll session ended because the build link changed. Start the updated build explicitly.",
                "stopped"
            )
        end
        self:refreshButtons()
        return true
    end

    function ui:onDraftLinkChanged()
        if self.rollOffSelecting then
            self.rollOffSelecting = false
        end
        -- Every confirmation captures the analyzed build. Editing the draft
        -- retires that authorization immediately; accepting a popup that is
        -- still on screen must never act on the previous link.
        if type(StaticPopup_Hide) == "function" then
            StaticPopup_Hide("LAZY_ROLLER_START")
            StaticPopup_Hide("LAZY_ROLLER_START_RAPID")
            StaticPopup_Hide("LAZY_ROLLER_SYNC_LOCKS")
            StaticPopup_Hide("LAZY_ROLLER_ROLL_OFF")
        end
        self:saveInputs()
        local key = buildKey(self:draftLink())
        if self.lastAnalyzedKey ~= key then
            self.lastAnalysis = nil
            self.lastRecommendation = nil
            self.lastSchedule = nil
            self.lastRapidProjection = nil
            self.lastRapidError = nil
        end
        if self:draftDiffers() then
            self:retireActiveSessionForLinkChange()
        end
        self:refreshButtons()
        self:refreshBuildEditor()
    end

    function ui:onRollSidesChanged()
        if type(StaticPopup_Hide) == "function" then
            StaticPopup_Hide("LAZY_ROLLER_START")
            StaticPopup_Hide("LAZY_ROLLER_START_RAPID")
        end

        local mode = self:activeMode()
        if mode == "rapid" then
            runtime.rapidController:stop(
                "The Rapid session ended because the Roll selection changed. Start again to use the new selection.",
                "rapid_stopped"
            )
            self:appendLog(
                "roll_sides_changed",
                "Roll selection changed. The current Rapid session is retiring safely; start again to use the new selection."
            )
        elseif mode == "single" then
            if runtime.controller.pendingRoll then
                self.pendingStop = true
                if runtime.controller.running then
                    runtime.controller:pause(
                        "Roll selection changed. The accepted roll will finish before this session ends."
                    )
                end
                self:appendLog(
                    "roll_sides_changed",
                    "Roll selection changed. The accepted single roll will finish, then the session will stop."
                )
            else
                runtime.controller:stop(
                    "The single-roll session ended because the Roll selection changed. Start again to use the new selection.",
                    "stopped"
                )
                self:appendLog(
                    "roll_sides_changed",
                    "Roll selection changed. The single-roll session stopped; start again to use the new selection."
                )
            end
        else
            self:analyze()
        end
        self:refreshButtons()
        return true
    end

    function ui:requestPauseToggle()
        if self.specializationSettling then
            self:appendLog(
                "resume_blocked",
                "Wait for the new specialization state to finish refreshing, then explicitly start a new session."
            )
            return false
        end
        if self:sessionRetiring() or self:draftDiffers() then
            self:appendLog(
                "resume_blocked",
                "The build link changed; the previous session cannot be resumed. Analyze and explicitly start the updated build."
            )
            return false
        end
        local ok
        local reason
        if runtime.rapidController.paused then
            ok, reason = runtime.rapidController:resume()
            if not ok then
                self:appendLog("rapid_blocked", reason)
            end
        elseif runtime.rapidController.running then
            ok, reason = runtime.rapidController:pause()
            if not ok then
                self:appendLog("rapid_blocked", reason)
            end
        elseif runtime.controller.paused then
            ok, reason = runtime.controller:resume()
            if not ok then
                self:appendLog("blocked", reason)
            end
        else
            ok, reason = runtime.controller:pause()
            if not ok then
                self:appendLog("blocked", reason)
            end
        end
        self:refreshButtons()
        return ok, reason
    end

    function ui:requestRapidReloadRecovery()
        local ok, reason =
            runtime.rapidController:requestReloadRecovery("manual")
        if not ok then
            self:appendLog("rapid_reload_blocked", reason)
        end
        self:refreshButtons()
        return ok, reason
    end

    function ui:onControllerEvent(kind, text, data)
        if kind ~= "reveal_complete" then
            self:appendLog(kind, text)
        end
        if kind == "started" or kind == "rapid_started" then
            self:appendProtection(
                kind == "rapid_started"
                    and "--- New Rapid session ---"
                    or "--- New single-roll session ---"
            )
        elseif (kind == "result" or kind == "upgrade")
            and data and data.entryID then
            -- Rapid results carry the desired metadata captured before the
            -- batch started. Prefer it over a synchronous live re-analysis:
            -- Character Advancement can transiently hide the newly learned
            -- entry while the native reveal is still settling.
            local desired = data.desiredSnapshot
                or self:findDesired(data.entryID, data.engine)
            if desired then
                self:appendProtection(
                    string.format(
                        "%s %d · %s %s · %s",
                        data.engine == "rapid" and "Batch" or "Roll",
                        data.engine == "rapid"
                            and (data.batch or 0)
                            or (data.roll
                                or runtime.controller.rollsSpent
                                or 0),
                        desired.name or data.name,
                        kind == "upgrade"
                            and string.format(
                                "rank %s/%s",
                                tostring(data.newRank or "?"),
                                tostring(desired.maxRank or "?")
                            )
                            or "learned",
                        self:desiredLabel(desired)
                    )
                )
            end
        end

        self:tryPendingStop()

        if self.viewMode ~= "full" then
            self.analysisDirty = true
            self:refreshTracker()
            return
        end
        if self.panel
            and not self.worldTransition
            and not self.specializationSettling then
            self:analyze()
        elseif self.panel then
            self:refreshButtons()
        end
    end

    function ui:plainIDPayload()
        if not self:isPlainIDListCandidate() then
            return nil
        end
        local payload = {
            v = 1,
            name = "Imported ID list",
            primaryStat = "",
            abilities = {},
            talents = {},
        }
        local seen = {}
        for token in trim(self:draftLink()):gmatch("[^,%s]+") do
            local spellID = canonicalSpellID(tonumber(token))
            if not uiIsInteger(spellID, 1, UI_MAX_SPELL_ID) then
                return nil, "ID lists may only contain positive numeric IDs."
            end
            if seen[spellID] then
                return nil, "ID #" .. tostring(spellID) .. " appears more than once."
            end
            seen[spellID] = true
            local ok, entry = pcall(
                resolveEntryBySpellID,
                runtime.api,
                spellID
            )
            if not ok or type(entry) ~= "table" then
                return nil, "Unknown live entry for ID #" .. tostring(spellID) .. "."
            end
            local side
            if entry.Type == "Talent" then
                side = "talents"
            elseif entry.Type == "Ability"
                or entry.Type == "TalentAbility" then
                side = "abilities"
            end
            if not side then
                return nil, "ID #" .. tostring(spellID)
                    .. " is not a live ability or talent."
            end
            local list = payload[side]
            if #list >= uiSideLimit(side) then
                return nil, sideTitle(side)
                    .. " exceed the custom build safety limit ("
                    .. tostring(uiSideLimit(side)) .. ")."
            end
            list[#list + 1] = spellID
        end
        return payload
    end

    function ui:prepareDraftLink()
        local raw = self:draftLink()
        local payload, importError = self:plainIDPayload()
        if not payload then
            return raw, importError
        end
        if not addon.codec
            or type(addon.codec.encodeBuildPayload) ~= "function" then
            return raw, "This client cannot convert a comma-separated ID list."
        end
        local encoded, encodeError = addon.codec.encodeBuildPayload(payload)
        if not encoded then
            return raw, encodeError
        end
        self.loadingEdit = true
        self.panel.EditBox:SetText(encoded)
        self.loadingEdit = false
        self:saveInputs()
        return encoded
    end

    function ui:analyze()
        if not self.panel then
            return { ok = false, errors = { "The Auto-Roller panel is unavailable." } }
        end
        if self.specializationSettling then
            self:refreshButtons()
            return {
                ok = false,
                errors = {
                    "Wait for the new specialization state to finish refreshing.",
                },
            }
        end
        local panel = self.panel
        local link, importError = self:prepareDraftLink()
        local result
        if importError then
            result = {
                ok = false,
                errors = { importError },
                lockSuggestions = {},
                surplusAnyEntries = {},
                desiredEntries = {},
                knownDesiredEntries = {},
                sides = {
                    abilities = { sections = {} },
                    talents = { sections = {} },
                },
            }
        else
            result = runtime.core.analyze(link, runtime.api)
        end
        local recommendation
        local schedule
        local rapidProjection
        local rapidError
        local rollOffState
        if result.ok then
            local abilityRollOffState
            local talentRollOffState
            if runtime.core.rollOffState then
                abilityRollOffState = runtime.core.rollOffState(
                    result,
                    "abilities"
                )
                talentRollOffState = runtime.core.rollOffState(
                    result,
                    "talents"
                )
            else
                abilityRollOffState = runtime.core.abilityRollOffState
                    and runtime.core.abilityRollOffState(result)
                talentRollOffState = runtime.core.talentRollOffState
                    and runtime.core.talentRollOffState(result)
            end
            rollOffState = combineRollOffStates(
                abilityRollOffState,
                talentRollOffState
            )
            local configuredFloors = self:configuredHighRollFloors()
            local configuredStandardTalentFallback =
                self:configuredStandardTalentFallback()
            local configuredRollSides = self:configuredRollSides()
            local singleFloors = self:singleBusy()
                and runtime.controller.highRollFloors
                or configuredFloors
            local rapidFloors = self:rapidBusy()
                and runtime.rapidController.highRollFloors
                or configuredFloors
            local singleStandardTalentFallback =
                configuredStandardTalentFallback
            if self:singleBusy() then
                singleStandardTalentFallback =
                    runtime.controller.allowStandardTalentScrolls
                        and true or false
            end
            local rapidStandardTalentFallback =
                configuredStandardTalentFallback
            if self:rapidBusy() then
                rapidStandardTalentFallback =
                    runtime.rapidController.allowStandardTalentScrolls
                        and true or false
            end
            local singleRollSides = self:singleBusy()
                and runtime.controller.rollSides
                or configuredRollSides
            local rapidRollSides = self:rapidBusy()
                and runtime.rapidController.rollSides
                or configuredRollSides
            recommendation, schedule =
                runtime.controller:selectRecommendation(
                    result,
                    runtime.controller.running
                        or runtime.controller.paused,
                    singleFloors,
                    singleStandardTalentFallback,
                    singleRollSides
                )
            if type(runtime.rapidController.previewAnalysis) == "function" then
                rapidProjection, rapidError =
                    runtime.rapidController:previewAnalysis(
                        result,
                        rapidFloors,
                        rapidStandardTalentFallback,
                        rapidRollSides
                    )
            else
                rapidProjection, rapidError =
                    runtime.rapidController:preview(
                        link,
                        rapidFloors,
                        rapidStandardTalentFallback,
                        rapidRollSides
                    )
            end
        end
        self.lastAnalysis = result
        self.lastRecommendation = recommendation
        self.lastSchedule = schedule
        self.lastRapidProjection = rapidProjection
        self.lastRapidError = rapidError
        self.rollOffState = rollOffState
        if self.rollOffSelecting and not rollOffState then
            self.rollOffSelecting = false
        end
        self.lastAnalyzedKey = buildKey(link)
        self.analysisDirty = false
        if self.viewMode ~= "minimized" then
            panel.Analysis:SetText(analysisText(
                result,
                recommendation,
                schedule,
                rapidProjection,
                rapidError,
                rollOffState
            ))
            panel.Analysis:SetTextColor(
                result.ok and 0.72 or 1,
                result.ok and 0.90 or 0.35,
                result.ok and 0.72 or 0.35
            )
            self:renderPlan(result)
        end
        self:refreshButtons()
        return result
    end

    function ui:requestAnalyze()
        self.rollOffSelecting = false
        self:saveInputs()
        if self.specializationSettling then
            self:appendLog(
                "specialization_waiting",
                "Wait for Ascension to finish refreshing the new specialization before analyzing."
            )
            return {
                ok = false,
                errors = {
                    "The specialization context is still refreshing.",
                },
            }
        end
        return self:analyze()
    end

    function ui:requestStop()
        local mode = self:activeMode()
        if mode == "rapid" then
            local rapid = runtime.rapidController
            if rapid.stopAfterBatch then
                self:appendLog(
                    "stop_waiting",
                    "The previous Rapid session is already retiring at the accepted batch boundary."
                )
                return true
            end
            if rapid.upgradeBoundaryActive then
                self:appendLog(
                    "stop_blocked",
                    "Finish the awarded Talent Essence recovery before ending this Rapid session; cancelling this boundary is known to wedge the client."
                )
                return false
            end
            rapid:stop(
                "Rapid session stopped by the player.",
                "rapid_stopped"
            )
            return true
        elseif mode == "single" then
            if runtime.controller.pendingRoll then
                self.pendingStop = true
                if runtime.controller.running then
                    runtime.controller:pause(
                        "Stop requested; the accepted roll will finish before the session ends."
                    )
                end
                self:appendLog(
                    "stop_waiting",
                    "The session will stop after the accepted single roll finishes."
                )
                return true
            end
            runtime.controller:stop(
                "Single-roll session stopped by the player.",
                "stopped"
            )
            return true
        end
        self:refreshButtons()
        return false
    end

    function ui:toggleRollOffSelection()
        if self.rollOffSelecting then
            self.rollOffSelecting = false
            if self.lastAnalysis then
                self:renderPlan(self.lastAnalysis)
            end
            self:refreshButtons()
            return true
        end
        if self:isSessionBusy() or runtime.controller.lockSync then
            self:appendLog(
                "rolloff_blocked",
                "Finish the active action before choosing a build entry to roll off."
            )
            return false
        end
        local result = self:analyze()
        if not result.ok or not self.rollOffState then
            self:appendLog(
                "rolloff_blocked",
                "A protected build-entry roll off is not needed in the current analyzed state."
            )
            return false
        end
        self.rollOffSelecting = true
        self:renderPlan(result)
        self:refreshButtons()
        return true
    end

    function ui:requestRollOff(item)
        if not self.rollOffSelecting or not item then
            return false
        end
        local result = self:analyze()
        local state = rollOffStateForSide(self.rollOffState, item.side)
        if not result.ok or not state or not state.eligibleSet
            or not state.eligibleSet[item.entryID] then
            self.rollOffSelecting = false
            self:renderPlan(result)
            self:refreshButtons()
            self:appendLog(
                "rolloff_blocked",
                "That "
                    .. sideNoun(item.side)
                    .. " is no longer eligible for the one-time roll off."
            )
            return false
        end
        local selected
        for _, possible in ipairs(state.eligible or {}) do
            if possible.entryID == item.entryID then
                selected = possible
                break
            end
        end
        if not selected then
            return false
        end
        local confirmationName = selected.name
        if selected.side == "talents" then
            confirmationName = string.format(
                "%s (Rank %d/%d)",
                selected.name,
                normalizeCount(selected.currentRank),
                math.max(
                    1,
                    normalizeCount(selected.maxRank),
                    normalizeCount(selected.targetRank)
                )
            )
        end
        showConfirmationPopup(
            self.panel,
            "LAZY_ROLLER_ROLL_OFF",
            confirmationName,
            nil,
            {
                ui = self,
                controller = runtime.controller,
                link = self.panel.EditBox:GetText(),
                buildKey = buildKey(self.panel.EditBox:GetText()),
                entryID = selected.entryID,
                side = selected.side,
                allowStandardTalentScrolls =
                    self:configuredStandardTalentFallback(),
                specializationGeneration = self.specializationGeneration,
            }
        )
        return true
    end

    function ui:startRollOff(data)
        if self.specializationSettling
            or data.specializationGeneration ~= self.specializationGeneration
            or data.buildKey ~= buildKey(self:draftLink()) then
            self.rollOffSelecting = false
            self:appendLog(
                "rolloff_blocked",
                "That confirmation belongs to an older build or specialization. Analyze and choose again."
            )
            return false
        end
        local result = self:analyze()
        local state = rollOffStateForSide(self.rollOffState, data.side)
        if not result.ok or not state
            or not state.eligibleSet
            or not state.eligibleSet[data.entryID] then
            self.rollOffSelecting = false
            self:renderPlan(result)
            self:refreshButtons()
            self:appendLog(
                "rolloff_blocked",
                "The selected "
                    .. sideNoun(data.side)
                    .. " is no longer eligible. No roll was sent."
            )
            return false
        end
        self.rollOffSelecting = false
        self:commitLink(data.link)
        local ok, reason = data.controller:startRollOffOnce(
            data.link,
            data.side,
            data.entryID,
            data.allowStandardTalentScrolls
        )
        if not ok then
            self:appendLog("rolloff_blocked", reason)
            self:renderPlan(result)
            self:refreshButtons()
            return false
        end
        self.linkInvalidated = false
        self.pendingStop = false
        self.specializationReset = false
        self:renderPlan(result)
        self:refreshButtons()
        return true
    end

    function ui:requestStart()
        self:saveInputs()
        if self.specializationSettling then
            self:appendLog(
                "specialization_waiting",
                "Wait for the new specialization state to finish refreshing before starting."
            )
            return
        end
        local result = self:analyze()
        if not result.ok or not self.lastRecommendation then
            self:appendLog(
                "blocked",
                not result.ok
                    and "Fix the build validation errors before starting."
                    or self.lastSchedule
                        and self.lastSchedule.highRollComplete
                        and self.lastSchedule.reason
                    or "There is no safe reroll to start."
            )
            return
        end
        local highRollFloors = self:configuredHighRollFloors()
        local allowStandardTalentScrolls =
            self:configuredStandardTalentFallback()
        local rollSides = self:configuredRollSides()
        if not rollSides.abilities and not rollSides.talents then
            self:appendLog(
                "blocked",
                "Enable Abilities, Talents, or both before starting."
            )
            return
        end
        showConfirmationPopup(
            self.panel,
            "LAZY_ROLLER_START",
            string.format(
                "Session roll limit: %s. Roll types: %s. %s Standard-scroll talent fallback: %s.",
                normalizeSessionLimit(
                    self.panel.SessionLimitBox:GetText()
                ) or "unlimited",
                rollSideDescription(rollSides),
                highRollDescription(highRollFloors),
                allowStandardTalentScrolls and "enabled" or "disabled"
            ),
            nil,
            {
                ui = self,
                mode = "single",
                link = self.panel.EditBox:GetText(),
                buildKey = buildKey(self.panel.EditBox:GetText()),
                sessionLimit = normalizeSessionLimit(
                    self.panel.SessionLimitBox:GetText()
                ),
                highRollFloors = highRollFloors,
                rollSides = rollSides,
                allowStandardTalentScrolls =
                    allowStandardTalentScrolls,
                specializationGeneration =
                    self.specializationGeneration,
            }
        )
    end

    function ui:requestRapidStart()
        self:saveInputs()
        if self.specializationSettling then
            self:appendLog(
                "specialization_waiting",
                "Wait for the new specialization state to finish refreshing before starting Rapid mode."
            )
            return
        end
        local result = self:analyze()
        if not result.ok then
            self:appendLog(
                "rapid_blocked",
                "Fix the build validation errors before starting Rapid mode."
            )
            return
        end
        local highRollFloors = self:configuredHighRollFloors()
        local allowStandardTalentScrolls =
            self:configuredStandardTalentFallback()
        local rollSides = self:configuredRollSides()
        if not rollSides.abilities and not rollSides.talents then
            self:appendLog(
                "rapid_blocked",
                "Enable Abilities, Talents, or both before starting Rapid mode."
            )
            return
        end
        local projection, projectionError =
            runtime.rapidController:preview(
                self.panel.EditBox:GetText(),
                highRollFloors,
                allowStandardTalentScrolls,
                rollSides
            )
        if not projection then
            self:appendLog("rapid_blocked", projectionError)
            return
        end
        showConfirmationPopup(
            self.panel,
            "LAZY_ROLLER_START_RAPID",
            string.format(
                "Session roll limit: %s. Roll types: %s. %s Standard-scroll talent fallback: %s.",
                normalizeSessionLimit(
                    self.panel.SessionLimitBox:GetText()
                ) or "unlimited",
                rollSideDescription(rollSides),
                highRollDescription(highRollFloors),
                allowStandardTalentScrolls and "enabled" or "disabled"
            ),
            nil,
            {
                ui = self,
                mode = "rapid",
                link = self.panel.EditBox:GetText(),
                buildKey = buildKey(self.panel.EditBox:GetText()),
                sessionLimit = normalizeSessionLimit(
                    self.panel.SessionLimitBox:GetText()
                ),
                highRollFloors = highRollFloors,
                rollSides = rollSides,
                allowStandardTalentScrolls =
                    allowStandardTalentScrolls,
                specializationGeneration =
                    self.specializationGeneration,
            }
        )
    end

    function ui:requestLockSync()
        self:saveInputs()
        if self.specializationSettling then
            self:appendLog(
                "specialization_waiting",
                "Wait for the new specialization state to finish refreshing before synchronizing locks."
            )
            return
        end
        local result = self:analyze()
        if not result.ok then
            self:appendLog(
                "blocked",
                "Fix the build validation errors before synchronizing locks."
            )
            return
        end
        showConfirmationPopup(
            self.panel,
            "LAZY_ROLLER_SYNC_LOCKS",
            nil,
            nil,
            {
                ui = self,
                controller = runtime.controller,
                link = self.panel.EditBox:GetText(),
                buildKey = buildKey(self.panel.EditBox:GetText()),
                specializationGeneration =
                    self.specializationGeneration,
            }
        )
    end

    function ui:onWorldLeaving()
        self.hideGeneration = self.hideGeneration + 1
        self.worldTransition = true
        local restore = self.viewMode
        if restore == "closed" and self.pendingHide then
            restore = "full"
        end
        self.restoreViewAfterWorld = restore
        self.pendingHide = false
    end

    function ui:onWorldEntered()
        local restore = self.restoreViewAfterWorld
        self.worldTransition = false
        self.restoreViewAfterWorld = false
        if restore == "full" and self.panel then
            self:restoreFullPanel()
        elseif restore == "minimized" and self.panel then
            self.viewMode = "minimized"
            self:createTracker()
            self:refreshTracker()
            raise(self.tracker)
            self.tracker:Show()
        end
    end

    function ui:createTracker()
        if _G.LazyRollerTracker then
            self.tracker = _G.LazyRollerTracker
            return self.tracker
        end

        local tracker = CreateFrame(
            "Frame",
            "LazyRollerTracker",
            UIParent
        )
        tracker:SetSize(600, 72)
        tracker:SetPoint("TOP", UIParent, "TOP", 0, -70)
        tracker:SetClampedToScreen(true)
        tracker:EnableMouse(true)
        tracker:SetMovable(true)
        tracker:RegisterForDrag("LeftButton")
        tracker:SetScript("OnDragStart", tracker.StartMoving)
        tracker:SetScript("OnDragStop", tracker.StopMovingOrSizing)
        tracker:SetBackdrop({
            bgFile = "Interface\\DialogFrame\\UI-DialogBox-Background",
            edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
            tile = true,
            tileSize = 16,
            edgeSize = 16,
            insets = { left = 4, right = 4, top = 4, bottom = 4 },
        })
        tracker:SetBackdropColor(0.02, 0.025, 0.035, 0.96)
        tracker:SetBackdropBorderColor(0.35, 0.62, 0.82, 0.96)

        local title = tracker:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontNormal"
        )
        title:SetPoint("TOPLEFT", 13, -11)
        title:SetPoint("TOPRIGHT", -274, -11)
        title:SetJustifyH("LEFT")
        title:SetText("AUTO-ROLL · IDLE")
        tracker.Title = title

        local detail = tracker:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontHighlightSmall"
        )
        detail:SetPoint("TOPLEFT", 13, -34)
        detail:SetPoint("BOTTOMRIGHT", -274, 9)
        detail:SetJustifyH("LEFT")
        detail:SetJustifyV("TOP")
        detail:SetText("No active rolling session.")
        tracker.Detail = detail

        local openButton = addButton(
            tracker,
            "LazyRollerTrackerOpenButton",
            "Open",
            82
        )
        openButton:SetPoint("RIGHT", tracker, "RIGHT", -12, 0)
        openButton:SetScript("OnClick", function()
            self:restoreFullPanel()
        end)
        tracker.OpenButton = openButton

        local pauseButton = addButton(
            tracker,
            "LazyRollerTrackerPauseButton",
            "Pause",
            82
        )
        pauseButton:SetPoint("RIGHT", openButton, "LEFT", -6, 0)
        pauseButton:SetScript("OnClick", function()
            self:requestPauseToggle()
        end)
        tracker.PauseButton = pauseButton

        local reloadRecoveryButton = addButton(
            tracker,
            "LazyRollerTrackerReloadRecoveryButton",
            "Reload",
            82
        )
        reloadRecoveryButton:SetPoint(
            "RIGHT",
            openButton,
            "LEFT",
            -6,
            0
        )
        reloadRecoveryButton:SetScript("OnClick", function()
            self:requestRapidReloadRecovery()
        end)
        reloadRecoveryButton:Hide()
        tracker.ReloadRecoveryButton = reloadRecoveryButton

        local stopButton = addButton(
            tracker,
            "LazyRollerTrackerStopButton",
            "Stop",
            66
        )
        stopButton:SetPoint("RIGHT", tracker, "RIGHT", -12, 0)
        stopButton:SetScript("OnClick", function()
            self:requestStop()
            self:refreshButtons()
        end)
        tracker.StopButton = stopButton

        local closeButton = addButton(
            tracker,
            "LazyRollerTrackerCloseButton",
            "Close",
            82
        )
        closeButton:SetPoint("RIGHT", tracker, "RIGHT", -12, 0)
        closeButton:SetScript("OnClick", function()
            self:closeTracker()
        end)
        tracker.CloseButton = closeButton

        tracker:SetScript("OnHide", function()
            if self.worldTransition or self.viewMode ~= "minimized" then
                return
            end
            self.hideGeneration = self.hideGeneration + 1
            local generation = self.hideGeneration
            self.pendingHide = true
            Timer.After(0, function()
                if generation ~= self.hideGeneration
                    or self.worldTransition
                    or self.viewMode ~= "minimized"
                    or tracker:IsShown() then
                    return
                end
                self.pendingHide = false
                self.viewMode = "closed"
                self:pauseForClosedPanel(
                    "Auto-Roll tracker hidden; no further paid roll will start. Reopen Auto-Roll and press Resume to continue.",
                    "Auto-Roll tracker hidden; the accepted native Rapid batch may finish, but no next batch will start. Reopen Auto-Roll and press Resume.",
                    "Auto-Roll tracker hidden; desired-lock synchronization stopped."
                )
            end)
        end)
        tracker:Hide()
        self.tracker = tracker
        return tracker
    end

    function ui:updateEntrySuggestions(side, query)
        local pane = self.panel and self.panel.PlanPanes
            and self.panel.PlanPanes[side]
        local frame = pane and pane.frame and pane.frame[side .. "Matches"]
        if not frame then
            return
        end
        local matches = fuzzyEntryMatches(side, query, 6)
        local addButton = self.panel.PlanPanes[side].frame[side .. "AddButton"]
        local exactMatches = exactEntryMatches(side, query)
        if addButton then
            addButton:SetText(#exactMatches > 1 and "Add all" or "Add")
        end
        frame.matches = matches
        local shown = 0
        for index = 1, #frame.buttons do
            local button = frame.buttons[index]
            local match = matches[index]
            if match then
                shown = shown + 1
                button:SetText(match.name)
                button:SetScript("OnClick", function()
                    local addBox = pane.frame[side .. "AddBox"]
                    local added = self:addCustomEntry(side, match.id)
                    if added and addBox then
                        addBox:SetText("")
                        addBox:ClearFocus()
                    end
                    self:updateEntrySuggestions(side, "")
                    self:refreshBuildEditor()
                end)
                button:Show()
            else
                button:Hide()
            end
        end
        if shown == 0 then
            frame:Hide()
            return
        end
        frame:SetHeight(shown * 22 + 6)
        frame:Show()
    end

    function ui:createPlanPane(parent, side, width, height)
        local pane = createBox(parent)
        pane:SetSize(width, height)
        local title = pane:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontNormal"
        )
        title:SetPoint("TOPLEFT", 11, -10)
        title:SetPoint("TOPRIGHT", -11, -10)
        title:SetJustifyH("LEFT")
        title:SetText(string.upper(side))

        local addBox = CreateFrame(
            "EditBox",
            "LazyRoller" .. sideTitle(side) .. "AddBox",
            pane,
            "InputBoxTemplate"
        )
        addBox:SetSize(math.max(64, width * 0.28), 20)
        addBox:SetPoint("TOPRIGHT", -11, -8)
        addBox:SetAutoFocus(false)
        addBox:SetMaxLetters(80)
        addBox:SetTextInsets(5, 5, 0, 0)
        styleInputBox(addBox)
        addBox:EnableMouse(true)
        addBox:SetScript("OnTextChanged", function(current)
            self:updateEntrySuggestions(side, current:GetText())
        end)
        addBox:SetScript("OnEnterPressed", function(current)
            local added = self:addCustomEntry(side, current:GetText())
            if added then
                current:SetText("")
            end
            current:ClearFocus()
            self:updateEntrySuggestions(side, "")
            self:refreshBuildEditor()
        end)
        addBox:SetScript("OnEscapePressed", function(current)
            current:ClearFocus()
            self:updateEntrySuggestions(side, "")
        end)
        pane[side .. "AddBox"] = addBox

        local matches = CreateFrame("Frame", nil, pane)
        matches:SetSize(math.max(220, width * 0.38), 28)
        matches:SetPoint("TOPRIGHT", addBox, "BOTTOMRIGHT", 0, -3)
        matches:SetFrameStrata("TOOLTIP")
        matches:SetBackdrop({
            bgFile = "Interface\\ChatFrame\\ChatFrameBackground",
            edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
            tile = true,
            tileSize = 16,
            edgeSize = 12,
            insets = { left = 3, right = 3, top = 3, bottom = 3 },
        })
        matches:SetBackdropColor(0.01, 0.012, 0.016, 0.98)
        matches:SetBackdropBorderColor(0.45, 0.40, 0.25, 0.95)
        matches.buttons = {}
        for index = 1, 6 do
            local matchButton = CreateFrame(
                "Button",
                nil,
                matches,
                "UIPanelButtonTemplate"
            )
            matchButton:SetSize(matches:GetWidth() - 6, 21)
            matchButton:SetPoint("TOPLEFT", 3, -3 - (index - 1) * 22)
            matchButton:Hide()
            matches.buttons[index] = matchButton
        end
        matches:Hide()
        pane[side .. "Matches"] = matches

        local addButton = addButton(
            pane,
            "LazyRoller" .. sideTitle(side) .. "AddButton",
            "Add",
            54
        )
        addButton:SetPoint("RIGHT", addBox, "LEFT", -6, 0)
        addButton:SetScript("OnClick", function()
            addBox:ClearFocus()
            local added = self:addCustomEntry(side, addBox:GetText())
            if added then
                addBox:SetText("")
                self:updateEntrySuggestions(side, "")
            end
            self:refreshBuildEditor()
        end)
        pane[side .. "AddButton"] = addButton

        local buildHint = pane:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontHighlightSmall"
        )
        buildHint:SetPoint("TOPLEFT", 11, -24)
        buildHint:SetPoint("TOPRIGHT", addBox, "TOPLEFT", -6, 0)
        buildHint:SetJustifyH("LEFT")
        buildHint:SetText("")
        pane[side .. "BuildHint"] = buildHint

        local scroll = CreateFrame(
            "ScrollFrame",
            nil,
            pane,
            "UIPanelScrollFrameTemplate"
        )
        scroll:SetPoint("TOPLEFT", 10, -46)
        scroll:SetPoint("BOTTOMRIGHT", -30, 10)
        local child = CreateFrame("Frame", nil, scroll)
        local contentWidth = math.max(100, width - 44)
        local viewHeight = math.max(100, height - 58)
        child:SetWidth(contentWidth)
        child:SetHeight(viewHeight)
        scroll:SetScrollChild(child)

        local empty = child:CreateFontString(
            nil,
            "OVERLAY",
            "GameFontHighlightSmall"
        )
        empty:SetPoint("TOPLEFT", 8, -12)
        empty:SetPoint("TOPRIGHT", -8, -12)
        empty:SetJustifyH("LEFT")
        empty:SetText("Analyze a valid build to populate this list.")

        local result = {
            frame = pane,
            title = title,
            scroll = scroll,
            child = child,
            empty = empty,
            pool = {},
            viewHeight = viewHeight,
            contentWidth = contentWidth,
            bottomPinned = false,
        }
        scroll:HookScript("OnVerticalScroll", function(current, offset)
            if result.adjustingScroll then
                return
            end
            local maximum = current.GetVerticalScrollRange
                and math.max(0, current:GetVerticalScrollRange()) or 0
            local position = offset
                or current.GetVerticalScroll and current:GetVerticalScroll()
                or 0
            result.bottomPinned = maximum > 0
                and position >= maximum - 1
            current.scrollToBottom = result.bottomPinned and true or nil
        end)
        return result
    end

    function ui:createPanel()
        if _G.LazyRollerPanel then
