        edit:SetPoint("TOPRIGHT", analyzeButton, "TOPLEFT", -12, -23)
        edit:SetAutoFocus(false)
        -- v2/v3 links can exceed 8 KiB when the builder carries the inferred
        -- synergy graph. Zero is the WoW EditBox sentinel for no addon-set
        -- byte limit; the previous 8192 cap silently truncated valid links
        -- and made their otherwise-valid JSON fail near the cut boundary.
        edit:SetMaxBytes(0)
