    StaticPopupDialogs["LAZY_ROLLER_SYNC_LOCKS"] = {
        text = "Synchronize locks to this build?\n\nMust-have and learned nice-to-keep entries will be locked. Any X-of-Y categories keep X learned options according to their policy: abilities use build order, while talents use highest rank or build order. Every surplus option will remain unlocked. Missing desired entries cannot be locked.",
        button1 = "Synchronize",
        button2 = CANCEL,
        hideOnEscape = true,
        timeout = 0,
        whileDead = false,
        OnAccept = function(_, data)
            if data.ui.specializationSettling
                or data.specializationGeneration
                    ~= data.ui.specializationGeneration
                or data.buildKey
                    ~= buildKey(data.ui:draftLink()) then
                data.ui:appendLog(
                    "specialization_blocked",
                    "That lock confirmation belongs to an older build or specialization. Review the refreshed plan and try again."
                )
                return
            end
            local ok, reason =
                data.controller:startLockSync(data.link)
            if not ok then
                data.ui:appendLog("sync_error", reason)
            end
            data.ui:refreshButtons()
        end,
    }

    return ui
end

