end)()
local addonName, addon = ...

local READY_TIMEOUT_SECONDS = 2
local READY_SETTLE_SECONDS = 0.25
local UNLEARN_WATCH_SECONDS = 1
local WORLD_SETTLE_SECONDS = 0.25
local WORLD_CONTEXT_TIMEOUT_SECONDS = 5
local SPECIALIZATION_SETTLE_SECONDS = 0.1
local RAPID_UPGRADE_WATCH_SECONDS = 0.05
local worldAvailable = IsLoggedIn and IsLoggedIn() or false
local worldGeneration = 0
local observedSpecializationID = tonumber(
    SpecializationUtil
        and SpecializationUtil.GetActiveSpecialization
        and SpecializationUtil.GetActiveSpecialization()
)
local specializationChangeGeneration = 0
local specializationChangePending = false
local specializationChangeSpecID = nil
local RAPID_FINISH_TIMEOUT_SECONDS = 10
local RAPID_RESTART_SETTLE_SECONDS = 1
local RAPID_CANCEL_RETRY_SECONDS = 0.75
local RAPID_CANCEL_MAX_ATTEMPTS = 3
local RAPID_TRACE_LIMIT = 160
local RAPID_TRACE_SCHEMA = 1
local RAPID_RELOAD_RECOVERY_SCHEMA = 1
local RAPID_RELOAD_RECOVERY_TTL_SECONDS = 120
local rapidReloadInProgress = false
local rapidReloadRecoveryHandled = false

local RAPID_TERMINAL_PHASES = {
    Completed = true,
    Failed = true,
    Cancelled = true,
}

local function nextFrame(callback)
    Timer.After(0, callback)
end

local function requestPendingRoll()
    local ok, reason = C_Wildcard.RollAbilities()
    return ok and true or false, reason
end

local function cancelRapidSession()
    return C_Wildcard.CancelRapidRolling()
end

local function prepareRapidVisual()
    if not WildCard
        or type(WildCard.ClearSoFRoll) ~= "function"
        or not WildCardDice
        or type(WildCardDice.SetRapidRolling) ~= "function"
        or type(WildCardDice.UnregisterOnClick) ~= "function" then
        return false,
            "The native Rapid dice controller is unavailable."
    end

    -- Match WildCardRapidRollingMixin:AttachDice before StartRapidRolling.
    -- isRapidRolling is behavioral, not cosmetic: it suppresses ordinary
    -- dice clicks and makes the native reveal chain force-finish Rapid
    -- results, including the talent-upgrade handoff.
    WildCard:ClearSoFRoll()
    WildCardDice:SetRapidRolling(UIParent)
    WildCardDice:UnregisterOnClick()
    if WildCardDice.RollButton then
        WildCardDice.RollButton:Hide()
    end

    if not WildCardDice.isRapidRolling then
        return false,
            "Ascension did not grant Rapid ownership of the Wildcard dice."
    end
    return true
end

local function cleanupRapidVisual()
    if WildCard then
        WildCard:ClearSoFRoll()
    end
    if WildCardDice then
        WildCardDice:UnregisterOnClick()
        WildCardDice.pendingReveal = nil
        if WildCardDice.RollButton then
            WildCardDice.RollButton:Hide()
        end
        WildCardDice:Hide()
        if WildCardDice.isRapidRolling
            and type(WildCardDice.SetNotRapidRolling) == "function" then
            WildCardDice:SetNotRapidRolling()
        end
    end
end

local function isWildcardActive()
    return C_GameMode
        and type(C_GameMode.IsGameModeActive) == "function"
        and Enum
        and Enum.GameMode
        and C_GameMode:IsGameModeActive(Enum.GameMode.WildCard)
end

local function isStartingChoiceActive()
    local level = UnitLevel and UnitLevel("player")
    if level and level <= 9 then
        return true
    end
    return C_Wildcard
        and type(C_Wildcard.WillRollStartingAbilities) == "function"
        and C_Wildcard.WillRollStartingAbilities()
        or false
end

local SKILL_CARD_TYPES = {
    { "StarterNormal", "SKILL_CARD_STARTER_NORMAL", "starter" },
    { "StarterGolden", "SKILL_CARD_STARTER_GOLDEN", "starter" },
    { "SkillNormal", "SKILL_CARD_DEFAULT_NORMAL", "ability" },
    { "SkillGolden", "SKILL_CARD_DEFAULT_GOLDEN", "ability" },
    { "TalentNormal", "SKILL_CARD_TALENT_NORMAL", "talent" },
    { "TalentGolden", "SKILL_CARD_TALENT_GOLDEN", "talent" },
}

local function getPendingSkillCards()
    if type(C_SkillCard) ~= "table"
        or type(C_SkillCard.GetMaxCardCount) ~= "function"
        or type(C_SkillCard.GetCardAtIndex) ~= "function"
        or type(C_SkillCard.IsCardAtIndexBlocked) ~= "function" then
        return {}
    end
    local pending = {}
    for _, specification in ipairs(SKILL_CARD_TYPES) do
        local enumName, fallbackType, family = unpack(specification)
        local cardType = Enum
            and Enum.SkillCardType
            and Enum.SkillCardType[enumName]
            or fallbackType
        local maximum = tonumber(C_SkillCard.GetMaxCardCount(cardType)) or 0
        for index = 1, maximum do
            local cardID = C_SkillCard.GetCardAtIndex(cardType, index)
            if tonumber(cardID)
                and tonumber(cardID) ~= 0
                and not C_SkillCard.IsCardAtIndexBlocked(cardType, index) then
                pending[#pending + 1] = {
                    cardType = cardType,
                    family = family,
                    index = index,
                    cardID = cardID,
                }
            end
        end
    end
    return pending
end

local function rapidRollingBlock()
    if addon.rapidController and addon.rapidController:isBusy() then
        return "The Rapid auto-roll engine is active or paused."
    end
    if WildCardDice and WildCardDice.isRapidRolling then
        return "Rapid Rolling owns the Wildcard dice."
    end
    if WildCardRapidRollingFrame and WildCardRapidRollingFrame:IsShown() then
        return "Close Rapid Rolling before starting single-roll automation."
    end
    if C_Wildcard
        and type(C_Wildcard.IsAwaitingRapidRollingTalentUpgradeRoll) == "function"
        and C_Wildcard.IsAwaitingRapidRollingTalentUpgradeRoll() then
        return "Rapid Rolling is waiting for a talent-upgrade roll."
    end
    if C_Wildcard
        and type(C_Wildcard.GetRapidRollingState) == "function" then
        local state = C_Wildcard.GetRapidRollingState()
        if state and state.Phase and state.Phase ~= "Idle" then
            return "A Rapid Rolling session is active ("
                .. tostring(state.Phase)
                .. ")."
        end
    end
end

local function singleRollingBlock()
    if addon.controller
        and (
            addon.controller.running
            or addon.controller.paused
            or addon.controller.pendingRoll
            or addon.controller.pendingLockID
            or addon.controller.pendingUnlockID
            or addon.controller.lockSync
        ) then
        return "The single-roll engine or desired-lock synchronization is active."
    end
end

local function combatRollingAllowed()
    return addon.ui
        and type(addon.ui.isCombatRollingAllowed) == "function"
        and addon.ui:isCombatRollingAllowed()
end

local function commonBlockReason(includeReveal, includeCombat, skipRapid)
    if not worldAvailable then
        return "Wait until the loading screen has finished."
    end
    if not isWildcardActive() then
        return "This addon only runs in Wildcard mode."
    end
    if includeCombat
        and UnitAffectingCombat
        and UnitAffectingCombat("player")
        and not combatRollingAllowed() then
        return "Auto-roll can continue in combat only while the minimized tracker is active."
    end
    if isStartingChoiceActive() then
        return "Finish the starting Wildcard choices first."
    end
    local pendingCards = getPendingSkillCards()
    if #pendingCards > 0 then
        return string.format(
            "Use the %d equipped guaranteed Skill Card roll%s before spending ordinary scrolls.",
            #pendingCards,
            #pendingCards == 1 and "" or "s"
        )
    end
    if C_CharacterAdvancement
        and type(C_CharacterAdvancement.IsPending) == "function"
        and C_CharacterAdvancement.IsPending() then
        return "Apply or discard the pending Character Advancement build first."
    end
    if StaticPopup_Visible and StaticPopup_Visible("CONFIRM_UNLEARN_S") then
        return "Close the native unlearn confirmation first."
    end

    if not skipRapid then
        local rapidReason = rapidRollingBlock()
        if rapidReason then
            return rapidReason
        end
    end

    if includeReveal and WildCardDice and WildCardDice:IsShown() then
        if WildCardDice.StartingChoice
            and WildCardDice.StartingChoice:IsShown() then
            return "Finish the starting Wildcard choices first."
        end
        if WildCardDice.pendingReveal then
            return "A Wildcard result is still being received."
        end
        if WildCardDice.RollButton and WildCardDice.RollButton:IsShown() then
            return "Resolve the existing Wildcard result before starting."
        end
    end
end

local function requireRuntime()
    if type(Timer) ~= "table"
        or type(Timer.After) ~= "function"
        or type(GetTime) ~= "function" then
        return "The client next-frame scheduler is unavailable."
    end
    if type(C_CharacterAdvancement) ~= "table" then
        return "Character Advancement APIs are unavailable."
    end
    if type(SpecializationUtil) ~= "table"
        or type(SpecializationUtil.GetActiveSpecialization) ~= "function"
        or type(TokenUtil) ~= "table"
        or type(TokenUtil.GetTokenCount) ~= "function"
        or type(TokenUtil.GetScrollOfFortuneAbilitiesForSpec) ~= "function"
        or type(TokenUtil.GetScrollOfFortuneTalentsForSpec) ~= "function"
        or type(TokenUtil.GetScrollOfFortuneForSpec) ~= "function" then
        return "Specialization scroll APIs are unavailable."
    end
    local required = {
        "GetEntryBySpellID",
        "GetEntryByInternalID",
        "GetInternalID",
        "GetKnownSpells",
        "GetKnownSpellEntries",
        "GetKnownTalentEntries",
        "GetTalentRankByID",
        "IsKnownID",
        "IsLockedID",
        "CanRemoveByEntryID",
        "LockID",
        "UnlockID",
        "UnlearnID",
    }
    for _, method in ipairs(required) do
        if type(C_CharacterAdvancement[method]) ~= "function" then
            return "Required Character Advancement API is missing: "
                .. method
                .. "."
        end
    end
    if type(C_Wildcard) ~= "table"
        or type(C_Wildcard.IsRollRequestBlocked) ~= "function"
        or type(C_Wildcard.CanRollAbilities) ~= "function"
        or type(C_Wildcard.RollAbilities) ~= "function" then
        return "Wildcard reroll state APIs are unavailable."
    end
    if not WildCard
        or type(WildCard.ClearSoFRoll) ~= "function"
        or not WildCardDice
        or type(WildCardDice.UnregisterOnClick) ~= "function" then
        return "The native Wildcard dice controller is unavailable."
    end
end

local function requireRapidRuntime()
    local runtimeError = requireRuntime()
    if runtimeError then
        return runtimeError
    end
    local required = {
        "GetRapidRollingState",
        "StartRapidRolling",
        "CancelRapidRolling",
        "SetRapidRollingSelections",
        "GetMaximumRapidRolls",
        "CanStartRapidRolling",
        "GetNextUnlearnedID",
        "CanAddDesiredID",
        "CanAddUndesiredID",
        "IsAwaitingRapidRollingTalentUpgradeRoll",
    }
    for _, method in ipairs(required) do
        if type(C_Wildcard[method]) ~= "function" then
            return "Required Rapid Rolling API is missing: "
                .. method
                .. "."
        end
    end
    if not WildCardDice
        or type(WildCardDice.SetRapidRolling) ~= "function"
        or type(WildCardDice.SetNotRapidRolling) ~= "function" then
        return "The native Rapid dice lifecycle is unavailable."
    end
end

local function optionalCategoryState(identity, create)
    LazyRollerDB = LazyRollerDB or {}
    identity = tostring(identity or "")
    if LazyRollerDB.optionalCategoryBuildKey ~= identity then
        if not create then
            return
        end
        LazyRollerDB.optionalCategoryBuildKey = identity
        LazyRollerDB.optionalCategories = {
            abilities = {},
            talents = {},
        }
    end
    local state = LazyRollerDB.optionalCategories
    if type(state) ~= "table" then
        if not create then
            return
        end
        state = {}
        LazyRollerDB.optionalCategories = state
    end
    for _, side in ipairs({ "abilities", "talents" }) do
        if type(state[side]) ~= "table" then
            if create then
                state[side] = {}
            else
                return
            end
        end
    end
    return state
end

local function managedLockIdentity()
    local name, unitRealm
    if type(UnitName) == "function" then
        name, unitRealm = UnitName("player")
    end
    local realm = unitRealm
    if (not realm or realm == "") and type(GetRealmName) == "function" then
        realm = GetRealmName()
    end
    return {
        guid = type(UnitGUID) == "function" and UnitGUID("player") or nil,
        name = name,
        realm = realm,
        specID = SpecializationUtil
            and SpecializationUtil.GetActiveSpecialization
            and SpecializationUtil.GetActiveSpecialization() or nil,
    }
end

addon.api = {
