        Timer.After(0.5, callback)
    end,
    getScrollBalances = function()
        local specID = SpecializationUtil.GetActiveSpecialization()
        if not specID then
            return nil, "The active Character Advancement specialization is unavailable."
        end
        return {
            specID = specID,
            abilities = TokenUtil.GetTokenCount(
                TokenUtil.GetScrollOfFortuneAbilitiesForSpec(specID)
            ),
            talents = TokenUtil.GetTokenCount(
                TokenUtil.GetScrollOfFortuneTalentsForSpec(specID)
            ),
            shared = TokenUtil.GetTokenCount(
                TokenUtil.GetScrollOfFortuneForSpec(specID)
            ),
        }
    end,
    getPendingSkillCards = getPendingSkillCards,
    ensureReady = function()
        if isWildcardActive()
            and not IsAddOnLoaded("Ascension_WildCard")
            and type(WildCard_LoadUI) == "function" then
            WildCard_LoadUI()
        end
        local runtimeError = requireRuntime()
        if runtimeError then
            return false, runtimeError
        end
        local blockReason = commonBlockReason(true, true)
        if blockReason then
            return false, blockReason
        end
        if C_Wildcard.CanRollAbilities() then
            return false,
                "Resolve the pending Wildcard die before starting another roll session."
        end
        if C_Wildcard.IsRollRequestBlocked() then
            return false, "The client is still finalizing another Wildcard roll."
        end
        return true
    end,
    ensureContextReady = function()
        if isWildcardActive()
            and not IsAddOnLoaded("Ascension_WildCard")
            and type(WildCard_LoadUI) == "function" then
            WildCard_LoadUI()
        end
        local runtimeError = requireRuntime()
        if runtimeError then
            return false, runtimeError
        end
        local blockReason = commonBlockReason(false, false)
        if blockReason then
            return false, blockReason
        end
        return true
    end,
    ensureRapidReady = function()
        if isWildcardActive()
            and not IsAddOnLoaded("Ascension_WildCard")
            and type(WildCard_LoadUI) == "function" then
            WildCard_LoadUI()
        end
        local runtimeError = requireRapidRuntime()
        if runtimeError then
            return false, runtimeError
        end
        local singleReason = singleRollingBlock()
        if singleReason then
            return false, singleReason
        end
        local blockReason = commonBlockReason(true, true, true)
        if blockReason then
            return false, blockReason
        end
        if C_Wildcard.CanRollAbilities() then
            return false,
                "Resolve the pending Wildcard die before starting another roll session."
        end
        if WildCardRapidRollingFrame
            and WildCardRapidRollingFrame:IsShown() then
            return false, "Close the native Rapid Rolling window first."
        end
        local state = C_Wildcard.GetRapidRollingState()
        if state and state.Phase and state.Phase ~= "Idle" then
            if RAPID_TERMINAL_PHASES[state.Phase] then
                if state.IsActive == false
                    and not C_Wildcard.IsRollRequestBlocked() then
                    return true
                end
                local canStart = C_Wildcard.CanStartRapidRolling()
                if canStart then
                    return true
                end
                cancelRapidSession()
                cleanupRapidVisual()
                return false,
                    "Clearing the previous terminal Rapid session; press Start rapid again after it settles."
            end
            cancelRapidSession()
            cleanupRapidVisual()
            return false,
                "Clearing a previous native Rapid session ("
                    .. tostring(state.Phase)
                    .. "); press Start rapid again after it settles."
        end
        if C_Wildcard.IsRollRequestBlocked() then
            return false,
                "The native Rapid request is still being finalized."
        end
        return true
    end,
    ensureRapidContextReady = function()
        if isWildcardActive()
            and not IsAddOnLoaded("Ascension_WildCard")
            and type(WildCard_LoadUI) == "function" then
            WildCard_LoadUI()
        end
        local runtimeError = requireRapidRuntime()
        if runtimeError then
            return false, runtimeError
        end
        local blockReason = commonBlockReason(false, false, true)
        if blockReason then
            return false, blockReason
        end
        return true
    end,
    getRollBlockReason = function()
        local blockReason = commonBlockReason(true, true)
        if blockReason then
            return blockReason
        end
        if C_Wildcard.IsRollRequestBlocked() then
            return "The client is still finalizing the previous Wildcard roll."
        end
    end,
    isRollRequestBlocked = function()
        return C_Wildcard.IsRollRequestBlocked()
    end,
    canRollAbilities = function()
        return C_Wildcard.CanRollAbilities() and true or false
    end,
    getRapidRecoveryBlockReason = function()
        local singleReason = singleRollingBlock()
        if singleReason then
            return singleReason
        end
        return commonBlockReason(false, true, true)
    end,
    requestPendingRoll = requestPendingRoll,
    requestRapidRecoveryReload = function(checkpoint, trigger)
        return addon.requestRapidRecoveryReload(checkpoint, trigger)
    end,
    cancelRapid = cancelRapidSession,
    getSavedRapidSelections = function()
        local specID = SpecializationUtil.GetActiveSpecialization()
        local function collect(saved)
            local selections = {}
            for entryType, entries in pairs(saved or {}) do
                for entryID, selected in pairs(entries or {}) do
                    if selected then
                        selections[#selections + 1] = {
                            ID = entryID,
                            Type = entryType,
                        }
                    end
                end
            end
            return selections
        end
        return {
            desired = collect(
                RapidRollDesired and RapidRollDesired[specID]
            ),
            undesired = collect(
                RapidRollUndesired and RapidRollUndesired[specID]
            ),
        }
    end,
    setRapidSelections = function(desired, undesired)
        return C_Wildcard.SetRapidRollingSelections(desired, undesired)
    end,
    canAddRapidDesired = function(entryID, entryType)
        return C_Wildcard.CanAddDesiredID(entryID, entryType)
    end,
    canAddRapidUndesired = function(entryID, entryType)
        return C_Wildcard.CanAddUndesiredID(entryID, entryType)
    end,
    getNextRapidUnlearnedID = function()
        return C_Wildcard.GetNextUnlearnedID()
    end,
    getRapidState = function()
        return C_Wildcard.GetRapidRollingState()
    end,
    getMaximumRapidRolls = function()
        return C_Wildcard.GetMaximumRapidRolls()
    end,
    canStartRapid = function()
        return C_Wildcard.CanStartRapidRolling()
    end,
    startRapid = function()
        return C_Wildcard.StartRapidRolling()
    end,
    prepareRapidVisual = prepareRapidVisual,
    isAwaitingRapidTalentUpgrade = function()
        return C_Wildcard.IsAwaitingRapidRollingTalentUpgradeRoll()
    end,
    deferRapidState = function(callback)
        nextFrame(callback)
    end,
    deferRapidUpgradeState = function(callback)
        Timer.After(RAPID_UPGRADE_WATCH_SECONDS, callback)
    end,
    deferRapidSettle = function(callback)
        Timer.After(0.25, callback)
    end,
    watchRapidState = function(callback)
        Timer.After(1, callback)
    end,
    watchRapidUpgradeState = function(callback)
        Timer.After(RAPID_UPGRADE_WATCH_SECONDS, callback)
    end,
    cleanupRapidVisual = function()
        cleanupRapidVisual()
    end,
    finishRapidSession = function(
        callback,
        isCurrent,
        isControllerSuspended
    )
        local deadline = GetTime() + RAPID_FINISH_TIMEOUT_SECONDS
        local attempts = 0
        local nextCancelAt = 0
        local lastCancelReason
        local lastCanStartReason
        local readySince
        local suspendedAt
        local function check()
            if type(isCurrent) == "function" and not isCurrent() then
                return
            end
            local now = GetTime()
            local suspended = not worldAvailable
                or type(isControllerSuspended) == "function"
                    and isControllerSuspended()
            if suspended then
                suspendedAt = suspendedAt or now
                Timer.After(0.05, check)
                return
            end
            if suspendedAt then
                deadline = deadline + math.max(0, now - suspendedAt)
                suspendedAt = nil
            end
            local state = C_Wildcard.GetRapidRollingState()
            local phase = state and state.Phase
            local terminal = phase and RAPID_TERMINAL_PHASES[phase]
            local idle = not phase or phase == "Idle"
            local canStart, canStartReason =
                C_Wildcard.CanStartRapidRolling()
            lastCanStartReason = canStartReason
            local requestBlocked = C_Wildcard.IsRollRequestBlocked()
            -- CanStartRapidRolling also validates the currently projected
            -- Desired/Undesired lists. Those lists can legitimately become
            -- exhausted by the batch that just ended, so a false preflight
            -- does not mean cleanup is still pending. Treat an unblocked Idle
            -- state (or an explicitly inactive terminal state) as released;
            -- the rebuilt projection gets its own CanStart preflight later.
            local terminalReleased = terminal
                and not requestBlocked
                and (
                    state.IsActive == false
                    or canStart
                )
            if (idle and not requestBlocked or terminalReleased)
                and not (terminal and attempts == 0) then
                if not readySince then
                    readySince = now
                elseif now - readySince
                    >= RAPID_RESTART_SETTLE_SECONDS then
                    callback(true)
                    return
                end
            else
                readySince = nil
            end

            -- Ascension's own terminal handler sends one cancellation and
            -- then observes the terminal state. Re-sending Cancel while the
            -- first request is settling can leave the native request latch at
            -- RAPID_ROLLING_REQUEST_IN_FLIGHT even though IsActive is false.
            -- Retries are therefore reserved for a phase that has not yet
            -- become terminal.
            local shouldCancel = (terminal and attempts == 0)
                or (not idle and not terminal)
            if shouldCancel
                and attempts < RAPID_CANCEL_MAX_ATTEMPTS
                and now >= nextCancelAt then
                attempts = attempts + 1
                local ok, reason = cancelRapidSession()
                lastCancelReason = ok and nil or reason
                cleanupRapidVisual()
                readySince = nil
                nextCancelAt = now + RAPID_CANCEL_RETRY_SECONDS
            end
            if GetTime() >= deadline then
                callback(
                    false,
                    string.format(
                        "last phase %s; request blocked %s; can-start reason %s; cancel attempts %d; last cancel reason %s",
                        tostring(phase),
                        tostring(requestBlocked),
                        tostring(
                            _G and _G[lastCanStartReason]
                                or lastCanStartReason
                        ),
                        attempts,
                        tostring(
                            _G and _G[lastCancelReason]
                                or lastCancelReason
                        )
                    )
                )
                return
            end
            Timer.After(0.05, check)
        end
        nextFrame(check)
    end,
    watchUnlearn = function(callback)
        local deadline = GetTime() + UNLEARN_WATCH_SECONDS
        local function check()
            if GetTime() >= deadline then
                callback()
            else
                nextFrame(check)
            end
        end
        nextFrame(check)
    end,
    watchLearn = function(callback)
        local deadline = GetTime() + UNLEARN_WATCH_SECONDS
        local function check()
            if GetTime() >= deadline then
                callback()
            else
                nextFrame(check)
            end
        end
        nextFrame(check)
    end,
    lockID = function(entryID)
        C_CharacterAdvancement.LockID(entryID)
        return true
    end,
    unlockID = function(entryID)
        C_CharacterAdvancement.UnlockID(entryID)
        return true
    end,
    unlearnID = function(entryID)
        return C_CharacterAdvancement.UnlearnID(entryID) and true or false
    end,
    finishReveal = function(
        callback,
        claimTalentUpgradeBonus,
        readyTimeoutSeconds
    )
        readyTimeoutSeconds = tonumber(readyTimeoutSeconds)
            or READY_TIMEOUT_SECONDS
        local function beginFinish()
            if not worldAvailable then
                Timer.After(0.1, beginFinish)
                return
            end
            if not WildCard or not WildCardDice then
                callback(false, "The native Wildcard reveal controller disappeared.")
                return
            end

            WildCard:ClearSoFRoll()
            WildCardDice:UnregisterOnClick()

            local function closeReveal()
                WildCardDice:Hide()
                -- OnHide normally clears this. Keep the automation boundary
                -- explicit because the native frame can immediately reopen.
                WildCardDice.pendingReveal = nil
                if WildCardDice.RollButton then
                    WildCardDice.RollButton:Hide()
                end
            end

            closeReveal()
            local deadline = GetTime() + readyTimeoutSeconds
            local readySince
            local function finishWhenReady()
                if not worldAvailable then
                    readySince = nil
                    Timer.After(0.1, function()
                        deadline = GetTime() + readyTimeoutSeconds
                        finishWhenReady()
                    end)
                    return
                elseif GetTime() >= deadline then
                    callback(
                        false,
                        string.format(
                            "The client did not release the previous Wildcard request within %.2g seconds.",
                            readyTimeoutSeconds
                        )
                    )
                    return
                elseif C_Wildcard.IsRollRequestBlocked() then
                    readySince = nil
                elseif not readySince then
                    readySince = GetTime()
                elseif GetTime() - readySince >= READY_SETTLE_SECONDS then
                    if claimTalentUpgradeBonus then
                        if not C_Wildcard.CanRollAbilities() then
                            callback(
                                false,
                                "The server did not expose the awarded Talent Essence replacement roll."
                            )
                            return
                        end
                        if not requestPendingRoll() then
                            callback(
                                false,
                                "The client rejected the talent-upgrade replacement roll."
                            )
                            return
                        end
                    end
                    callback(true)
                    return
                end
                nextFrame(finishWhenReady)
            end
            finishWhenReady()
        end
        nextFrame(beginFinish)
    end,
}

local function compactTraceValue(value, maximum)
    local text = tostring(value == nil and "nil" or value)
        :gsub("%s+", " ")
    maximum = maximum or 96
    if #text > maximum then
        text = text:sub(1, maximum - 3) .. "..."
    end
    return text
end

local function safeTraceCall(callback, fallback)
    local ok, first, second = pcall(callback)
    if not ok then
        return fallback, compactTraceValue(first)
    end
    return first, second
end

local function ensureRapidTraceStore()
    LazyRollerDB = LazyRollerDB or {}
    if LazyRollerDB.rapidTraceSchema ~= RAPID_TRACE_SCHEMA
        or type(LazyRollerDB.rapidTrace) ~= "table" then
        LazyRollerDB.rapidTraceSchema = RAPID_TRACE_SCHEMA
        LazyRollerDB.rapidTrace = {}
        LazyRollerDB.rapidTraceSequence = 0
    end
    return LazyRollerDB.rapidTrace
end

local function rapidTraceArguments(...)
    local values = {}
    for index = 1, select("#", ...) do
        values[#values + 1] = compactTraceValue(
            select(index, ...),
            72
        )
    end
    return #values > 0 and table.concat(values, ",") or "-"
end

local function rapidTraceState()
    local state = safeTraceCall(function()
        return C_Wildcard
            and C_Wildcard.GetRapidRollingState
            and C_Wildcard.GetRapidRollingState()
    end)
    local rapid = addon.rapidController
        and addon.rapidController:snapshot()
        or {}
    local blocked = safeTraceCall(function()
        return C_Wildcard.IsRollRequestBlocked()
    end)
    local canRoll = safeTraceCall(function()
        return C_Wildcard.CanRollAbilities()
    end)
    local awaitingUpgrade = safeTraceCall(function()
        return C_Wildcard.IsAwaitingRapidRollingTalentUpgradeRoll()
    end)
    local canStart, canStartReason = safeTraceCall(function()
        return C_Wildcard.CanStartRapidRolling()
    end)
    local diceInternal = safeTraceCall(function()
        return WildCardDice
            and WildCardDice.GetInternalID
            and WildCardDice:GetInternalID()
    end)
    local diceCore = safeTraceCall(function()
        return WildCardDice
            and WildCardDice.Core
            and WildCardDice.Core.GetState
            and WildCardDice.Core:GetState()
    end)
    local pendingReveal = WildCardDice
        and WildCardDice.pendingReveal
    if type(pendingReveal) == "table" then
        pendingReveal = pendingReveal[1]
    end

    return table.concat({
        "ctl=" .. compactTraceValue(rapid.phase),
        "run=" .. compactTraceValue(rapid.running),
        "pause=" .. compactTraceValue(rapid.paused),
        "batch=" .. compactTraceValue(rapid.batchActive),
        "side=" .. compactTraceValue(rapid.selectedSide),
        "batches=" .. compactTraceValue(rapid.batches),
        "spent=" .. compactTraceValue(
            rapid.rollsBySide and rapid.rollsBySide.abilities
        ) .. "/" .. compactTraceValue(
            rapid.rollsBySide and rapid.rollsBySide.talents
        ),
        "floor=" .. compactTraceValue(
            rapid.highRollFloors and rapid.highRollFloors.abilities
        ) .. "/" .. compactTraceValue(
            rapid.highRollFloors and rapid.highRollFloors.talents
        ),
        "rollSides=" .. compactTraceValue(
            rapid.rollSides and rapid.rollSides.abilities
        ) .. "/" .. compactTraceValue(
            rapid.rollSides and rapid.rollSides.talents
        ),
        "upgrade=" .. compactTraceValue(
            rapid.upgradeBoundaryActive
        ) .. "/" .. compactTraceValue(
            rapid.upgradeReplacementPending
        ) .. "/" .. compactTraceValue(
            rapid.upgradeReplacementReceived
        ) .. "/" .. compactTraceValue(
            rapid.upgradeReplacementAttempts
        ) .. "/" .. compactTraceValue(
            rapid.upgradeBoundaryWaitChecks
        ) .. "/" .. compactTraceValue(
            rapid.upgradeClaimStableChecks
        ),
        "reload=" .. compactTraceValue(
            rapid.autoReloadEnabled
        ) .. "/" .. compactTraceValue(
            rapid.upgradeReloadReady
        ) .. "/" .. compactTraceValue(
            rapid.reloadRecoveryActive
        ) .. "/" .. compactTraceValue(
            rapid.reloadRecoveryUsed
        ),
        "standardTalent=" .. compactTraceValue(
            rapid.allowStandardTalentScrolls
        ),
        "native=" .. compactTraceValue(state and state.Phase)
            .. "/" .. compactTraceValue(state and state.StopCode),
        "reason=" .. compactTraceValue(state and state.Reason),
        "active=" .. compactTraceValue(state and state.IsActive),
        "session=" .. compactTraceValue(state and state.SessionID),
        "rolls=" .. compactTraceValue(state and state.RollCount),
        "target=" .. compactTraceValue(state and state.TargetEntryID),
        "learned=" .. compactTraceValue(state and state.LearnedEntryID),
        "blocked=" .. compactTraceValue(blocked),
        "canRoll=" .. compactTraceValue(canRoll),
        "helper=" .. compactTraceValue(awaitingUpgrade),
        "canStart=" .. compactTraceValue(canStart)
            .. "/" .. compactTraceValue(canStartReason),
        "dice=" .. compactTraceValue(
            WildCardDice and WildCardDice.IsShown
                and WildCardDice:IsShown()
        ) .. "/" .. compactTraceValue(
            WildCardDice and WildCardDice.isRapidRolling
        ) .. "/" .. compactTraceValue(pendingReveal)
            .. "/" .. compactTraceValue(diceCore)
            .. "/" .. compactTraceValue(diceInternal),
    }, " ")
end

function addon.recordRapidTrace(label, flush, ...)
    local trace = ensureRapidTraceStore()
    LazyRollerDB.rapidTraceSequence =
        (tonumber(LazyRollerDB.rapidTraceSequence) or 0) + 1
    local clock = type(GetTime) == "function" and GetTime() or 0
    local stamp = type(date) == "function"
        and date("%Y-%m-%d %H:%M:%S")
        or "no-wall-clock"
    trace[#trace + 1] = string.format(
        "%04d %s +%.3f %s args=%s %s",
        LazyRollerDB.rapidTraceSequence,
        stamp,
        tonumber(clock) or 0,
        compactTraceValue(label, 80),
        rapidTraceArguments(...),
        rapidTraceState()
    )
    while #trace > RAPID_TRACE_LIMIT do
        table.remove(trace, 1)
    end
    if flush and type(SaveSavedVariables) == "function" then
        SaveSavedVariables(addonName)
    end
end

function addon.flushRapidTrace()
    if type(SaveSavedVariables) == "function" then
        SaveSavedVariables(addonName)
    end
end

function addon.copyRapidTrace()
    addon.recordRapidTrace("copy_requested", false)
    local trace = ensureRapidTraceStore()
    local output = table.concat({
        "Lazy Roller v1.0.6 persistent Rapid trace",
        "Newest record is last. This contains state only, never the build link.",
        table.concat(trace, "\n"),
    }, "\n")
    if type(Internal_CopyToClipboard) ~= "function" then
        return false,
            "Ascension's clipboard function is unavailable; use /lazyroller debug for the current state."
    end
    Internal_CopyToClipboard(output)
    return true, string.format(
        "Copied %d persistent Rapid diagnostic records.",
        #trace
    )
end

local ARCHITECT_GEAR_PREFIX = "architect-gear:1.s10w60"

local function architectBase36(value, allowZero)
    local digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    value = tonumber(value)
    if not value or value < (allowZero and 0 or 1) then
        return allowZero and "0" or nil
    end
    value = math.floor(value)
    if value == 0 then
        return "0"
    end
    local encoded = ""
    repeat
        local remainder = value % 36
        encoded = string.sub(digits, remainder + 1, remainder + 1)
            .. encoded
        value = math.floor(value / 36)
    until value == 0
    return encoded
end

local function architectHex(value)
    local encoded = string.gsub(tostring(value or ""), ".", function(character)
        return string.format("%02x", string.byte(character))
    end)
    return encoded
end

local function architectCleanText(value)
    value = tostring(value or "")
    value = string.gsub(value, "|c%x%x%x%x%x%x%x%x", "")
    value = string.gsub(value, "|r", "")
    value = string.gsub(value, "|T.-|t", "")
    value = string.gsub(value, "|n", " ")
    value = string.gsub(value, "[\r\n]+", " ")
    value = string.gsub(value, "%s+", " ")
    value = string.gsub(value, "^%s+", "")
    value = string.gsub(value, "%s+$", "")
    return value
end

function addon.copyArchitectGear()
    if type(GetInventoryItemLink) ~= "function"
        or type(GetItemInfo) ~= "function" then
        return false, "The client gear APIs are unavailable."
    end
    if type(Internal_CopyToClipboard) ~= "function" then
        return false, "Ascension's clipboard function is unavailable."
    end

    local gear = {}
    for slot = 1, 19 do
        local itemLink = GetInventoryItemLink("player", slot)
        if itemLink then
            local itemString = string.match(itemLink, "|Hitem:([^|]+)|h")
                or string.match(itemLink, "item:([^|]+)")
                or ""
            local itemID = tonumber(string.match(itemString, "^(%d+)"))
            if itemID then
                local itemName, _, quality, itemLevel, _, _, _, _, _, itemTexture =
                    GetItemInfo(itemLink)
                itemName = itemName or string.match(itemLink, "%[(.-)%]")
                    or ("Item " .. tostring(itemID))
                if type(GetInventoryItemTexture) == "function" then
                    itemTexture = GetInventoryItemTexture("player", slot)
                        or itemTexture
                end
                gear[#gear + 1] = table.concat({
                    architectBase36(slot),
                    architectHex(itemString),
                    architectHex(architectCleanText(itemName)),
                    architectBase36(quality or 0, true),
                    architectBase36(itemLevel or 0, true),
                    architectHex(itemTexture or ""),
                    "",
                }, "~")
            end
        end
    end

    if #gear == 0 then
        return false, "No equipped items could be read."
    end

    local name, unitRealm = UnitName("player")
    local realm = unitRealm
    if (not realm or realm == "") and type(GetRealmName) == "function" then
        realm = GetRealmName()
    end
    local token = table.concat({
        ARCHITECT_GEAR_PREFIX,
        tostring(tonumber(UnitLevel("player")) or 0),
        architectHex(architectCleanText(name or "Unknown")),
        architectHex(architectCleanText(realm or "")),
    }, ".") .. "!" .. table.concat(gear, "_")
    local link = "https://architect.nie.one/import#gear=" .. token
    Internal_CopyToClipboard(link)
    return true, string.format(
        "Copied %d equipped items for Ascension Architect.",
        #gear
    )
end

local function recoveryWallTime()
    if type(time) ~= "function" then
        return nil
    end
    return tonumber(time())
end

local function recoveryIdentity()
    local name, unitRealm
    if type(UnitName) == "function" then
        name, unitRealm = UnitName("player")
    end
    local realm = unitRealm
    if (not realm or realm == "")
        and type(GetRealmName) == "function" then
        realm = GetRealmName()
    end
    return {
        guid = type(UnitGUID) == "function"
            and UnitGUID("player") or nil,
        name = name,
        realm = realm,
        specID = SpecializationUtil
            and SpecializationUtil.GetActiveSpecialization
            and SpecializationUtil.GetActiveSpecialization()
            or nil,
    }
end

function addon.validateRapidReloadRecovery(envelope)
    if type(envelope) ~= "table"
        or envelope.schema ~= RAPID_RELOAD_RECOVERY_SCHEMA
        or envelope.kind ~= "rapid_talent_upgrade"
        or type(envelope.checkpoint) ~= "table"
        or envelope.checkpoint.schema ~= 1
        or type(envelope.token) ~= "string"
        or envelope.token == ""
        or (
            envelope.resumeView ~= nil
            and envelope.resumeView ~= "full"
            and envelope.resumeView ~= "minimized"
        )
        or envelope.checkpoint.selectedSide ~= "talents"
        or envelope.checkpoint.ownsSelections ~= true then
        return false, "The saved reload checkpoint has an unknown schema."
    end
    local now = recoveryWallTime()
    local issuedAt = tonumber(envelope.issuedAt)
    if not now or not issuedAt
        or issuedAt > now + 5
        or now - issuedAt > RAPID_RELOAD_RECOVERY_TTL_SECONDS then
        return false, "The saved reload checkpoint is stale."
    end
    local identity = recoveryIdentity()
    if not identity.specID
        or identity.specID ~= envelope.specID then
        return false,
            "The saved reload checkpoint belongs to another specialization."
    end
    if envelope.characterGUID and identity.guid then
        if envelope.characterGUID ~= identity.guid then
            return false,
                "The saved reload checkpoint belongs to another character."
        end
    elseif envelope.characterName ~= identity.name
        or envelope.realmName ~= identity.realm then
        return false,
            "The saved reload checkpoint belongs to another character."
    end
    LazyRollerDB = LazyRollerDB or {}
    if envelope.checkpoint.link ~= LazyRollerDB.link then
        return false,
            "The imported build changed after the reload checkpoint was saved."
    end
    if envelope.trigger == "automatic"
        and not envelope.checkpoint.autoReloadEnabled then
        return false,
            "The checkpoint did not authorize an automatic UI reload."
    end
    return true
end

function addon.requestRapidRecoveryReload(checkpoint, trigger)
    trigger = trigger or "manual"
    if trigger ~= "manual" then
        return false,
            "Ascension requires a player click on a recovery Reload button; asynchronous UI reload was not attempted."
    end
    if type(checkpoint) ~= "table"
        or checkpoint.schema ~= 1
        or checkpoint.selectedSide ~= "talents"
        or checkpoint.ownsSelections ~= true then
        return false, "The Rapid reload checkpoint is invalid."
    end
    if type(SaveSavedVariables) ~= "function" then
        return false,
            "Ascension's SavedVariables flush function is unavailable."
    end
    if type(ReloadUI) ~= "function" then
        return false, "The client UI reload function is unavailable."
    end
    local issuedAt = recoveryWallTime()
    local identity = recoveryIdentity()
    if not issuedAt or not identity.specID
        or not identity.guid or not identity.name or not identity.realm then
        return false,
            "The character identity needed for safe reload recovery is unavailable."
    end
    local checkpointSpecID = tonumber(
        checkpoint.batchStartBalances
            and checkpoint.batchStartBalances.specID
    )
    if not checkpointSpecID
        or checkpointSpecID ~= identity.specID then
        return false,
            "The active specialization changed before reload recovery was requested."
    end

    LazyRollerDB = LazyRollerDB or {}
    LazyRollerDB.link = checkpoint.link
    local resumeView = addon.ui
        and addon.ui.viewMode == "minimized"
        and "minimized"
        or "full"
    LazyRollerDB.rapidReloadRecovery = {
        schema = RAPID_RELOAD_RECOVERY_SCHEMA,
        kind = "rapid_talent_upgrade",
        issuedAt = issuedAt,
        token = table.concat({
            tostring(identity.guid),
            tostring(issuedAt),
            tostring(LazyRollerDB.rapidTraceSequence or 0),
        }, ":"),
        trigger = trigger,
        resumeView = resumeView,
        characterGUID = identity.guid,
        characterName = identity.name,
        realmName = identity.realm,
        specID = identity.specID,
        checkpoint = checkpoint,
    }
    rapidReloadInProgress = true
    addon.recordRapidTrace(
        "rapid_reload_checkpoint_armed",
        false,
        trigger
    )
    SaveSavedVariables(addonName)
    local reloaded, reloadError = pcall(ReloadUI)
    if reloaded then
        return true
    end
    rapidReloadInProgress = false
    LazyRollerDB.rapidReloadRecovery = nil
    SaveSavedVariables(addonName)
    return false, reloadError
end

function addon.discardRapidReloadRecovery(reason)
    LazyRollerDB = LazyRollerDB or {}
    if not LazyRollerDB.rapidReloadRecovery then
        return
    end
    LazyRollerDB.rapidReloadRecovery = nil
    rapidReloadRecoveryHandled = true
    addon.recordRapidTrace(
        "rapid_reload_checkpoint_discarded",
        false,
        reason
    )
    if type(SaveSavedVariables) == "function" then
        SaveSavedVariables(addonName)
    end
    if addon.ui then
        addon.ui:appendLog(
            "rapid_reload_discarded",
            tostring(reason)
        )
    end
end

function addon.resumeRapidReloadRecovery()
    if rapidReloadRecoveryHandled then
        return false, "handled"
    end
    LazyRollerDB = LazyRollerDB or {}
    local envelope = LazyRollerDB.rapidReloadRecovery
    if not envelope then
        return false, "none"
    end
    local valid, validationError =
        addon.validateRapidReloadRecovery(envelope)
    if not valid then
        addon.discardRapidReloadRecovery(validationError)
        return false, "discarded"
    end
    local contextReady, contextError =
        addon.api.ensureRapidContextReady()
    if not contextReady then
        return nil, contextError
    end
    if type(SaveSavedVariables) ~= "function" then
        addon.discardRapidReloadRecovery(
            "Ascension's SavedVariables flush function disappeared after reload."
        )
        return false, "discarded"
    end

    -- Consume and flush the token before restoring controller ownership or
    -- issuing any client mutation. A crash cannot replay this checkpoint.
    local checkpoint = envelope.checkpoint
    local resumeView = envelope.resumeView == "minimized"
        and "minimized"
        or "full"
    LazyRollerDB.rapidReloadRecovery = nil
    rapidReloadRecoveryHandled = true
    SaveSavedVariables(addonName)
    addon.recordRapidTrace(
        "rapid_reload_checkpoint_consumed",
        true,
        envelope.trigger
    )

    if resumeView == "minimized" and addon.ui then
        addon.ui:restoreMinimizedTracker()
    end

    local restored, restoreError =
        addon.rapidController:restoreReloadRecovery(checkpoint)
    if not restored then
        local native = addon.api.getRapidState()
        local phase = native and native.Phase
        local released = not phase
            or phase == "Idle"
            or (
                RAPID_TERMINAL_PHASES[phase]
                and native.IsActive == false
            )
        if released and not addon.api.isRollRequestBlocked()
            and checkpoint.savedSelections then
            addon.api.setRapidSelections(
                checkpoint.savedSelections.desired or {},
                checkpoint.savedSelections.undesired or {}
            )
        end
        addon.recordRapidTrace(
            "rapid_reload_restore_failed",
            true,
            restoreError
        )
        if addon.ui then
            addon.ui:appendLog(
                "rapid_reload_error",
                "The one-shot reload checkpoint could not resume: "
                    .. tostring(restoreError)
            )
        end
        return false, "discarded"
    end
    return true, resumeView
end

LazyRollerDB = LazyRollerDB or {}
LazyRollerDB.talentUpgradeStats = nil
addon.controller = addon.controllerModule.new(
    addon.core,
    addon.api,
    function(kind, text, data, controller)
        if addon.ui then
            addon.ui:onControllerEvent(kind, text, data, controller)
        end
    end
)
addon.rapidController = addon.rapidControllerModule.new(
    addon.core,
    addon.api,
    function(kind, text, data, controller)
        addon.recordRapidTrace(
            "notify:" .. tostring(kind),
            false,
            text
        )
        if addon.ui then
            addon.ui:onControllerEvent(kind, text, data, controller)
        end
    end
)
addon.ui = addon.uiModule.new(addon)

local function createMinimapButton()
    if not Minimap then
        return nil
    end
    if _G.LazyRollerMinimapButton then
        return _G.LazyRollerMinimapButton
    end

    local button = CreateFrame(
        "Button",
        "LazyRollerMinimapButton",
        Minimap
    )
    button:SetSize(32, 32)
    button:SetFrameStrata("MEDIUM")
    button:SetPoint("TOPLEFT", Minimap, "TOPLEFT", -2, 2)
    button:SetHighlightTexture(
        "Interface\\Minimap\\UI-Minimap-ZoomButton-Highlight"
    )

    local icon = button:CreateTexture(nil, "BACKGROUND")
    icon:SetTexture("Interface\\Icons\\INV_Misc_Gear_08")
    icon:SetSize(20, 20)
    icon:SetPoint("CENTER")
    button.Icon = icon

    local border = button:CreateTexture(nil, "OVERLAY")
    border:SetTexture("Interface\\Minimap\\MiniMap-TrackingBorder")
    border:SetSize(54, 54)
    border:SetPoint("CENTER")
    button.Border = border

    button:SetScript("OnClick", function()
        addon.ui:show()
    end)
    button:SetScript("OnEnter", function(current)
        if not GameTooltip then
            return
        end
        GameTooltip:SetOwner(current, "ANCHOR_LEFT")
        GameTooltip:SetText("Lazy Roller")
        GameTooltip:AddLine("Click to open the Auto-Roll window.", 0.75, 0.75, 0.75)
        GameTooltip:Show()
    end)
    button:SetScript("OnLeave", function()
        if GameTooltip then
            GameTooltip:Hide()
        end
    end)
    button:Show()
    return button
end

addon.minimapButton = createMinimapButton()

local eventFrame = CreateFrame("Frame", "LazyRollerEventFrame")
addon.eventFrame = eventFrame

local events = {
    "ADDON_LOADED",
    "PLAYER_LEAVING_WORLD",
    "PLAYER_ENTERING_WORLD",
    "PLAYER_REGEN_DISABLED",
    "CHARACTER_ADVANCEMENT_LOCK_ENTRY_RESULT",
    "WILDCARD_UNLEARN_ABILITY_RESULT",
    "WILDCARD_ROLL_ABILITIES_RESULT",
    "WILDCARD_ENTRY_LEARNED",
    "WILDCARD_RAPID_ROLL_STATE_CHANGED",
    "WILDCARD_RAPID_ROLL_RESULT",
    "WILDCARD_RAPID_ROLL_LEARNED",
    "WILDCARD_RAPID_ROLL_UNLEARNED",
    "ASCENSION_CA_SPECIALIZATION_ACTIVE_ID_CHANGED",
    "PLAYER_SPECIALIZATION_CHANGED",
    "PLAYER_LOGOUT",
}
for _, event in ipairs(events) do
    eventFrame:RegisterEvent(event)
end

local function stopForContextChange(reason)
    if addon.controller.running
        or addon.controller.paused
        or addon.controller.pendingRoll
        or addon.controller.pendingLockID
        or addon.controller.pendingUnlockID then
        addon.controller:stop(reason, "stopped")
    end
    addon.controller:cancelLockSync(reason)
    if addon.rapidController:isBusy() then
        addon.rapidController:stop(reason, "rapid_stopped")
    end
end

local function resetForSpecializationChange(event, ...)
    local eventSpecID = tonumber((...)) or tonumber(
        SpecializationUtil
            and SpecializationUtil.GetActiveSpecialization
            and SpecializationUtil.GetActiveSpecialization()
    )
    local checkpoint = LazyRollerDB
        and LazyRollerDB.rapidReloadRecovery
    local previousSpecID = tonumber(
        addon.controller.scrollsAtStart
            and addon.controller.scrollsAtStart.specID
    ) or tonumber(
        addon.rapidController.scrollsAtStart
            and addon.rapidController.scrollsAtStart.specID
    ) or tonumber(checkpoint and checkpoint.specID)
        or observedSpecializationID

    -- The client can replay the active-specialization event while the UI is
    -- initializing after /reload. That is not a context change and must not
    -- destroy a valid same-spec Rapid recovery checkpoint.
    if not specializationChangePending
        and eventSpecID
        and previousSpecID
        and eventSpecID == previousSpecID then
        observedSpecializationID = eventSpecID
        return false
    end

    specializationChangeGeneration =
        specializationChangeGeneration + 1
    local generation = specializationChangeGeneration
    if eventSpecID then
        specializationChangeSpecID = eventSpecID
    end

    if not specializationChangePending then
        specializationChangePending = true
        local singleHadSession = addon.controller.running
            or addon.controller.paused
            or addon.controller.worldSuspended
            or addon.controller.pendingRoll ~= nil
            or addon.controller.pendingLockID ~= nil
            or addon.controller.pendingUnlockID ~= nil
            or addon.controller.lockSync ~= nil
        local rapidHadSession = addon.rapidController:isBusy()
            or addon.rapidController.upgradeBoundaryActive
            or addon.rapidController.reloadRecoveryActive
        local savedRecovery = LazyRollerDB
            and LazyRollerDB.rapidReloadRecovery ~= nil
        local hadSession = singleHadSession
            or rapidHadSession
            or savedRecovery

        addon.recordRapidTrace(
            "specialization_reset_begin",
            false,
            event,
            specializationChangeSpecID,
            hadSession
        )
        addon.ui:beginSpecializationReset(
            hadSession,
            specializationChangeSpecID
        )
        addon.controller:resetForSpecializationChange(
            "Specialization changed; the previous single-roll session was reset. Review the refreshed plan and explicitly Start again."
        )
        addon.rapidController:resetForSpecializationChange(
            "Specialization changed; the previous Rapid session was reset without restoring its old specialization selections. Review the refreshed plan and explicitly Start again."
        )
        addon.discardRapidReloadRecovery(
            "Specialization changed; the old Rapid reload checkpoint cannot resume in the new specialization."
        )
    end

    -- Ascension itself buckets these two specialization signals for 0.1
    -- seconds before clearing the old dice. Use the same quiet window so the
    -- plan is never analyzed between duplicate events or before the native
    -- per-specialization catalogs/selections have finished refreshing.
    Timer.After(SPECIALIZATION_SETTLE_SECONDS, function()
        if generation ~= specializationChangeGeneration then
            return
        end
        specializationChangePending = false
        local activeSpecID = SpecializationUtil
            and SpecializationUtil.GetActiveSpecialization
            and SpecializationUtil.GetActiveSpecialization()
            or specializationChangeSpecID
        specializationChangeSpecID = activeSpecID
        observedSpecializationID = tonumber(activeSpecID)
            or observedSpecializationID
        addon.recordRapidTrace(
            "specialization_reset_settled",
            false,
            activeSpecID
        )
        addon.ui:completeSpecializationReset(activeSpecID)
    end)
    return true
end

eventFrame:SetScript("OnEvent", function(_, event, ...)
    local traceRapidEvent = event == "WILDCARD_RAPID_ROLL_STATE_CHANGED"
        or event == "WILDCARD_RAPID_ROLL_RESULT"
        or event == "WILDCARD_RAPID_ROLL_LEARNED"
        or event == "WILDCARD_RAPID_ROLL_UNLEARNED"
        or (
            (
                event == "WILDCARD_ROLL_ABILITIES_RESULT"
                or event == "WILDCARD_ENTRY_LEARNED"
            )
            and addon.rapidController:isHandlingUpgradeReplacement()
        )
    local flushRapidTraceAfterEvent = false
    if traceRapidEvent then
        local native = addon.api.getRapidState()
        local stopCode = native and native.StopCode
        local _, _, learnedPreRollRank = ...
        flushRapidTraceAfterEvent =
            event == "WILDCARD_ROLL_ABILITIES_RESULT"
            or event == "WILDCARD_ENTRY_LEARNED"
            or event == "WILDCARD_RAPID_ROLL_LEARNED" and (
                tonumber(learnedPreRollRank) ~= nil
                    and tonumber(learnedPreRollRank) > 0
                or addon.rapidController:isHandlingUpgradeReplacement()
            )
            or (
                type(stopCode) == "string"
                and stopCode:find("TALENT_UPGRADE", 1, true)
            )
        -- Ordinary Rapid learns stay in memory and reach SavedVariables through
        -- the normal client lifecycle. Only the crash-sensitive Talent Essence
        -- overlap forces a synchronous flush after its recovery work is armed.
        addon.recordRapidTrace("event:" .. event, false, ...)
    end
    if event == "ADDON_LOADED" then
        local loadedAddon = ...
        if loadedAddon == addonName
            or loadedAddon == "Ascension_CharacterAdvancement" then
            addon.ui:ensure()
        end
        if loadedAddon == addonName then
            addon.recordRapidTrace("addon_loaded", false, loadedAddon)
            if LazyRollerDB
                and LazyRollerDB.rapidReloadRecovery then
                addon.recordRapidTrace(
                    "rapid_reload_checkpoint_seen",
                    false
                )
            end
        end
    elseif event == "PLAYER_LEAVING_WORLD" then
        if addon.rapidController:isBusy() then
            addon.recordRapidTrace("event:PLAYER_LEAVING_WORLD", false)
            flushRapidTraceAfterEvent = true
        end
        worldGeneration = worldGeneration + 1
        worldAvailable = false
        addon.ui:onWorldLeaving()
        addon.controller:suspendForWorld()
        addon.rapidController:suspendForWorld()
        addon.controller:cancelLockSync(
            "Zoning interrupted desired-lock synchronization; run it again after loading."
        )
    elseif event == "PLAYER_ENTERING_WORLD" then
        worldAvailable = true
        addon.ui:ensure()
        addon.ui:onWorldEntered()
        local enteringGeneration = worldGeneration
        local contextDeadline = GetTime() + WORLD_CONTEXT_TIMEOUT_SECONDS
        local function resumeAfterSettle()
            if not worldAvailable
                or enteringGeneration ~= worldGeneration then
                return
            end
            local recovered, recoveryStatus =
                addon.resumeRapidReloadRecovery()
            if recovered == nil then
                if GetTime() < contextDeadline then
                    Timer.After(WORLD_SETTLE_SECONDS, resumeAfterSettle)
                    return
                end
                addon.discardRapidReloadRecovery(
                    "The addon-initiated reload checkpoint could not regain a valid Wildcard context within five seconds: "
                        .. tostring(recoveryStatus)
                )
            elseif recovered then
                if recoveryStatus ~= "minimized" then
                    addon.ui:show()
                end
                return
            end
            local contextReady
            if addon.rapidController:isBusy() then
                contextReady = addon.api.ensureRapidContextReady()
            else
                contextReady = addon.api.ensureContextReady()
            end
            if not contextReady and GetTime() < contextDeadline then
                Timer.After(WORLD_SETTLE_SECONDS, resumeAfterSettle)
                return
            end
            addon.ui:enforceCombatBoundary()
            addon.controller:resumeAfterWorld()
            addon.rapidController:resumeAfterWorld()
        end
        Timer.After(WORLD_SETTLE_SECONDS, resumeAfterSettle)
    elseif event == "PLAYER_REGEN_DISABLED" then
        addon.ui:enforceCombatBoundary()
    elseif event == "CHARACTER_ADVANCEMENT_LOCK_ENTRY_RESULT" then
        local lockResult, internalID = ...
        if internalID and (
            lockResult == "CA_UNLOCK_OK"
            or not addon.api.isLockedID(internalID)
        ) then
            addon.api.clearManagedAnyLockByEntryID(internalID)
        end
        addon.controller:onLockResult(...)
        addon.rapidController:onLockResult(...)
    elseif event == "WILDCARD_UNLEARN_ABILITY_RESULT" then
        addon.controller:onUnlearnResult(...)
    elseif event == "WILDCARD_ROLL_ABILITIES_RESULT" then
        if not addon.rapidController:onRollAbilitiesResult(...) then
            addon.controller:onRollAbilitiesResult(...)
        end
    elseif event == "WILDCARD_ENTRY_LEARNED" then
        if not addon.rapidController:onEntryLearned(...) then
            addon.controller:onEntryLearned(...)
        end
    elseif event == "WILDCARD_RAPID_ROLL_STATE_CHANGED" then
        addon.rapidController:onRapidStateChanged(...)
    elseif event == "WILDCARD_RAPID_ROLL_RESULT" then
        addon.rapidController:onRapidResult(...)
    elseif event == "WILDCARD_RAPID_ROLL_LEARNED" then
        addon.rapidController:onRapidLearned(...)
    elseif event == "WILDCARD_RAPID_ROLL_UNLEARNED" then
        -- The state event is authoritative; this event is observational.
        addon.rapidController:onRapidStateChanged()
    elseif event == "ASCENSION_CA_SPECIALIZATION_ACTIVE_ID_CHANGED"
        or event == "PLAYER_SPECIALIZATION_CHANGED" then
        resetForSpecializationChange(event, ...)
    elseif event == "PLAYER_LOGOUT" then
        if rapidReloadInProgress
            and LazyRollerDB
            and LazyRollerDB.rapidReloadRecovery then
            addon.recordRapidTrace(
                "event:PLAYER_LOGOUT_SELF_RELOAD",
                true
            )
            return
        end
        if addon.rapidController:isBusy() then
            addon.recordRapidTrace("event:PLAYER_LOGOUT", false)
            flushRapidTraceAfterEvent = true
        end
        stopForContextChange("Logging out; auto-roll stopped.")
    end
    if flushRapidTraceAfterEvent then
        addon.flushRapidTrace()
    end
end)

SLASH_LAZYROLLER1 = "/lazyroller"
SLASH_LAZYROLLER2 = "/s10roll"
SLASH_LAZYROLLER3 = "/lr"
SlashCmdList.LAZYROLLER = function(message)
    local command = tostring(message or ""):match("^%s*(.-)%s*$")
    if command == "debug" then
        local single = addon.controller:snapshot()
        local rapid = addon.rapidController:snapshot()
        local native = addon.api.getRapidState()
        local nativeCanStart, nativeCanStartReason =
            addon.api.canStartRapid()
        local balances = addon.api.getScrollBalances()
        local pendingCards = addon.api.getPendingSkillCards()
        print(string.format(
            "AR single: running %s paused %s phase %s rolls %d limit %s floor A %d / T %d roll A %s / T %s",
            tostring(single.running),
            tostring(single.paused),
            tostring(single.phase),
            tonumber(single.rollsSpent) or 0,
            tostring(single.sessionLimit or "unlimited"),
            tonumber(single.highRollFloors
                and single.highRollFloors.abilities) or 0,
            tonumber(single.highRollFloors
                and single.highRollFloors.talents) or 0,
            tostring(single.rollSides and single.rollSides.abilities),
            tostring(single.rollSides and single.rollSides.talents)
        ))
        print(string.format(
            "AR rapid: running %s paused %s phase %s side %s batches %d spent A %d / T %d limit %s floor A %d / T %d roll A %s / T %s batch %s/%s stall %d upgrade %s pending %s received %s attempt %d wait %d stable %d reload %s/%s/%s/%s diceRapid %s",
            tostring(rapid.running),
            tostring(rapid.paused),
            tostring(rapid.phase),
            tostring(rapid.selectedSide),
            tonumber(rapid.batches) or 0,
            tonumber(rapid.rollsBySide.abilities) or 0,
            tonumber(rapid.rollsBySide.talents) or 0,
            tostring(rapid.sessionLimit or "unlimited"),
            tonumber(rapid.highRollFloors
                and rapid.highRollFloors.abilities) or 0,
            tonumber(rapid.highRollFloors
                and rapid.highRollFloors.talents) or 0,
            tostring(rapid.rollSides and rapid.rollSides.abilities),
            tostring(rapid.rollSides and rapid.rollSides.talents),
            tostring(rapid.batchActive),
            tostring(rapid.batchFinalizing),
            tonumber(rapid.inFlightStateChecks) or 0,
            tostring(rapid.upgradeBoundaryActive),
            tostring(rapid.upgradeReplacementPending),
            tostring(rapid.upgradeReplacementReceived),
            tonumber(rapid.upgradeReplacementAttempts) or 0,
            tonumber(rapid.upgradeBoundaryWaitChecks) or 0,
            tonumber(rapid.upgradeClaimStableChecks) or 0,
            tostring(rapid.autoReloadEnabled),
            tostring(rapid.upgradeReloadReady),
            tostring(rapid.reloadRecoveryActive),
            tostring(rapid.reloadRecoveryUsed),
            tostring(WildCardDice and WildCardDice.isRapidRolling)
        ))
        print(string.format(
            "AR native Rapid: phase %s stop %s next %s projected maximum %s blocked %s upgrade %s canRoll %s canStart %s/%s",
            tostring(native and native.Phase),
            tostring(native and native.StopCode),
            tostring(addon.api.getNextRapidUnlearnedID()),
            tostring(addon.api.getMaximumRapidRolls()),
            tostring(addon.api.isRollRequestBlocked()),
            tostring(addon.api.isAwaitingRapidTalentUpgrade()),
            tostring(addon.api.canRollAbilities()),
            tostring(nativeCanStart),
            tostring(nativeCanStartReason)
        ))
        print(string.format(
            "AR scrolls: ability %s + shared %s / talent %s; pending Skill Cards %d",
            tostring(balances and balances.abilities),
            tostring(balances and balances.shared),
            tostring(balances and balances.talents),
            #pendingCards
        ))
        return
    end
    if command == "trace" then
        local ok, reason = addon.copyRapidTrace()
        print("Lazy Roller: " .. tostring(reason))
        return
    end
    if command == "gear" or command == "export" then
        local ok, reason = addon.copyArchitectGear()
        print("Lazy Roller: " .. tostring(reason))
        return
    end
    addon.ui:show()
end
